import type { FieldDef, FieldUrl, FieldSelect, FieldStringList } from './types';
import { inferFieldsFromObject, inferField } from './infer';
import { resolveResourceBundleDir, buildFieldsFromZodSchema } from './build-editor-rules';
import {
  npcModelDefinitionSchema,
  npcSpawnConfigSchema,
  npcRegionManifestSchema,
  chunkedCollisionManifestSchema,
  chunkedTerrainManifestSchema,
  chunkedLightBlocksManifestSchema,
  chunkedProgramsManifestSchema,
} from '@tencent/viewer-sdk';
import { z } from 'zod';

/**
 * 已知枚举字段表：字段名（小写）→ 下拉选项。
 *
 * 这些字段虽然值是普通字符串，但语义上是**有限枚举**，不应落到自由文本或被
 * `resolveResourceBundleDir` 的字段名正则误判为资源路径（如 `fileType` 含 `file`
 * 会命中 URL_FIELD_PATTERN 被升级成上传控件）。此表优先级高于资源升级。
 */
const ENUM_FIELD_OPTIONS: Record<string, { label: string; value: string }[]> = {
  // GS 场景文件格式（RegionModule.fileType / gaussianSplatting.fileType）
  filetype: [
    { label: 'splat', value: 'splat' },
    { label: 'ksplat', value: 'ksplat' },
    { label: 'ply', value: 'ply' },
    { label: 'spz', value: 'spz' },
    { label: 'sog', value: 'sog' },
  ],
};

/**
 * 资源段字段白名单（region-replace config 内 string[] 资源引用，如 modules[].ply_name /
 * modules[].collision_name）。
 *
 * 这类字段是「相对 config.baseUrl 的资源段数组」，语义上每个元素对应一个本地资源文件，
 * 但字段名不含 url/path/file 等关键词、不命中 resolveResourceBundleDir，故需单独白名单
 * 标记为可上传（resourceUpload），托管模式下每项渲染「上传」按钮落盘到 meta 所在目录。
 */
const RESOURCE_SEG_FIELD_NAMES = new Set(['ply_name', 'collision_name']);

/**
 * 递归遍历字段树，把「字段名命中资源白名单」的叶子字段升级为可上传的 url 控件。
 *
 * infer 产出的树中，叶子字段（text/textarea/url）的 `path` 就是「相对其父作用域的
 * 字段名」（group 的 children 相对 group、array 的 itemSchema 相对 item），因此直接
 * 用 `field.path.toLowerCase()` 查 resolveResourceBundleDir 即可命中白名单，无需拼
 * 父级路径。
 *
 * @param fields 待增强的字段树（通常来自 inferFieldsFromObject）
 * @param hasBaseUrl 该 config 是否含 baseUrl 字段（chunked manifest / region-replace 为 true）。
 *   为 true 时资源字段（url/r16Url/configFile）语义是「相对 baseUrl 的文件名」而非「相对
 *   config 目录的完整相对路径」，故 bundleDir 置空——字段值=文件名、落盘=valueBaseDir(=dirname
 *   +baseUrl)+文件名；为 false（npc legacy 等）保持 bundleDir 前缀（modelFilePath→models/）。
 * @returns 增强后的字段树（原地不变，返回新数组）
 */
function enhanceResourceFields(fields: FieldDef[], hasBaseUrl: boolean): FieldDef[] {
  return fields.map((f) => {
    // group：递归增强 children
    if (f.type === 'group' && f.children) {
      return { ...f, children: enhanceResourceFields(f.children, hasBaseUrl) };
    }
    // array：递归增强 itemSchema（覆盖数组项内资源字段，如 modules[].ply_name）
    if (f.type === 'array' && f.itemSchema) {
      return { ...f, itemSchema: enhanceResourceFields(f.itemSchema, hasBaseUrl) };
    }

    // 叶子字段：先看是否为已知枚举字段（优先级高于资源升级，避免 fileType 被误判为上传）
    if (f.type === 'text' || f.type === 'textarea' || f.type === 'url' || f.type === 'select') {
      const enumOptions = ENUM_FIELD_OPTIONS[f.path.toLowerCase()];
      if (enumOptions) {
        const selectField: FieldSelect = {
          type: 'select',
          path: f.path,
          label: f.label,
          hint: f.hint,
          options: enumOptions,
        };
        return selectField;
      }
    }

    // 叶子字段：命中资源白名单 → 强制升级为 url + bundleDir
    if (f.type === 'text' || f.type === 'textarea' || f.type === 'url') {
      const bundleDir = resolveResourceBundleDir(f.path.toLowerCase());
      if (bundleDir) {
        const urlField: FieldUrl = {
          type: 'url',
          path: f.path,
          label: f.label,
          hint: f.hint,
          urlMode: 'dual',
          // 有 baseUrl：字段值 = 相对 baseUrl 的文件名（不带 models/assets 前缀），
          // 落盘 = valueBaseDir(dirname+baseUrl) + 文件名；无 baseUrl：保持 bundleDir 前缀
          bundleDir: hasBaseUrl ? '' : bundleDir,
        };
        return urlField;
      }
    }

    // string-list：命中资源段白名单（ply_name / collision_name）→ 标记可上传
    if (f.type === 'string-list' && RESOURCE_SEG_FIELD_NAMES.has(f.path.toLowerCase())) {
      const listField: FieldStringList = { ...f, resourceUpload: true };
      return listField;
    }

    return f;
  });
}

/**
 * npc configFile（legacy 形态）顶层 schema —— { models, list }。
 *
 * configFile 文件内容没有独立顶层 schema（SDK 里最接近的 legacyNpcsConfigSchema 含
 * meta 层的 enabled 开关），此处复用已导出的字段级 schema 组合顶层，供 schema 驱动。
 */
const npcConfigFileSchema = z.object({
  models: z.array(npcModelDefinitionSchema).optional(),
  list: z.array(npcSpawnConfigSchema).optional(),
});

/**
 * v1.7.0：chunked manifest schema 按**维度**索引。
 *
 * 为什么不能用末段字段名：`chunkedUrl` 这个字段名在 5 个维度下指向**结构完全不同的**
 * 清单（collision modules[] / terrain modules[]+r16Url / lighting 内联九通道 /
 * programs 内联表 / npcs regions[]），同名不同义 —— 只能按维度消歧。
 */
const CHUNKED_MANIFEST_BY_DIMENSION: Record<string, z.ZodTypeAny> = {
  collision: chunkedCollisionManifestSchema,
  terrain: chunkedTerrainManifestSchema,
  lighting: chunkedLightBlocksManifestSchema,
  programs: chunkedProgramsManifestSchema,
  npcs: npcRegionManifestSchema,
};

/**
 * v1.7.0：按「入口」解析应使用的 SDK zod schema（注册表 + 末段字段名回退）。
 *
 * 取代原 `absPath === 'npcs.configFile'` 硬编码分支。这是「通用多层」的关键：
 * - `configFile`：末段字段名匹配即可 —— L1 `npcs.configFile` 与 L3 `regions[].configFile`
 *   指向**同构文件**（{models, list}，见 npc-region-schema.ts 注释），故同名字段自动复用。
 * - `chunkedUrl`：取路径首段作为维度（`npcs.chunks.chunkedUrl` / `collision.chunkedUrl`
 *   均可得 `npcs` / `collision`），查维度表消歧；维度未知则返回 null 降级 infer。
 *
 * 未命中（regionReplaceConfigPath / mortonConfig 等无 schema 的链路）→ 返回 null，
 * 调用方降级为 infer 数据驱动（符合「没有类型 schema 就靠 infer 推断」）。
 *
 * @param entryPath 入口字段路径（meta 绝对路径如 `npcs.configFile`，或多层下的
 *   `regions[0].configFile`）
 */
export function resolveSchemaByEntry(entryPath?: string): z.ZodTypeAny | null {
  if (!entryPath) return null;
  const normalized = entryPath.toLowerCase();
  const leaf = normalized.slice(normalized.lastIndexOf('.') + 1);

  if (leaf === 'configfile') return npcConfigFileSchema;

  if (leaf === 'chunkedurl') {
    const dimension = normalized.split('.')[0];
    return CHUNKED_MANIFEST_BY_DIMENSION[dimension] ?? null;
  }

  return null;
}

/**
 * 入口是否指向 npc spawn config（{models, list}）—— 决定读入时是否要做老格式 transform 归一化。
 *
 * 为什么必须按 schema/字段名而非路径前缀判定：L3 的 `regions[0].configFile` 不含 `npcs`
 * 前缀，按前缀判定会漏掉第三层的老格式 NPC 数据（平铺 position/rotation/scale 不被
 * 归一化 → infer 认不出 transform → 失去 gizmo，且导出仍是老格式）。
 */
export function isNpcSpawnConfigEntry(entryPath?: string): boolean {
  return resolveSchemaByEntry(entryPath) === npcConfigFileSchema;
}

/**
 * 生成子编辑器的场景表单字段树。
 *
 * 乙-2 schema 驱动（npc configFile）：absPath === 'npcs.configFile' 时走
 * buildFieldsFromZodSchema(npcConfigFileSchema)——字段 100% 由 SDK schema 驱动，枚举转
 * select、transform 转 gizmo、optional 字段占位行（删除后可加回），不再依赖 infer 猜类型。
 *
 * 乙-1 白名单驱动（其余 4 种目录型配置）：沿用 infer 数据驱动 + 骨架补位 + 资源字段增强。
 *
 * @param json 子 json 数据（plain object）
 * @param skeleton 类型骨架（JSON_EDITOR_SKELETONS 同构），乙-1 分支用于把「数据中被删除、
 *   但骨架仍声明的字段」补回字段树作为占位行
 * @param absPath 触发字段的 meta 绝对路径（如 npcs.configFile），用于判定 schema 驱动分支
 * @returns 完整字段树；json 不是 plain object 时返回空数组
 */
export function buildSubEditorRules(
  json: unknown,
  skeleton?: Record<string, unknown>,
  entryPath?: string,
): FieldDef[] {
  if (!json || typeof json !== 'object' || Array.isArray(json)) return [];

  // 乙-2：入口命中 schema 注册表 → schema 驱动（与层级无关，多层同名字段自动复用同一 schema）
  const schema = resolveSchemaByEntry(entryPath);
  if (schema) {
    return buildFieldsFromZodSchema(schema);
  }

  // 乙-1：infer 数据驱动 + 骨架补位 + 资源字段增强
  const inferred = inferFieldsFromObject(json as Record<string, unknown>);
  const merged = skeleton ? mergeSkeletonFields(inferred, skeleton) : inferred;
  // 有 baseUrl 的 config（chunked manifest / region-replace）：资源字段值相对 baseUrl；
  // 无 baseUrl（npc legacy configFile）：资源字段值相对 config 目录
  const hasBaseUrl = !!skeleton && 'baseUrl' in skeleton;
  return enhanceResourceFields(merged, hasBaseUrl);
}

/**
 * 递归把「骨架声明、但数据缺失」的字段补进字段树（占位行）。
 *
 * 对齐关系：字段树的 path 相对各自作用域（group.children 相对 group、array.itemSchema
 * 相对 item），骨架同层级对象结构一一对应，因此按 key 对齐即可。
 *
 * - 已存在字段：array 递归合并 itemSchema、group 递归合并 children（让嵌套删除字段也能恢复）。
 * - 缺失字段：用 inferField 从骨架值推断类型 + 标记 defaultValue（骨架值），经
 *   enhanceResourceFields 后 modelFilePath 等会升级为可上传 url 控件；渲染层 isFieldPresent
 *   为 false → 显示占位行，用户点「添加」写回 defaultValue。
 */
function mergeSkeletonFields(fields: FieldDef[], skeleton: Record<string, unknown>): FieldDef[] {
  const result = fields.map((f) => {
    // array：骨架数组第一项作为 item 的字段定义源，递归合并 itemSchema
    if (f.type === 'array' && f.itemSchema) {
      const skArr = skeleton[f.path];
      const skItem = Array.isArray(skArr) && skArr.length > 0 && isPlainObject(skArr[0]) ? skArr[0] : null;
      if (skItem) return { ...f, itemSchema: mergeSkeletonFields(f.itemSchema, skItem) };
      return f;
    }
    // group：递归合并 children
    if (f.type === 'group' && f.children) {
      const skGroup = skeleton[f.path];
      if (isPlainObject(skGroup)) {
        return { ...f, children: mergeSkeletonFields(f.children, skGroup) };
      }
      return f;
    }
    return f;
  });

  // 骨架声明、字段树缺失的字段 → 补占位字段（defaultValue=骨架值，inferDefaultValue 深拷贝）
  const existing = new Set(fields.map((f) => f.path));
  for (const [key, skValue] of Object.entries(skeleton)) {
    if (existing.has(key)) continue;
    const field = inferField(key, skValue);
    field.defaultValue = skValue;
    result.push(field);
  }
  return result;
}

/** 判断是否 plain object（排除数组 / null） */
function isPlainObject(v: unknown): v is Record<string, unknown> {
  return !!v && typeof v === 'object' && !Array.isArray(v);
}

// ==================== npc transform 统一归一化（v1.5.0） ====================

/**
 * 归一化 npc 子 json 的老格式 spawn 变换（平铺 position/rotation/scale → 合成 transform）。
 *
 * transform 统一前 npc list[] 用平铺 position/rotation/scale（{x,y,z} 对象 / number 标量），
 * 统一后改为 transform（[n,n,n] 三元组数组，对齐 SDK npcSpawnConfigSchema.transform =
 * transformSchema）。编辑已有老 json 时读入即就地归一化：
 * - 使 infer 识别成 transform 控件（gizmo 坐标轴）；
 * - 保存后输出新格式（SDK 消费端已兼容读取，归一化是编辑器侧的「迁移 + 规范化」）。
 *
 * 仅处理 json.list 数组（无 list 的 json 为 no-op，如 chunked manifest）；已含 transform
 * 的新格式元素跳过。
 *
 * @param json 子 json 数据（就地修改）
 */
export function normalizeNpcLegacySpawnTransform(json: Record<string, unknown>): void {
  const list = json.list;
  if (!Array.isArray(list)) return;
  for (const item of list) {
    if (!isPlainObject(item)) continue;
    const spawn = item as Record<string, unknown>;
    // 已是新格式（有 transform 对象）→ 跳过
    if (isPlainObject(spawn.transform)) continue;
    // 无任何老格式字段 → 跳过（空对象等）
    if (!('position' in spawn) && !('rotation' in spawn) && !('scale' in spawn)) continue;

    const pos = normalizeVec3Tuple(spawn.position);
    const rot = normalizeVec3Tuple(spawn.rotation);
    const scaleNum = typeof spawn.scale === 'number' && Number.isFinite(spawn.scale) ? spawn.scale : undefined;

    spawn.transform = {
      position: pos ?? [0, 0, 0],
      rotation: rot ?? [0, 0, 0],
      scale: [scaleNum ?? 1, scaleNum ?? 1, scaleNum ?? 1],
    };
    delete spawn.position;
    delete spawn.rotation;
    delete spawn.scale;
  }
}

/** {x,y,z} 对象 / [n,n,n] 数组 → [n,n,n]（不可识别返回 undefined） */
function normalizeVec3Tuple(v: unknown): [number, number, number] | undefined {
  const toNum = (x: unknown): number => (typeof x === 'number' && Number.isFinite(x) ? x : 0);
  if (Array.isArray(v)) return [toNum(v[0]), toNum(v[1]), toNum(v[2])];
  if (isPlainObject(v)) return [toNum(v.x), toNum(v.y), toNum(v.z)];
  return undefined;
}
