<template>
  <Teleport to="body">
    <Transition name="me-modal">
      <div v-if="visible" class="me-modal-mask meta-editor-scope" @click="onMaskClick">
        <div
          class="me-modal-card"
          :class="`me-modal-${variant}`"
          role="dialog"
          aria-modal="true"
          @click.stop
        >
          <div class="me-modal-header">
            <component :is="iconComp" :size="18" class="me-modal-icon" />
            <div class="me-modal-title">{{ currentOpts.title || '提示' }}</div>
          </div>
          <div class="me-modal-body">{{ currentOpts.message }}</div>
          <div class="me-modal-actions">
            <button class="me-btn" type="button" @click="resolve(false)">
              {{ currentOpts.cancelText || '取消' }}
            </button>
            <button
              ref="okBtnRef"
              class="me-btn me-btn-primary"
              :class="{ danger: variant === 'danger' }"
              type="button"
              @click="resolve(true)"
            >
              {{ currentOpts.okText || '确定' }}
            </button>
          </div>
        </div>
      </div>
    </Transition>
  </Teleport>
</template>

<script lang="ts">
/**
 * 命令式 Confirm 对话框单例。
 *
 * 任意位置 `import { confirmDialog } from './ConfirmDialog.vue'` 调用，返回 Promise<boolean>。
 * 必须在某个组件树挂载一次 `<ConfirmDialog />`（推荐 MetaEditor 根节点）。
 *
 * 设计取舍：
 * - 用 module-level ref 中转，避免引入 reactive 单例 store 的样板代码
 * - 同一时刻只显示一个 dialog（多次 confirmDialog() 调用串行排队）
 *
 * 使用：
 * ```ts
 * const ok = await confirmDialog({
 *   title: '新建项目',
 *   message: '将丢弃当前未保存修改，是否继续？',
 *   variant: 'danger',
 * });
 * if (!ok) return;
 * ```
 */
import { ref } from 'vue';
import {
  AlertTriangle,
  Info,
  HelpCircle,
} from 'lucide-vue-next';

export type ConfirmVariant = 'info' | 'danger' | 'warn';

export interface ConfirmOptions {
  title?: string;
  message: string;
  okText?: string;
  cancelText?: string;
  variant?: ConfirmVariant;
}

interface PendingConfirm {
  opts: ConfirmOptions;
  resolve: (v: boolean) => void;
}

const _queue = ref<PendingConfirm[]>([]);

/** 命令式调用：弹出 confirm 对话框，返回 Promise<boolean> */
export function confirmDialog(opts: ConfirmOptions): Promise<boolean> {
  return new Promise<boolean>((resolve) => {
    _queue.value.push({ opts, resolve });
  });
}

/** 内部钩子：组件 setup 与外部 helpers 共享同一个 ref */
export function _useConfirmQueue() {
  return _queue;
}

const _iconOf = (variant: ConfirmVariant) => {
  switch (variant) {
    case 'danger':
      return AlertTriangle;
    case 'warn':
      return AlertTriangle;
    default:
      return HelpCircle;
  }
};

export { Info, _iconOf };
</script>

<script setup lang="ts">
import { computed, watch, nextTick, onMounted, onBeforeUnmount } from 'vue';

const queue = _useConfirmQueue();
const okBtnRef = ref<HTMLButtonElement | null>(null);

/** 当前正在显示的 confirm（队首） */
const current = computed(() => queue.value[0] || null);
const visible = computed(() => !!current.value);
const currentOpts = computed<ConfirmOptions>(
  () => current.value?.opts || { message: '' },
);
const variant = computed<ConfirmVariant>(() => currentOpts.value.variant || 'info');
const iconComp = computed(() => _iconOf(variant.value));

/** 解析当前队首并出队 */
function resolve(result: boolean) {
  const pending = queue.value.shift();
  if (pending) pending.resolve(result);
}

/** 点击遮罩等同于"取消"（避免用户被卡死） */
function onMaskClick() {
  resolve(false);
}

/** Esc 取消 / Enter 确定（仅当对话框可见时拦截） */
const onKeyDown = (e: KeyboardEvent) => {
  if (!visible.value) return;
  if (e.key === 'Escape') {
    e.preventDefault();
    resolve(false);
  } else if (e.key === 'Enter') {
    e.preventDefault();
    resolve(true);
  }
};

/** 显示后自动聚焦"确定"按钮，方便键盘流回车确认 */
watch(visible, async (v) => {
  if (v) {
    await nextTick();
    okBtnRef.value?.focus();
  }
});

onMounted(() => window.addEventListener('keydown', onKeyDown));
onBeforeUnmount(() => window.removeEventListener('keydown', onKeyDown));
</script>

