<template>
  <div v-if="items.length > 1" class="sub-breadcrumb" role="navigation" aria-label="配置层级">
    <template v-for="(item, index) in items" :key="index">
      <span v-if="index > 0" class="crumb-sep" aria-hidden="true">›</span>
      <button
        class="crumb"
        :class="{ 'is-current': index === items.length - 1 }"
        type="button"
        :disabled="index === items.length - 1"
        :title="item"
        @click="emit('jump', index)"
      >
        {{ item }}
      </button>
    </template>
  </div>
</template>

<script setup lang="ts">
defineProps<{
  /** 配置链各层标题（下标 = 层级；长度 ≤1 时不渲染——单层无需导航） */
  items: string[];
}>();

const emit = defineEmits<{
  /** 点击第 index 层：由编排层 popTo(index) 回跳（当前层按钮已 disabled，不会触发） */
  (e: 'jump', index: number): void;
}>();
</script>

<style scoped>
.sub-breadcrumb {
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
  gap: 2px;
  padding: 0 10px 6px 10px;
  overflow-x: auto;
  /* 细滚动条：层级较深时该行横向滚动，不挤压下方内容区 */
  scrollbar-width: thin;
}

.sub-breadcrumb::-webkit-scrollbar {
  height: 4px;
}

.sub-breadcrumb::-webkit-scrollbar-thumb {
  background: rgba(148, 163, 184, 0.35);
  border-radius: 2px;
}

.crumb-sep {
  flex: 0 0 auto;
  font-size: 11px;
  color: rgba(148, 163, 184, 0.7);
  user-select: none;
}

.crumb {
  flex: 0 0 auto;
  max-width: 140px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 2px 6px;
  border: none;
  border-radius: 4px;
  background: transparent;
  font-size: 11px;
  color: rgba(148, 163, 184, 0.95);
  cursor: pointer;
}

.crumb:hover:not(:disabled) {
  background: rgba(148, 163, 184, 0.14);
  color: rgba(226, 232, 240, 0.98);
}

.crumb.is-current {
  color: rgba(226, 232, 240, 0.98);
  font-weight: 600;
  cursor: default;
}
</style>
