  @changelog
  | 版本   | 变更说明                                                       |
  | v0.2.0 | Vector3 输入：3 列网格 + XYZ 轴色（红绿蓝）+ 内嵌轴标签        |
  | v0.3.0 | 接通 emit('update:values')：编辑后回写父级（双向绑定）         |
  /@changelog

  @author v_weiqinlin
-->
<template>
  <div class="vec3">
    <div v-for="(v, i) in values" :key="i" class="axis-input" :data-axis="axisLabels[i]">
      <span class="axis-tag" :class="`axis-${axisLabels[i].toLowerCase()}`">
        {{ axisLabels[i] }}
      </span>
      <input
        class="axis-num me-mono"
        type="number"
        :value="localStrings[i]"
        :step="step"
        @input="onAxisInput(i, $event)"
      />
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue';

const props = withDefaults(
  defineProps<{
    values: number[];
    labels?: string;
    step?: number;
  }>(),
  { labels: 'X,Y,Z', step: 0.1 },
);

const emit = defineEmits<{
  /** 任一轴变化：emit 完整新数组（保持原数组其它项不变） */
  (e: 'update:values', v: number[]): void;
}>();

const axisLabels = computed(() => props.labels.split(','));

/**
 * 本地缓存输入字符串，允许输入过程中的中间状态（如 "-"、"."）。
 *
 * 受控 `:value` 绑定会在 NaN 时回弹到旧值，导致无法输入负数。
 * 用 localStrings 暂存原始输入，仅在解析为有效数字时才 emit。
 */
const localStrings = ref<string[]>(['0', '0', '0']);

watch(
  () => props.values,
  (vals) => {
    for (let i = 0; i < 3; i++) {
      const v = Number(vals[i] ?? 0);
      // 仅在外部值与本地解析值不一致时同步，避免输入过程中覆盖
      if (Number(localStrings.value[i]) !== v) {
        localStrings.value[i] = String(v);
      }
    }
  },
  { immediate: true, deep: true },
);

const onAxisInput = (axisIdx: number, e: Event) => {
  const raw = (e.target as HTMLInputElement).value;
  localStrings.value[axisIdx] = raw;
  const num = raw === '' ? 0 : Number(raw);
  if (Number.isNaN(num)) return; // 中间状态（如 "-"）暂存但不 emit
  // 复制原数组并替换对应轴
  const next = [
    Number(props.values[0] ?? 0),
    Number(props.values[1] ?? 0),
    Number(props.values[2] ?? 0),
  ];
  next[axisIdx] = num;
  emit('update:values', next);
};
</script>

