/**
 * MetaEditor 是通用 JSON 表单编辑器壳子。
 *
 * 调用方传入：
 * - :value  待编辑的 JSON 数据（任意结构）
 * - :rules  字段→控件 映射规则（可外部注入；缺省走默认规则 + 自动推断）
 *
 * 不传时使用 mockMeta + defaultEditorRules 作为 demo 默认值。
 *
 * **响应式策略**：将 props.value 深拷贝到内部 reactive 副本（meta），
 * 所有添加/移除/编辑都在副本上 mutate，避免污染外部传入的 plain object，
 * 同时让 Vue 能追踪深层属性变化（外部 plain object 的 delete/set 不会触发更新）。
 */
const props = withDefaults(
  defineProps<{
    value?: any;
    rules?: EditorRules;
    useWidgetSchemas?: boolean;
    includeSpecialWidgets?: boolean;
  }>(),

  {
    // 默认进入空白引导态（不再塞 mockMetaJson 让用户误以为是自己的项目）。
    // 用户通过顶栏文件菜单或场景层级面板的引导按钮触发：新建 / 导入 / 加载示例
    value: () => ({}),
    rules: undefined,
    useWidgetSchemas: false,
    includeSpecialWidgets: true,
  },
);

/** 内部响应式数据副本；props.value 变化时同步重置 */
const meta = reactive<Record<string, any>>(deepClone(props.value));
normalizeMeta(meta);

watch(
  () => props.value,
  (newVal) => {
    // 清空旧 keys 再赋新值，保持 reactive 引用稳定
    for (const k of Object.keys(meta)) delete meta[k];
    Object.assign(meta, deepClone(newVal));
    normalizeMeta(meta);
  },
);

const value = computed(() => meta);
const internalRules = computed(() => {
  if (props.includeSpecialWidgets) return zodOnlyEditorRules;
  return buildEditorRules({
    schema: projectConfigSchema as unknown as z.ZodTypeAny,
    mode: 'zod',
    includeSpecialWidgets: props.includeSpecialWidgets,
  });
});
const rules = computed(() => props.rules ?? internalRules.value);

/** 简单深拷贝（mockMeta 是纯 JSON 形态，无 Date/Map/循环引用，足够用） */
function deepClone<T>(v: T): T {
  return v == null ? v : JSON.parse(JSON.stringify(v));
}

/**
 * 对导入 / raw 应用 / 示例数据做安全结构迁移。
 *
 * 已确定升级方向的字段：
 * 1. 旧版 `initial.player.position/rotation` → `initial.player.transform.{position,rotation,scale}`
 * 2. 旧版 InteractionZone 扁平字段 → v2 嵌套格式（geometry/model 分离 + transform 统一）
 *
 * `initial.camera` 等存在语义歧义的历史字段仍不做静默迁移。
 */
function normalizeMeta(m: Record<string, any>): void {
  migratePlayerTransform(m);
  migrateInteractionZones(m);
  normalizeShapeNodes(m);
}

/**
 * unified-shape-trigger-ecs 阶段一：为 interaction zones / audio zones 补齐统一 Shape 节点。
 *
 * 复用 viewer-sdk 的 schema 归一化函数（与 projectConfigSchema 读取行为一致）：
 * - interaction（单个 zone）与 interactionZones（数组/Record）→ normalizeInteractionZoneShape
 * - audio.audioZones → normalizeAudioZone
 *
 * 单向语义：旧 geometry/model（或 center/radius/size）→ 生成 shape；**不回写旧字段**。
 * 编辑器配置层（meta）只保留统一 Shape，geometry/model 由 SDK 渲染副本在读取时回写，
 * 避免导出的配置携带旧字段（二阶段统一 shape 格式）。
 */
function normalizeShapeNodes(m: Record<string, any>): void {
  // interaction（单个 zone）
  if (m.interaction && typeof m.interaction === 'object' && !Array.isArray(m.interaction)) {
    normalizeInteractionZoneShape(m.interaction, false);
  }
  // interactionZones（数组或 Record）
  if (m.interactionZones) {
    const zones = m.interactionZones;
    if (Array.isArray(zones)) {
      zones.forEach((zone: any) => normalizeInteractionZoneShape(zone, false));
    } else if (typeof zones === 'object' && zones !== null) {
      Object.values(zones).forEach((zone: any) => normalizeInteractionZoneShape(zone, false));
    }
  }
  // audio.audioZones
  const audioZones = m.audio?.audioZones;
  if (Array.isArray(audioZones)) {
    audioZones.forEach((zone: any) => normalizeAudioZone(zone, false));
  }
}

function migratePlayerTransform(m: Record<string, any>): void {
  const player = m.initial?.player;
  if (!player || typeof player !== 'object' || Array.isArray(player)) return;

  const transform =
    player.transform && typeof player.transform === 'object' && !Array.isArray(player.transform)
      ? player.transform
      : {};

  const oldPosition = vectorToTuple(player.position, [0, 0, 0]);
  const oldRotation = vectorToTuple(player.rotation, [0, 0, 0]);
  const nextPosition = vectorToTuple(transform.position, oldPosition);
  const nextRotation = vectorToTuple(transform.rotation, oldRotation);
  const nextScale = vectorToTuple(transform.scale, [1, 1, 1]);

  if (player.transform !== transform || player.position !== undefined || player.rotation !== undefined) {
    player.transform = {
      ...transform,
      position: nextPosition,
      rotation: nextRotation,
      scale: nextScale,
    };
    delete player.position;
    delete player.rotation;
  }
}

/**
 * 把旧版 InteractionZone 扁平结构迁移到 v2 嵌套格式。
 *
 * 旧字段 → 新字段映射：
 * - `geometry: [w,h,d]` → `geometry.size: [w,h,d]`
 * - `geometryPos` / `geometryRotation` / `geometryScale` / `geometryTransform` → `geometry.transform.{position,rotation,scale}`
 * - `model: "url"` → `model.url: "url"`
 * - `modelPos` / `rotation` / `scale` / `transform` / `modelTransform` → `model.transform.{position,rotation,scale}`
 *
 * 同时处理 `interaction`（单个 zone）和 `interactionZones`（数组/Record）两种顶层容器。
 * 已是新格式的 zone 原样跳过（geometry 是对象且含 type 字段时视为已迁移）。
 */
function migrateInteractionZones(m: Record<string, any>): void {
  // interaction（单个 zone）
  if (m.interaction) {
    migrateSingleZone(m, 'interaction');
  }
  // interactionZones（数组或 Record）
  if (m.interactionZones) {
    const zones = m.interactionZones;
    if (Array.isArray(zones)) {
      zones.forEach((zone) => migrateZoneObject(zone));
    } else if (typeof zones === 'object' && zones !== null) {
      Object.values(zones).forEach((zone: any) => migrateZoneObject(zone));
    }
  }
}

function migrateSingleZone(m: Record<string, any>, key: string): void {
  const zone = m[key];
  if (!zone || typeof zone !== 'object' || Array.isArray(zone)) return;
  migrateZoneObject(zone);
}

function migrateZoneObject(zone: Record<string, any>): void {
  if (!zone || typeof zone !== 'object' || Array.isArray(zone)) return;

  // ── geometry 迁移 ──
  // 已是新格式（geometry 是对象且含 type）→ 跳过
  const geo = zone.geometry;
  const isGeoNew = geo && typeof geo === 'object' && !Array.isArray(geo) && geo.type !== undefined;
  const hasLegacyGeo =
    !isGeoNew && (Array.isArray(geo) || zone.geometryPos !== undefined || zone.geometryTransform !== undefined);

  if (hasLegacyGeo) {
    const gt = zone.geometryTransform;
    const legacySize = Array.isArray(geo) ? geo : [1, 1, 1];
    zone.geometry = {
      type: 'box',
      size: vectorToTuple(legacySize, [1, 1, 1]),
      transform: {
        position: vectorToTuple(gt?.position ?? zone.geometryPos, [0, 0, 0]),
        rotation: vectorToTuple(gt?.rotation ?? zone.geometryRotation, [0, 0, 0]),
        scale: vectorToTuple(gt?.scale ?? zone.geometryScale, [1, 1, 1]),
      },
    };
    delete zone.geometryPos;
    delete zone.geometryRotation;
    delete zone.geometryScale;
    delete zone.geometryTransform;
  }

  // ── model 迁移 ──
  // 已是新格式（model 是对象且含 url）→ 跳过
  const mdl = zone.model;
  const isModelNew = mdl && typeof mdl === 'object' && !Array.isArray(mdl) && mdl.url !== undefined;
  const hasLegacyModel =
    !isModelNew && (typeof mdl === 'string' || zone.modelPos !== undefined || zone.modelTransform !== undefined);

  if (hasLegacyModel) {
    const mt = zone.modelTransform;
    const legacyTransform = zone.transform;
    zone.model = {
      url: typeof mdl === 'string' ? mdl : '',
      transform: {
        position: vectorToTuple(mt?.position ?? zone.modelPos, [0, 0, 0]),
        rotation: vectorToTuple(mt?.rotation ?? zone.rotation ?? legacyTransform?.rotation, [0, 0, 0]),
        scale: vectorToTuple(mt?.scale ?? zone.scale ?? legacyTransform?.scale, [1, 1, 1]),
      },
    };
    delete zone.modelPos;
    delete zone.modelTransform;
    delete zone.scale;
    delete zone.rotation;
    delete zone.transform;
  }
}

function vectorToTuple(value: unknown, fallback: [number, number, number]): [number, number, number] {
  if (Array.isArray(value)) {
    return [
      numberOrFallback(value[0], fallback[0]),
      numberOrFallback(value[1], fallback[1]),
      numberOrFallback(value[2], fallback[2]),
    ];
  }
  if (value && typeof value === 'object') {
    const v = value as Record<string, unknown>;
    return [numberOrFallback(v.x, fallback[0]), numberOrFallback(v.y, fallback[1]), numberOrFallback(v.z, fallback[2])];
  }
  return fallback;
}

function numberOrFallback(value: unknown, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

const projectName = computed(() => {
  if (Object.keys(meta).length === 0) return '尚未打开项目';
  return value.value?.name || '未命名项目';
});
const activeTab = ref<'scene' | 'raw'>('scene');
const selectedWidgetId = ref<string | null>(null);

/**
 * 侧边栏二级页（JSON 子编辑器）状态。
 *
 * 非 null 时，左侧内容区整体切换为 JsonSubEditorPanel（编辑即生效），
 * 右侧 3D 预览保持可见；底部 LeftSidebar 复用它切「场景/Raw」两种视图（activeTab 驱动）。
 * cfgPath 作为组件 :key，每次打开（含新建切换）都重挂载，保证 draft 从初始 json 干净重建。
 */
/**
 * 多层子编辑器栈（v2.39.0：由单值 SubEditorState 升级而来）。
 *
 * 栈深 = 层级 = 面包屑；每个节点自带 cfgPath / json / skeleton / baseDir / dirty，
 * 取代原「meta 绝对路径 absPath」作为身份——因为第二层以上的路径（如
 * `regions[0].configFile`）根本不在 meta 里，无法用绝对路径标识。
 *
 * 栈长 1 时行为与旧单值实现完全等价（2 层场景零回归）。
 */
const subEditorStack = ref<SubEditorNode[]>([]);

/**
 * 栈顶节点（当前编辑层）；null 表示二级页关闭。
 *
 * 保留 computed 形态（而非重命名全部引用点），使模板与既有逻辑
 * （isSubEditorOpen / editing-config-path / onSubEditorConfigChanged 等）改动最小。
 */
const subEditorState = computed(() => subEditorStack.value[subEditorStack.value.length - 1] ?? null);

/** 面包屑数据：配置链各层标题（长度 = 层级；≤1 时组件不渲染） */
const subEditorCrumbs = computed(() => subEditorStack.value.map((node) => node.title));

/**
 * 子编辑器暴露的回写入口（JsonSubEditorPanel defineExpose）。
 *
 * 用结构化最小接口而非 InstanceType<typeof SFC>：script setup 下暴露类型推断噪声大，
 * 这里只需要两个方法签名。
 */
interface SubEditorExposed {
  /** gizmo 拖拽回写：path 相对 draft 根（如 `list[0].transform`） */
  applyGizmoChange(path: string, channel: 'position' | 'rotation' | 'scale' | 'size', value: number[]): void;
  /** 打点回填：path 相对 draft 根 */
  applyPickPosition(path: string, pos: [number, number, number]): void;
  /**
   * 外部写入字段值（v2.39.0）：非根层「新建子 json」后把新 cfgPath 回填进父层活 draft。
   * 栈节点上的 json 只是备份快照，真正的编辑态在面板 draft 内。
   */
  applyFieldValue(relPath: string, value: unknown): void;
}
const subEditorRef = ref<SubEditorExposed | null>(null);

/**
 * 子编辑器是否处于打开态。
 *
 * 打开期间 gizmo / 打点的回写目标是 draft（相对路径）而非 meta（绝对路径）。
 * 判断依据是 subEditorState（打开前 handleOpenJsonEditor 已 deactivateGizmo()，
 * 且此期间主属性面板不渲染 → 此时激活的 gizmo 必然属于 draft）。
 */
const isSubEditorOpen = (): boolean => subEditorState.value !== null && subEditorRef.value !== null;

/**
 * 托管工作区模式（响应式镜像，供 TopBar 条件渲染菜单 / Ctrl+S 分流）。
 *
 * 底层真相源在 assets-loader 的模块级状态（enterWorkspaceMode/exitWorkspaceMode），
 * 但那是普通 TS 变量，Vue 无法追踪。这里维护一份 ref，在各 enter/exit 调用点同步，
 * 使 TopBar 菜单项与快捷键语义能随模式切换实时更新。
 */
const workspaceMode = ref(false);

/**
 * 被子编辑器编辑过、尚未写回磁盘的内部 json 集合（FileBundle key）。
 *
 * 托管模式下 saveToDisk 遍历此集合，把编辑过的 region-replace / npcs / chunked
 * 清单 json 一并写回磁盘（仅写变更过的，避免全量写盘）。
 *
 * 用 ref 包装使 Vue 可追踪：子 json 编辑不写 meta（内容在 FileBundle），isDirty
 * 需把「dirtyJsonSet 非空」一并纳入，否则顶部 dirty 橙点不会亮。
 */
const dirtyJsonSet = ref(new Set<string>());

/**
 * 目录型引用配置（regionReplaceConfigPath / npcs.configFile）内部资源补读挂起标记。
 * 上传该类 config 后置 true → PreviewPanel.scheduleRebuild 挂起，补读完成置 false →
 * 强制重建一次（避免授权期间失败请求的中间态）。
 */
const configPendingLoad = ref(false);

/** 是否处于"空白引导态"：meta 无任何 key（用户尚未新建/导入/加载示例） */
const isEmptyMeta = computed(() => Object.keys(meta).length === 0);

/**
 * Pristine 快照：表示"上次重置数据时的初始状态"。
 *
 * 在每个会清空/重置 meta 的入口（setMeta）调用后，把当前 meta 序列化为 JSON 字符串保存。
 * 后续每次比较"当前 meta JSON 化后是否与快照一致"得到 isDirty。
 *
 * 用 JSON 字符串而不是对象引用，是为了规避 reactive proxy 的引用稳定性问题，
 * 也避免深比较的性能消耗（JSON 序列化对纯数据足够快）。
 */
const pristineSnapshot = ref<string>(JSON.stringify(meta));

/** 当前 meta 是否相对 pristine 快照有变更（含子编辑器改过的内部 json） */
const isDirty = computed(() => {
  if (isEmptyMeta.value) return false;
  // 子编辑器编辑过内部 json（内容在 FileBundle、不写 meta）也算未保存修改
  if (dirtyJsonSet.value.size > 0) return true;
  // 空字符串 vs '{}' 等价处理
  try {
    return JSON.stringify(meta) !== pristineSnapshot.value;
  } catch {
    return true;
  }
});

/** 当前选中 widget 的规则；找不到时返回 null（PropertyPanel 走 infer 兜底） */
const currentSchema = computed<WidgetSchema | null>(() => {
  if (!selectedWidgetId.value) return null;
  return rules.value.widgets.find((w) => w.id === selectedWidgetId.value) ?? null;
});

// ==================== 布局尺寸（可拖拽 + 持久化） ====================
const LS_KEYS = {
  leftWidth: 'meta-editor.leftWidth',
  treeHeight: 'meta-editor.treeHeight',
};
const LEFT_WIDTH_DEFAULT = 360;
const TREE_HEIGHT_DEFAULT = 320;

const winSize = ref({ w: window.innerWidth, h: window.innerHeight });

const readLS = (k: string, fallback: number): number => {
  try {
    const v = Number(localStorage.getItem(k));
    return Number.isFinite(v) && v > 0 ? v : fallback;
  } catch {
    return fallback;
  }
};
const writeLS = (k: string, v: number) => {
  try {
    localStorage.setItem(k, String(v));
  } catch {
    // ignore
  }
};

const leftWidth = ref(readLS(LS_KEYS.leftWidth, LEFT_WIDTH_DEFAULT));
const treeHeight = ref(readLS(LS_KEYS.treeHeight, TREE_HEIGHT_DEFAULT));

/** 左侧面板最大宽度：窗口宽度的 70%（保留 30% 给预览） */
const leftWidthMax = computed(() => Math.max(400, Math.floor(winSize.value.w * 0.7)));
/** 树面板最大高度：左侧内容区高度 - 120（保证属性面板至少有 120px） */
const treeHeightMax = computed(() => Math.max(200, Math.floor(winSize.value.h * 0.7)));
const treeHeightDefault = TREE_HEIGHT_DEFAULT;

const setLeftWidth = (v: number) => {
  leftWidth.value = v;
  writeLS(LS_KEYS.leftWidth, v);
};
const setTreeHeight = (v: number) => {
  treeHeight.value = v;
  writeLS(LS_KEYS.treeHeight, v);
};

// 监听窗口 resize，避免 leftWidth/treeHeight 超过新的可视范围
const onWinResize = () => {
  winSize.value = { w: window.innerWidth, h: window.innerHeight };
  if (leftWidth.value > leftWidthMax.value) leftWidth.value = leftWidthMax.value;
  if (treeHeight.value > treeHeightMax.value) treeHeight.value = treeHeightMax.value;
};
onMounted(() => {
  window.addEventListener('resize', onWinResize);
  window.addEventListener('beforeunload', onBeforeUnload);
});
onBeforeUnmount(() => {
  window.removeEventListener('resize', onWinResize);
  window.removeEventListener('beforeunload', onBeforeUnload);
});

// ==================== 事件 ====================

const onSwitchTab = (tab: 'scene' | 'raw') => {
  activeTab.value = tab;
};

const onSelectWidget = (id: string) => {
  selectedWidgetId.value = id;
};

/**
 * 选中 widget 时的 gizmo 策略：
 * - 有 transform 字段的 widget → 自动激活所有 transform 的 gizmo（批量操作）
 * - 无 transform 字段 / 未选中 → 关闭所有 gizmo
 */
watch(selectedWidgetId, (id) => {
  if (!id) {
    deactivateGizmo();
    return;
  }
  const entries = collectWidgetGizmoEntries(id);
  if (entries.length > 0) {
    activateGizmoMulti(entries);
  } else {
    deactivateGizmo();
  }
});

/**
 * 选中 widget 时收集所有 transform 的 GizmoEntry。
 *
 * 纯数据驱动：扫描 widget rootPath 下的实际 meta 数据，
 * 找出所有含 position/rotation/scale 的 transform 对象，每个生成独立 gizmo。
 * 不依赖 schema 声明，因此对 infer 兜底字段（npcs.list、models 等）同样有效。
 *
 * Union widget（如 collision 有 legacy/chunked 变体）的 rootPath 为 ''，
 * 需从匹配的 variant 解析有效 rootPath。
 */
function collectWidgetGizmoEntries(widgetId: string): GizmoEntry[] {
  if (widgetId === 'interactionZones') {
    return collectInteractionZoneGizmoEntries();
  }

  const widget = rules.value.widgets.find((w) => w.id === widgetId);
  if (!widget) return [];

  // 解析有效 rootPath
  let rootPath = widget.rootPath || '';
  if (!rootPath && widget.variants?.length) {
    const widgetData = (meta as any)[widgetId];
    const matched = widget.variants.find((v) => v.match?.(widgetData));
    rootPath = matched?.rootPath || widgetId;
  }
  if (!rootPath) return [];

  // 纯数据驱动：扫描 rootPath 下所有 transform
  // （收集器与子编辑器 JsonSubEditorPanel 共用 useGizmoBridge.collectTransformEntries）
  const rootData = getByPath(meta, rootPath);
  if (!rootData || typeof rootData !== 'object') return [];

  return collectTransformEntries(rootData, rootPath);
}

/**
 * 遍历 meta.interactionZones，为每个 zone 收集 transform 的 GizmoEntry。
 * 路径格式与 SchemaRenderer 中 joinPath(basePath, `${field.path}[${i}]`) 一致。
 * 支持数组和 Record 两种格式。
 *
 * v3 统一 Shape 节点：zone 含 shape 时只收集 shape.transform（shape 是权威数据源，
 * geometry/model 仅是兼容镜像，收集会重复且拖拽只改镜像不动 shape 驱动物体）；
 * 无 shape 的旧配置仍收集 geometry.transform + model.transform（向后兼容）。
 */
function collectInteractionZoneGizmoEntries(): GizmoEntry[] {
  const zones = (meta as any).interactionZones;
  if (!zones) return [];

  const entries: GizmoEntry[] = [];

  const collectFromZone = (baseZonePath: string, zone: any): void => {
    const st = zone?.shape?.transform;
    if (st && typeof st === 'object' && zone?.shape?.type) {
      // v3 统一 Shape：shape.transform 是几何（及 triangleMesh 的模型）权威变换
      entries.push(makeGizmoEntry(`${baseZonePath}.shape.transform`, st));
      // 若同时声明了 model（展示模型，transform 为相对 shape 的偏移），保留独立 gizmo 微调
      const mt = zone?.model?.transform;
      if (mt && typeof mt === 'object') {
        entries.push(makeGizmoEntry(`${baseZonePath}.model.transform`, mt));
      }
      return;
    }
    // 旧格式（无 shape）：geometry 碰撞框 + model 展示模型各自独立 gizmo
    const gt = zone?.geometry?.transform;
    if (gt && typeof gt === 'object') {
      entries.push(makeGizmoEntry(`${baseZonePath}.geometry.transform`, gt));
    }
    const mt = zone?.model?.transform;
    if (mt && typeof mt === 'object') {
      entries.push(makeGizmoEntry(`${baseZonePath}.model.transform`, mt));
    }
  };

  if (Array.isArray(zones)) {
    zones.forEach((zone, i) => collectFromZone(`interactionZones[${i}]`, zone));
  } else if (typeof zones === 'object' && zones !== null) {
    // Record 格式：key 是字符串，路径用点号（与 SchemaRenderer joinPath 一致），
    // 不能用方括号 interactionZones[key]——parsePath 只认 [\d+]，
    // 且 isGizmoPathActive 做字符串精确匹配，点号 vs 方括号会对不上。
    for (const [key, zone] of Object.entries(zones)) {
      collectFromZone(`interactionZones.${key}`, zone as any);
    }
  }

  return entries;
}

// 注：v1.6.0 引入的 materializeDefaults（选中 widget 时把 schema 缺失字段写回 meta）
// 在 v1.9.0 被移除——它会污染导入的原始配置（用户的 .json 被静默改动）。
// 替代方案：
// - 属性面板（SchemaRenderer v1.1.0+）按"占位行 vs 编辑控件"区分缺失/已填字段，
//   只有用户主动点"+ 添加"才会真正写入；
// - SDK 渲染需要的兜底由 PreviewPanel.applyRenderDefaults 在 config 副本上做，
//   不影响 meta。

const onAddWidget = (id: string) => {
  const widget = rules.value.widgets.find((w) => w.id === id);
  if (!widget) return;

  // 联合类型 widget：写入第一个 variant 的 defaultSkeleton
  if (widget.variants && widget.variants.length > 0) {
    const firstVariant = widget.variants[0];
    applyVariantSkeleton(id, firstVariant);
    selectedWidgetId.value = id;
    return;
  }

  // 添加策略：按 schema.rootPath 写入一个空骨架，让 SceneTreePanel 的"数据存在"判定通过。
  // - rootPath 含 '.'（如 'initial.camera'）：递归创建中间对象，最终 key 写空字符串占位
  // - rootPath = id：在顶层写一个空对象 {}（数组类的 widget 由属性面板的 emptyDefault 接管真正的初始化）
  // - rootPath = ''（如 camera 这种跨多顶层路径的 widget）：用 visibleInTree 推断需要的最小路径
  const rp = (widget.rootPath || '').trim();

  if (id === 'player') {
    const v = meta as any;
    v.initial = v.initial ?? {};
    v.initial.player =
      v.initial.player && typeof v.initial.player === 'object' && !Array.isArray(v.initial.player)
        ? v.initial.player
        : {};
    v.initial.player.transform = v.initial.player.transform ?? {
      position: [0, 0, 0],
      rotation: [0, 0, 0],
      scale: [1, 1, 1],
    };
    selectedWidgetId.value = id;
    return;
  }

  if (rp.includes('.')) {
    // 嵌套路径：例如 'initial.camera' → 写 meta.initial.camera = ''
    const parts = rp.split('.');
    let cur: any = meta;
    for (let i = 0; i < parts.length - 1; i++) {
      const p = parts[i];
      if (cur[p] == null || typeof cur[p] !== 'object') cur[p] = {};
      cur = cur[p];
    }
    const last = parts[parts.length - 1];
    if (cur[last] === undefined) cur[last] = '';
  } else if (rp) {
    // 顶层路径：写空对象（数组类 widget 的"空状态"由属性面板内的 emptyDefault 按钮处理）
    if ((meta as any)[rp] === undefined) (meta as any)[rp] = {};
  } else {
    // rootPath = ''：camera 这种跨多顶层路径的 widget，按已知的 visibleInTree 语义决定
    if (id === 'camera') {
      const v = meta as any;
      v.initial = v.initial ?? {};
      // 顶层 camera[] 不存在或空 → 写入一份完整默认相机
      if (!Array.isArray(v.camera) || v.camera.length === 0) {
        const def = buildDefaultCamera();
        v.camera = [def];
        // initial.camera 必须是非空字符串才视为合规引用；其他形态（undefined / '' / 旧版对象 /
        // null / 数组）都视为"待迁移"，覆盖为新创建相机的 id。
        // 这正是从旧版结构（initial.camera = CameraConfig 对象）迁移到新版（id 引用）的转换点。
        const cur = v.initial.camera;
        if (typeof cur !== 'string' || cur === '') {
          v.initial.camera = def.id;
        }
      } else {
        // camera[] 已存在
        const cur = v.initial.camera;
        if (typeof cur !== 'string' || cur === '') {
          // 同上：非合规引用 → 覆盖为第一项 id
          v.initial.camera = v.camera[0]?.id ?? '';
        }
      }
    }
  }

  selectedWidgetId.value = id;
};

/**
 * 将 variant 的 defaultSkeleton 写入 meta。
 * skeleton 的 key 是顶层 key（如 { interactionZones: [] }），直接合并到 meta。
 *
 * 切换 Record ↔ Array 时：
 * - 无数据 → 写入骨架（空数组/空对象）
 * - 有数据，类型匹配 → 保留已有数据
 * - 有数据，类型不匹配 → 保留已有数据不覆盖（保存时 checkTypeConflicts 会警告）
 */
function applyVariantSkeleton(_widgetId: string, variant: WidgetVariant) {
  if (!variant.defaultSkeleton) return;
  const v = meta as any;
  for (const [topKey, targetSkeleton] of Object.entries(variant.defaultSkeleton)) {
    const existing = v[topKey];

    // 无数据 → 写入骨架
    if (existing == null) {
      v[topKey] = targetSkeleton;
      continue;
    }

    // 有数据且类型匹配 → 保留已有数据
    const existingIsArray = Array.isArray(existing);
    const targetIsArray = Array.isArray(targetSkeleton);
    if (existingIsArray === targetIsArray) continue;

    // 类型不匹配 → 保留已有数据，不覆盖（编辑器渲染会用 skeleton fallback 显示空结构）
  }
}

/**
 * 用户在属性面板切换联合类型 variant 时触发。
 * 用新 variant 的 defaultSkeleton 覆盖旧数据。
 */
const onVariantSwitch = (widgetId: string, variant: WidgetVariant) => {
  applyVariantSkeleton(widgetId, variant);
  // variant 切换可能写入含 transform 的骨架（如 union widget 从无数据切到有 transform 的 variant），
  // 需重新收集 gizmo 条目。applyVariantSkeleton 直接 mutate meta 不走 onPropertyChange，
  // 且 selectedWidgetId 不变所以 watch 不触发，必须手动重收集。
  if (selectedWidgetId.value === widgetId) {
    const entries = collectWidgetGizmoEntries(widgetId);
    if (entries.length > 0) {
      activateGizmoMulti(entries);
    } else if (activeGizmoEntries.value.length > 0) {
      deactivateGizmo();
    }
  }
};

const onRemoveWidget = (id: string) => {
  const widget = rules.value.widgets.find((w) => w.id === id);
  if (!widget) return;

  const rp = (widget.rootPath || '').trim();

  if (rp.includes('.')) {
    const parts = rp.split('.');
    let cur: any = meta;
    for (let i = 0; i < parts.length - 1; i++) {
      cur = cur?.[parts[i]];
      if (cur == null) return;
    }
    delete cur[parts[parts.length - 1]];
  } else if (rp) {
    delete (meta as any)[rp];
  } else if (id === 'camera') {
    // 跨多顶层路径：camera widget 的可见性来自 `initial.camera` 或顶层 `camera[]`，
    // 所以删除时两处都要清掉，树节点才会真正消失。
    const v = meta as any;
    if (v.initial && 'camera' in v.initial) delete v.initial.camera;
    if (Array.isArray(v.camera) || 'camera' in v) delete v.camera;
  } else {
    const removableTopLevelPaths = Array.from(
      new Set(
        (widget.fields ?? []).map((field) => (field.path || '').trim()).filter((path) => path && !path.includes('.')),
      ),
    );

    if (removableTopLevelPaths.length === 1) {
      removeAtPath(meta, removableTopLevelPaths[0]);
    }
  }

  if (selectedWidgetId.value === id) selectedWidgetId.value = null;
};

/**
 * 当 PropertyPanel 中数据缺失场景被点击"添加默认数据"按钮时触发。
 *
 * 当前为 demo：仅在控制台提示。后续真正接入数据双向绑定时，
 * 应该按 schema.rootPath 在 value 上写入空对象 {}，
 * 让虚拟节点（如 player → initial.player）的属性面板可编辑。
 */
const onAddDefault = () => {
  // eslint-disable-next-line no-console
  console.log('[MetaEditor] add default for:', selectedWidgetId.value, currentSchema.value?.rootPath);
};

// ==================== 双向绑定：属性面板写回 ====================

/**
 * 叶子字段写回：将 absPath 指向的位置就地 mutate 为 value。
 *
 * - value === undefined → 视为删除该 key（用于 group 启用 checkbox 取消勾选等场景）
 * - 其余 → setByPath 写入
 */
const onPropertyChange = (absPath: string, value: unknown): void => {
  if (!absPath) return;

  // v3 统一 Shape 的 resize 回写：PreviewPanel 发 `shape.size`（数组，channel='size'），
  // 按 shape.type 拆分到结构化参数（width/height/depth、radius、outerRadius 等），
  // 再以整个 shape 节点作为变更值写入（避免 `shape.size` 数组残留在 meta）。
  if (absPath.endsWith('.shape.size') && Array.isArray(value)) {
    const shape = getByPath(meta, absPath.replace(/\.size$/, ''));
    const t = shape?.type;
    if (shape && typeof shape === 'object') {
      const s = value as number[];
      switch (t) {
        case 'box':
          shape.width = s[0];
          shape.height = s[1];
          shape.depth = s[2];
          break;
        case 'sphere':
        case 'circle':
          shape.radius = s[0];
          break;
        case 'cylinder':
          shape.radiusTop = s[0];
          shape.radiusBottom = s[1];
          shape.height = s[2];
          break;
        case 'capsule':
          // capsule: [radius, length]（CapsuleGeometry 语义：总高 = length + 2×radius）
          shape.radius = s[0];
          shape.length = s[1];
          break;
        case 'cone':
          shape.radius = s[0];
          shape.height = s[1];
          break;
        case 'plane':
          shape.width = s[0];
          shape.depth = s[1];
          break;
        case 'ring': {
          // ring: innerRadius 为 resize 基准轴（X）。
          // 已存在合法 outerRadius 时按比例跟随（等比缩放，避免覆盖用户手动设置的外半径）；
          // 无 outerRadius 或非法（<= innerRadius）时回退等比 2 倍。
          const prevInner = shape.innerRadius;
          shape.innerRadius = s[0];
          if (typeof shape.outerRadius === 'number' && shape.outerRadius > prevInner && prevInner > 0) {
            shape.outerRadius = shape.outerRadius * (shape.innerRadius / prevInner);
          } else if (!(shape.outerRadius > shape.innerRadius)) {
            shape.outerRadius = Math.max(s[0] * 2, s[0]);
          }
          break;
        }
        case 'torus':
        case 'torusKnot':
          shape.radius = s[0];
          shape.tube = s[1];
          break;
      }
    }
    // 转为 shape 节点整体变更，触发几何重建
    absPath = absPath.replace(/\.shape\.size$/, '.shape');
    value = shape ? getByPath(meta, absPath) : undefined;
  }

  if (value === undefined) {
    removeAtPath(meta, absPath);
  } else {
    setByPath(meta, absPath, value);
  }

  // gizmo 激活时，数值面板改值需同步对应 gizmo 的 proxy 位置。
  // 遍历所有激活的 gizmo 条目，找到路径匹配的并同步。
  for (const entry of activeGizmoEntries.value) {
    if (absPath.startsWith(entry.path + '.')) {
      const transform = getByPath(meta, entry.path);
      if (transform && typeof transform === 'object') {
        const newTransform: GizmoTransform = {
          position: [transform.position?.[0] ?? 0, transform.position?.[1] ?? 0, transform.position?.[2] ?? 0],
          rotation: [transform.rotation?.[0] ?? 0, transform.rotation?.[1] ?? 0, transform.rotation?.[2] ?? 0],
          scale: [transform.scale?.[0] ?? 1, transform.scale?.[1] ?? 1, transform.scale?.[2] ?? 1],
        };
        syncGizmoTransform(entry.path, newTransform);
        // 同步更新 activeGizmoEntries 中对应条目的 transform，
        // 确保 gizmo 下次拖拽时 dragStart.metaTransform 使用正确的基准值，
        // 而非激活时的旧值（否则多次拖拽后 delta 会加到过时的 base 上）。
        activeGizmoEntries.value = activeGizmoEntries.value.map((e) =>
          e.path === entry.path ? { ...e, transform: newTransform } : e,
        );
      }
      break;
    }
  }

  // geometry.type 变更 → 自动调整 size 为该 type 的默认参数。
  // 不同 type 的 size 项数不同（box=3, sphere=1, cone=2...），切换时需重置。
  if (absPath.endsWith('.geometry.type') && typeof value === 'string') {
    const DEFAULT_SIZE: Record<string, number[]> = {
      box: [1, 1, 1],
      sphere: [0.5],
      cylinder: [0.5, 0.5, 1],
      cone: [0.5, 1],
      plane: [1, 1],
      circle: [0.5],
      torus: [0.5, 0.15],
    };
    const defaultSize = DEFAULT_SIZE[value];
    if (defaultSize) {
      const sizePath = absPath.replace(/\.type$/, '.size');
      setByPath(meta, sizePath, defaultSize);
    }
  }

  // geometry.size 或 geometry.type 变更 → 通知 PreviewPanel 就地重建几何体网格。
  // gizmo 激活时 suppressRebuild=true 阻止了 SDK 重建，
  // PreviewPanel 需要直接在场景中替换 Mesh 的 geometry。
  // v3 统一 Shape：shape 节点整体替换（union type 切换）也触发重建，
  // 且 Shape 类型变化时 shape 是权威，gizmo 需重新解析绑定目标（基础形状→geometry、triangleMesh→model）。
  if (absPath.includes('.geometry.size') || absPath.includes('.geometry.type')) {
    notifyGeometryChange(absPath);
  } else if (absPath.includes('.shape')) {
    const isShapeTypeSwitch =
      absPath.endsWith('.shape.type') ||
      (absPath.endsWith('.shape') && value !== undefined && typeof value === 'object' && !Array.isArray(value));
    if (isShapeTypeSwitch) {
      // 等 gizmo 激活态同步后重建几何：通知 PreviewPanel 就地重建 zone 网格
      notifyGeometryChange(absPath.replace(/\.shape(\.type)?$/, ''));
    } else {
      // shape 参数变更（width/height/depth、radius、segments/radialSegments、
      // thickness、torusKnot 的 p/q 等，只要不是 transform 子路径）→ 就地重建几何，
      // 使手动修改数值后预览网格即时生效。
      // transform.position/rotation/scale 由 gizmo 增量同步（不重建几何），需排除。
      const isTransformSubPath = /\.shape\.transform($|\.)/.test(absPath);
      if (!isTransformSubPath) {
        notifyGeometryChange(absPath.split('.shape')[0]);
      }
    }
  }

  // 属性变更可能引入新的 transform 对象（如用户手动添加 geometry 对象），
  // 需重新收集选中 widget 的 gizmo 条目。
  // 仅当变更路径不是已有 gizmo 条目的子路径时才重收集（避免拖拽时频繁重置）。
  // 例外：value === undefined（删除操作）时必须重收集，
  // 因为删除的可能正是 gizmo 条目对应的 transform 对象本身（absPath === entry.path），
  // 此时 isExistingGizmoSubPath 为 true 但数据已不存在，gizmo 应被移除。
  const isExistingGizmoSubPath = activeGizmoEntries.value.some((entry) => {
    if (absPath === entry.path || absPath.startsWith(entry.path + '.')) return true;
    // 同一 geometry/model 对象内的兄弟字段（如 .geometry.type vs .geometry.transform）
    // 视为已存在路径，避免切换 type 时重新激活全部 gizmo
    const entryParent = entry.path.replace(/\.transform$/, '');
    return entryParent !== entry.path && absPath.startsWith(entryParent + '.');
  });
  if ((!isExistingGizmoSubPath || value === undefined) && selectedWidgetId.value) {
    const entries = collectWidgetGizmoEntries(selectedWidgetId.value);
    if (entries.length > 0) {
      // interactionZones 对象格式新增 zone key 时，需等 SDK 重建出对应运行时对象，
      // 否则 PreviewPanel 创建 gizmo 时 sceneTarget=null，只回写数值不更新视觉。
      // 与 onArrayPush 的延迟激活逻辑对齐。
      //
      // v2.18.0：判断从"仅 zone 整体对象"扩展为"zone 整体 / shape / model / geometry
      // 单节点"——新增 shape 字段时 value 是 shape 对象本身（{type,transform}），
      // 原判断 value?.shape?.transform 恒为 undefined → 误判 false → 立即激活 →
      // suppressRebuild 阻止 SDK 重建 zone 网格 → gizmo sceneTarget=null 无法绑定。
      const isNewInteractionZoneKey =
        selectedWidgetId.value === 'interactionZones' &&
        !isExistingGizmoSubPath &&
        value !== undefined &&
        value != null &&
        typeof value === 'object' &&
        !Array.isArray(value) &&
        Boolean(
          (value as any)?.geometry?.transform ||
          (value as any)?.model?.transform ||
          (value as any)?.shape?.transform ||
          // 添加 shape / model / geometry 单节点：value 自身携带 transform
          (value as any)?.transform,
        );

      if (isNewInteractionZoneKey) {
        const beforeSdk = sdkRef.value;
        const beforeCounter = sceneReadyCounter.value;
        deactivateGizmo();
        void (async () => {
          await nextTick();
          await waitForSdkRefresh(beforeSdk, beforeCounter);
          if (selectedWidgetId.value) {
            const newEntries = collectWidgetGizmoEntries(selectedWidgetId.value);
            if (newEntries.length > 0) {
              activateGizmoMulti(newEntries);
            }
          }
        })();
      } else {
        activateGizmoMulti(entries);
      }
    } else if (activeGizmoEntries.value.length > 0) {
      deactivateGizmo();
    }
  }

  // v2.14.0：属性面板手动上传"目录型引用配置"后，config 内部引用的资源尚未登记到
  // FileBundle → 预览改写保留相对路径 → SDK 拼出无效 blob URL 加载失败。此处检测到
  // 该类字段（v2.20.0：regionReplace / npcs.configFile / collision / terrain / npcs 的
  // chunkedUrl，注册表 DIRECTORY_CONFIG_FIELD_MAP）设为本地路径时，弹授权引导补读内部资源。
  if (resolveDirectoryExtractor(absPath) && typeof value === 'string' && value && FileBundle.isLocalPath(value)) {
    // v2.16.0：挂起重建直到内部资源补读完成——避免授权期间 SDK 用未登记资源的
    // 相对路径拼出无效 blob URL（ERR_FILE_NOT_FOUND）先失败请求一次。
    void runPendingConfigLoadByPath(absPath, value);
  }
};

/**
 * v2.16.0：目录型配置内部资源补读的挂起重建管理。
 *
 * config 上传（onPropertyChange 写入 value）后，PreviewPanel 的 watch 会在下一 tick 触发
 * rebuild——此时 config 内部资源尚未登记，改写保留相对路径导致失败请求。这里先将
 * configPendingLoad 置 true（PreviewPanel.scheduleRebuild 挂起全部重建），再执行授权补读，
 * finally 中置 false 触发一次强制重建（FileBundle 已填充，改写全部命中）。
 *
 * 用户取消授权同样会重置挂起并重建——此时资源未登记，SDK 按真实相对路径尝试加载（
 * 与未授权导入一致的行为），并保留上一轮 console.warn 指引。
 */
async function runPendingConfigLoad(node: SubEditorNode): Promise<void> {
  configPendingLoad.value = true;
  try {
    await promptLoadReferencedConfigAssets(node);
  } finally {
    configPendingLoad.value = false;
  }
}

/**
 * 根层路径式补读包装（属性面板上传配置后调用，语义与旧实现完全一致）。
 *
 * 构造一个 parentCfgPath=null 的临时节点走同一条补读链路——避免为根层维护第二套实现。
 */
async function runPendingConfigLoadByPath(absPath: string, cfgPath: string): Promise<void> {
  await runPendingConfigLoad({
    cfgPath,
    parentCfgPath: null,
    fieldPathInParent: absPath,
    entryFieldName: absPath.split('.').pop() || '',
    title: '',
    json: {},
    // 根层基准：非 chunked → dirname(cfgPath)；chunked 走精确提取器（内部自读 manifest.baseUrl），
    // baseDir 仅供通用扫描兜底使用
    baseDir: resolveNodeBaseDir({ cfgPath, entryFieldName: absPath.split('.').pop() || '', json: {} }),
    dirty: false,
  });
}

/**
 * v2.28.0：目录型配置字段的「JSON 子编辑器」默认文件名（按字段语义）。
 *
 * 新建空白 json 时，用 uniquePath(bundleDir, 默认名) 生成不冲突路径并回填字段值。
 * 编辑已有本地 json 时覆盖同 key，不改变文件名。
 */
const JSON_EDITOR_DEFAULT_FILENAMES: Record<string, string> = {
  regionreplaceconfigpath: 'region-replace-config.json',
  configfile: 'npc-config.json',
  chunkedurl: 'manifest.json',
};

/**
 * v2.30.0：各目录型配置字段「新建」时的默认骨架（按 meta 绝对路径映射）。
 *
 * 背景：子编辑器是「纯推断」驱动（乙-1），新建时若给空 {} 则推断不出任何字段，
 * 二级页显示「空配置」——用户新建后什么都看不到。骨架为每个类型预置顶层字段 +
 * 一个空元素数组项（数组必须带 1 个元素，infer 才能从元素推断出 itemSchema，
 * 否则空数组落入 auto-object 空态），让用户新建后直接看到完整字段结构并编辑。
 *
 * 字段严格对齐 viewer-sdk 的 TS interface / zod schema（types/gs.ts / types/npc.ts /
 * gs.schema.ts / npc-region-schema.ts），遵循以下原则：
 * 1. 必填字段全部列出（如 chunked manifest 的 loadConfig、RegionModule 的 id/name/url/
 *    mortonConfig/transform/bounds）。
 * 2. 常见可选字段列出（morton/switchConfig/collision_name/isDefault/unloadable/modelFilePath/
 *    rotation），罕见/纯内部可选字段省略（gsInfo/opacity/cloneAsLightMesh/uvRegion/r16Url/
 *    globalModels），避免骨架臃肿。
 * 3. 运行时生成字段不手写：RegionModule.url 由策略层在 loadRegionReplaceConfig 中根据
 *    ply_name 解析生成（gs.ts:137 注释），用户手写 config 不含 url——TS 里 url 必填描述的是
 *    「运行时完整形态」而非「手写文件形态」，故骨架省略 url。
 * 4. 数组字段必带 1 个空模板元素（infer 才能推断 itemSchema）；标量用空串/0（scale=1 因
 *    缩放中性值、chunk size=10 因 npcSizeTuple 需正数）。
 */
const JSON_EDITOR_SKELETONS: Record<string, Record<string, unknown>> = {
  // RegionReplaceConfig（gs.ts:178-194）：baseUrl/fileType/morton 可选 + modules 必填 + switchConfig 可选
  'gaussianSplatting.regionReplaceConfigPath': {
    baseUrl: '',
    fileType: 'splat',
    morton: false,
    modules: [
      {
        // RegionModule（gs.ts:124-173）：id/name/url/mortonConfig/transform/bounds 必填；url 运行时生成省略
        id: '',
        name: '',
        ply_name: [''],
        mortonConfig: '',
        transform: { position: [0, 0, 0], rotation: [0, 0, 0], scale: [1, 1, 1] },
        bounds: { x: 0, y: 0, z: 0 },
        collision_name: [''],
        isDefault: false,
      },
    ],
    switchConfig: { preloadDistance: 0, unloadDistance: 0, switchDelay: 0 },
  },
  // NPCFileConfig = { models, list }（npc-region-schema.ts npcRegionFileSchema 同构）
  'npcs.configFile': {
    models: [
      {
        // NPCModelDefinition（npc.ts:193-218）：id/name 必填；modelFilePath 资源字段
        id: '',
        name: '',
        modelFilePath: '',
      },
    ],
    list: [
      {
        // NPCSpawnConfig（npc.ts:284-313）：transform 必填（对齐 npcSpawnConfigSchema.transform =
        // transformSchema 三元组数组）；position 必填出生位置，rotation 角度制，scale 三轴
        id: '',
        modelId: '',
        transform: { position: [0, 0, 0], rotation: [0, 0, 0], scale: [1, 1, 1] },
      },
    ],
  },
  // chunkedCollisionManifestSchema（gs.schema.ts:230-236）：baseUrl 可选 + modules 必填 + loadConfig 必填
  'collision.chunkedUrl': {
    baseUrl: '',
    modules: [
      {
        // collisionAssetSchema（gs.schema.ts:211-219）：url 必填 + transform/id/size 可选
        id: '',
        url: '',
        transform: { position: [0, 0, 0], rotation: [0, 0, 0], scale: [1, 1, 1] },
        size: [10, 10, 10],
      },
    ],
    loadConfig: {},
  },
  // chunkedTerrainManifestSchema（gs.schema.ts:1286-1300）：baseUrl 可选 + modules 必填 + loadConfig 必填
  'terrain.chunkedUrl': {
    baseUrl: '',
    modules: [
      {
        // terrainAssetSchema（gs.schema.ts:1263-1274）：url 必填 + transform/id/size 可选
        id: '',
        url: '',
        transform: { position: [0, 0, 0], rotation: [0, 0, 0], scale: [1, 1, 1] },
        size: [10, 10, 10],
      },
    ],
    loadConfig: {},
  },
  // NpcRegionManifest（npc.ts:90-102 / npc-region-schema.ts:50-63）：baseUrl 可选 + regions 必填
  'npcs.chunkedUrl': {
    baseUrl: '',
    regions: [
      {
        // NpcRegionAsset（npc.ts:74-85）：id/center/size/configFile 必填（center/size 为 [n,n,n] 数组）
        id: '',
        center: [0, 0, 0],
        size: [10, 10, 10],
        configFile: '',
        unloadable: true,
      },
    ],
  },
};

/**
 * 打开/下钻 JSON 子编辑器（v2.39.0：由 handleOpenJsonEditor 升级为支持任意层）。
 *
 * 统一入口（两个调用方）：
 * - 根层（parentCfgPath=null）：属性面板字段旁「编辑/新建 JSON」→ handleOpenJsonEditor
 * - 非根层：子编辑器内「下一层」按钮 → handleOpenChildJsonEditor（@open-json-editor 转发）
 *
 * 流程：
 * 1. 远程拦截：值指向 http(s):// 时提示先切本地（子编辑器只编辑本地 json）。
 * 2. 防环：目标已在配置链上则阻断（A.json → B.json → A.json）。
 * 3. 读已有内容：值指向的 json 已登记在 FileBundle 时读出解析；否则按骨架新建。
 * 4. 新建前置分配 cfgPath + 回填字段值（根层写 meta / 非根层写父节点 draft），
 *    使「新建」从进入编辑起就是一条真实可渲染配置。
 * 5. 压栈打开二级页，编辑即生效——JsonSubEditorPanel 内部 draft 防抖写回 FileBundle，
 *    右侧 PreviewPanel 随 contentVersion 实时重建。
 *
 * @param parentCfgPath 父节点 cfgPath；null 表示父是 meta（根层）
 * @param fieldPath 根层为 meta 绝对路径；非根层为相对父 json 根的路径（如 `regions[0].configFile`）
 * @param value 非根层由子编辑器转发的字段实时值（根层忽略，从 meta 取）
 * @returns 是否成功压栈（远程拦截 / 防环会返回 false）
 */
async function openSubEditorNode(
  parentCfgPath: string | null,
  fieldPath: string,
  value?: unknown,
): Promise<boolean> {
  const entryFieldName = fieldPath.split('.').pop() || '';
  const isRoot = parentCfgPath === null;
  const parentNode = isRoot ? null : subEditorStack.value[subEditorStack.value.length - 1];

  // 字段当前值：根层从 meta 取；非根层用子编辑器转发上来的实时值（draft 内的值）
  const currentValue = isRoot ? (getByPath(meta, fieldPath) as string | undefined) : value;

  /**
   * 字段值 → FileBundle key 的解析（v2.39.3）。
   *
   * 非根层的字段值是**相对父节点基准目录**的（如 manifest 内
   * `regions[].configFile = './regions/region_east.json'`，基准是 manifest 的 baseUrl），
   * 而 FileBundle 的 key 是解析后的完整相对路径（补读侧 extractChunkedManifestResourcePaths
   * 用 joinRelativePath(baseUrl, value) 生成）。
   *
   * 不解析就直接 get → 取不到 → 按「新建」处理 → 面板一片空白
   * （这正是第三层 regions[].configFile 打开为空的原因）。
   */
  const bundleKey: unknown =
    !isRoot && typeof currentValue === 'string' && currentValue
      ? FileBundle.joinRelativePath(parentNode?.baseDir ?? '', currentValue)
      : currentValue;

  // 诊断日志（临时）
  // eslint-disable-next-line no-console
  console.log('[JsonSubEditor] openSubEditorNode', {
    isRoot,
    parentCfgPath,
    fieldPath,
    currentValue,
    bundleKey,
    parentBaseDir: parentNode?.baseDir,
    isLocalPath: typeof bundleKey === 'string' && FileBundle.isLocalPath(bundleKey),
    hasBundleEntry: typeof bundleKey === 'string' && !!FileBundle.get(bundleKey),
    // 未命中时列出 bundle 内全部 key，便于比对「基准目录推导」与「补读实际写入的 key」是否一致
    bundleKeys:
      typeof bundleKey === 'string' && !FileBundle.get(bundleKey)
        ? FileBundle.entries().map(([k]) => k)
        : undefined,
  });

  // 远程拦截：http(s):// 形态字段不支持子编辑器（只编辑本地 json）
  if (typeof currentValue === 'string' && currentValue && FileBundle.isAbsoluteUrl(currentValue)) {
    await confirmDialog({
      title: '请先切换为本地类型',
      message:
        '该字段当前指向远程 http(s) URL，JSON 子编辑器仅支持编辑本地 json 文件。\n请先在字段的「本地文件」模式下选择/上传一份 json，再点击「编辑 JSON」。',
    });
    return false;
  }

  // 防环：目标 cfgPath 已在配置链上（A.json → B.json → A.json）→ 阻断，否则无限嵌套
  if (typeof bundleKey === 'string' && bundleKey && isCyclicReference(subEditorStack.value, bundleKey)) {
    pushToast({
      type: 'warn',
      title: '配置引用成环',
      message: `「${bundleKey}」已在当前配置链上，继续打开会无限嵌套。`,
    });
    return false;
  }

  // 下钻前先补齐父节点内部资源（v2.39.4）：
  // promptLoadReferencedConfigAssets 原本只在「编辑后（config-changed）」「退出二级页」触发，
  // 导致「打开 L2 → 不编辑、不关闭 → 直接点 L3」时 L3 的文件尚未进 FileBundle
  // → 读取取不到 → 按新建处理 → 面板空白（导出也因此漏文件）。
  if (!isRoot && parentNode && typeof bundleKey === 'string' && bundleKey && !FileBundle.get(bundleKey)) {
    await promptLoadReferencedConfigAssets(parentNode);
  }

  // 读已有本地 json 内容（已登记才可编辑）；否则用类型骨架新建（深拷贝，避免多次新建共享引用）。
  // 骨架表 JSON_EDITOR_SKELETONS 的 key 是 meta 绝对路径 → 仅根层可用；非根层无骨架 → 纯 infer。
  const skeleton = isRoot ? JSON_EDITOR_SKELETONS[fieldPath] : undefined;
  let initial: Record<string, unknown> = skeleton ? (structuredClone(skeleton) as Record<string, unknown>) : {};
  let cfgPath = '';
  if (typeof bundleKey === 'string' && bundleKey && FileBundle.isLocalPath(bundleKey)) {
    const entry = FileBundle.get(bundleKey);
    if (entry) {
      try {
        const text = await new Response(entry as BodyInit).text();
        const parsed: unknown = JSON.parse(text);
        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
          initial = parsed as Record<string, unknown>;
          // bundleKey 已在 guard 处按 string narrow（TS 不跨 try 块保持 narrow）
          cfgPath = bundleKey as string;
          // npc spawn config（{models, list}）：把老格式平铺 position/rotation/scale 归一化成合成
          // transform，使 infer 识别成 transform 控件（gizmo），编辑保存后输出新格式（对齐 SDK）。
          // 按 schema/字段名判定而非 `npcs.` 路径前缀——L3 的 regions[0].configFile 不含该前缀，
          // 按前缀会漏掉第三层老格式数据（不归一化 → 无 gizmo 且导出仍是老格式）。
          if (isNpcSpawnConfigEntry(fieldPath)) {
            normalizeNpcLegacySpawnTransform(initial);
          }
        }
      } catch (err) {
        // eslint-disable-next-line no-console
        console.warn(`[JsonSubEditor] 读取已有 json 失败（${bundleKey}），按新建处理:`, err);
        initial = skeleton ? (structuredClone(skeleton) as Record<string, unknown>) : {};
        cfgPath = '';
      }
    }
  }

  // v2.39.8：本地未命中 + 父节点 baseUrl 为远程（绝对 URL）→ 从远端拉取配置内容。
  //
  // 为什么需要：baseUrl 为绝对 URL 时编辑器把整份清单判为「远程引用」——
  // extractChunkedManifestResourcePaths 直接 return []（不本地化），因此区域配置
  // （regions[].configFile）从未登记进 FileBundle，打开下一层只能得到空面板。
  // 这里按「远程 baseUrl + 相对段」语义拼出远程 URL 并拉取，登记到同一 bundleKey
  // （**不改写父节点引用**：SDK 侧仍按 baseUrl + 相对段远程加载，编辑器侧用同一 key
  // 从 bundle 取，两边自洽）。拉取失败则降级按新建，保持旧行为。
  if (!cfgPath && !isRoot && parentNode && typeof currentValue === 'string' && currentValue) {
    const parentBase = typeof parentNode.json?.baseUrl === 'string' ? parentNode.json.baseUrl : '';
    const remoteUrl = FileBundle.resolveRemoteChunkedSegToUrl(currentValue, parentBase);
    if (remoteUrl && typeof bundleKey === 'string' && bundleKey) {
      try {
        const resp = await fetch(remoteUrl);
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const parsed: unknown = await resp.json();
        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
          initial = parsed as Record<string, unknown>;
          cfgPath = bundleKey;
          if (isNpcSpawnConfigEntry(fieldPath)) normalizeNpcLegacySpawnTransform(initial);
          FileBundle.register(cfgPath, new TextEncoder().encode(JSON.stringify(initial, null, 2)));
        }
      } catch (err) {
        // eslint-disable-next-line no-console
        console.warn(`[JsonSubEditor] 远程配置拉取失败（${remoteUrl}），按新建处理:`, err);
      }
    }
  }

  // 新建（无已有可编辑内容）：前置分配 cfgPath + 写骨架 + 回填字段值。
  // 这样「新建」从进入编辑起就是一条真实可渲染配置，与编辑已有 json 共用同一套
  // 「draft 防抖写回 FileBundle」逻辑，无需分支。
  //
  // 落盘基准（bundleDir）：
  // - 非托管模式：落根（v2.32.0 起目录型配置落根）——清单内部相对路径基准 = 根，
  //   避免 bundleDir 前缀把清单移到子目录导致内部资源错位。
  // - 托管模式：根层用 resolveResourceBundleDir，非根层用**父节点 baseDir**
  //   （子 json 应落在父配置所在目录，父 json 的相对引用才拼得出）。
  if (!cfgPath) {
    const bundleDir = !workspaceMode.value
      ? ''
      : isRoot
        ? resolveResourceBundleDir(entryFieldName.toLowerCase()) || ''
        : (parentNode?.baseDir ?? '');
    cfgPath = FileBundle.uniquePath(
      bundleDir,
      JSON_EDITOR_DEFAULT_FILENAMES[entryFieldName.toLowerCase()] || 'config.json',
    );
    FileBundle.register(cfgPath, new TextEncoder().encode(JSON.stringify(initial, null, 2)));
    // 回填：根层写 meta；非根层写**父节点 draft**（栈快照 + 父面板活 draft 双写），
    // 使父层面板立即显示新引用、弹栈回来重挂载时快照也不丢。
    if (isRoot) {
      setByPath(meta, fieldPath, cfgPath);
    } else if (parentNode) {
      // 回填到父 draft 的值必须是**相对父节点 baseDir** 的（与父 json 内其他引用同基准）。
      // 不能直接写 bundle key（= baseDir + 相对值）——否则下次打开会再拼一次 baseDir 而错位。
      const baseDir = parentNode.baseDir;
      const relativeValue =
        baseDir && cfgPath.startsWith(baseDir) ? cfgPath.slice(baseDir.length) : cfgPath;
      setByPath(parentNode.json, fieldPath, relativeValue);
      parentNode.dirty = true;
      subEditorRef.value?.applyFieldValue(fieldPath, relativeValue);
    }
  }

  // 打开/下钻侧边栏二级页（默认切到「场景」视图）。
  // 先关闭 gizmo：目录型配置字段（regionReplaceConfigPath/configFile/chunkedUrl）的父 widget
  // （gaussianSplatting/npcs/collision/terrain）多含 transform，选中即自动激活 gizmo →
  // suppressRebuild=true。若不关闭，二级页编辑即生效的实时重建（scheduleRebuild 非 force）
  // 会被 suppressRebuild 静默拦截、右侧场景永不刷新。故进入二级页前先清空主编辑器 gizmo；
  // 二级页自身会在选中字段 key 时以「draft 短路径」重新激活 gizmo（见 JsonSubEditorPanel），
  // 两者路径语义不同，必须互斥而非叠加。
  deactivateGizmo();
  activeTab.value = 'scene';
  const node: SubEditorNode = {
    cfgPath,
    parentCfgPath,
    fieldPathInParent: fieldPath,
    entryFieldName,
    // 面包屑文案用完整路径：根层是 meta 绝对路径（npcs.configFile），
    // 非根层是相对父 json 的路径（regions[0].configFile）—— 只用字段名会显示成
    // 「configFile › configFile」无法区分层级。
    title: fieldPath,
    json: initial,
    skeleton,
    baseDir: '',
    dirty: false,
  };
  // baseDir 依赖 node.json（chunked manifest 取自身 baseUrl），故在结构完整后单独推导
  node.baseDir = resolveNodeBaseDir(node);
  subEditorStack.value = [...subEditorStack.value, node];
  return true;
}

/**
 * 属性面板入口（根层）。
 *
 * 入口校验按**末段字段名**（isJsonEntryFieldName）而非「精确路径 + 提取器存在性」：
 * SDK 自 v1.15.0 起把 chunk 声明收编为 `{ chunks: { chunkedUrl } }` 形态，chunked manifest
 * 的真实绝对路径是 `npcs.chunks.chunkedUrl`（非旧扁平 `npcs.chunkedUrl`）——按精确 key 匹配
 * 会让「编辑 JSON」点击无反应。
 *
 * 不再要求「必须存在提取器」：补读侧已具备通用深度扫描兜底，任何白名单字段名都能进入编辑。
 */
async function handleOpenJsonEditor(absPath: string): Promise<void> {
  if (!absPath || !isJsonEntryFieldName(absPath)) return;
  await openSubEditorNode(null, absPath);
}

/**
 * 子编辑器内「下一层」入口（v2.39.0）。
 *
 * relPath 是**相对父 json 根**的草稿路径（如 `regions[0].configFile`），value 为其实时值。
 * 不做注册表校验：多层下的路径不在 meta 里，入口合法性由 SchemaRenderer 的
 * 「白名单 ∪ 值以 .json 结尾」判定（jsonEditableOf），内部资源补读走通用深度扫描兜底。
 */
async function handleOpenChildJsonEditor(relPath: string, value: unknown): Promise<void> {
  const parentNode = subEditorState.value;
  if (!parentNode || !relPath) return;
  await openSubEditorNode(parentNode.cfgPath, relPath, value);
}

/**
 * v2.29.0：退出侧边栏二级页（「返回」按钮触发）。
 *
 * 退出时复用 runPendingConfigLoad 重扫子 json 内部引用做差量授权补读 + 触发一次
 * 强制重建（对齐原「保存后补读」语义）。编辑期间的实时刷新已由 JsonSubEditorPanel
 * 的 draft 防抖写回 + contentVersion 信号完成，无需在退出前再补一次写回。
 */
async function popTo(index: number, hasChanges = false): Promise<void> {
  const stack = subEditorStack.value;
  if (stack.length === 0) return;

  // 待弹出 (index, 栈顶] 的所有节点
  const popped = stack.slice(index + 1);
  const newTop = index >= 0 ? stack[index] : null;

  // 保留层（新栈顶）的脏标志：由面板报告的 hasChanges 补齐——覆盖「编辑后 300ms 防抖内
  // 立即返回」边界（此时 config-changed 尚未 emit，节点 dirty 还是 false 会漏标脏丢改动）。
  if (newTop && hasChanges) newTop.dirty = true;

  // 逐个收口被弹出的层：按**各层自身 dirty** 标脏（一次弹多层时中间层的脏状态只能自己承载），
  // 并对该层做一次差量补读（对齐原「退出即补读」语义）。
  for (const node of popped) {
    if (node.dirty) dirtyJsonSet.value.add(node.cfgPath);
    await runPendingConfigLoad(node);
  }

  // 仍有层级 → **先刷新新栈顶快照再改栈**：父面板会因 :key 变化重挂载、draft 从快照重建，
  // 而 Vue 渲染是异步的 —— 若先改栈再 await，重挂载可能已用旧快照完成（丢失父层改动）。
  if (newTop) await refreshNodeSnapshot(newTop);

  subEditorStack.value = index >= 0 ? stack.slice(0, index + 1) : [];
  // 层级变化 → 释放子编辑器内以草稿短路径激活的 gizmo，
  // 避免残留 activeGizmoEntries 留下一组无主 gizmo。
  deactivateGizmo();
}

/**
 * 返回按钮（v2.39.0）：逐层返回一层——弹出栈顶，回到父层；栈长为 1 时等价于关闭二级页。
 */
async function onCloseSubEditor(hasChanges: boolean): Promise<void> {
  await popTo(subEditorStack.value.length - 2, hasChanges);
}

/**
 * 从 FileBundle 重读节点 json 快照（弹栈回来后调用）。
 *
 * 数据真相源是 FileBundle（面板 draft 已防抖写回），而 :key=cfgPath 变化会让面板重挂载、
 * draft 从栈快照重建 —— 不刷新快照就会显示旧内容。
 */
async function refreshNodeSnapshot(node: SubEditorNode): Promise<void> {
  const entry = FileBundle.get(node.cfgPath);
  if (!entry) return;
  try {
    const text = await new Response(entry as BodyInit).text();
    const parsed: unknown = JSON.parse(text);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      const next = parsed as Record<string, unknown>;
      if (isNpcSpawnConfigEntry(node.fieldPathInParent)) normalizeNpcLegacySpawnTransform(next);
      node.json = next;
    }
  } catch {
    /* 读失败保留旧快照（预览仍以 FileBundle 原内容为准） */
  }
}

/**
 * v2.31.0：二级页编辑期间「静默补读」内部资源。
 *
 * 编辑即生效只把 config 内容写回 FileBundle，不会补读新引用的资源（如改了 baseUrl /
 * collision_name / ply_name 后，新指向的地块/碰撞文件不在 FileBundle）——导致预览改写
 * 保留相对路径、SDK 拼出无效 blob URL（ERR_FILE_NOT_FOUND）。而退出二级页时
 * runPendingConfigLoad 补读后又能恢复，这正是「编辑时 404、返回后正常」的根因。
 *
 * 这里在 config 变更后（节流触发）做「静默补读」：用会话内缓存的目录句柄试读缺失资源，
 * 成功则 FileBundle.register（contentVersion++ 自动触发 PreviewPanel 重建）；失败静默忽略
 * （不弹框，退出时 runPendingConfigLoad 仍会做完整授权补读兜底）。
 *
 * @param node 当前编辑层的节点（栈顶）；提取器按节点解析（根层注册表 / 非根层通用扫描）
 */
async function silentReloadConfigAssets(node: SubEditorNode): Promise<void> {
  const cfgPath = node.cfgPath;
  const entry = FileBundle.get(cfgPath);
  if (!entry) {
    // eslint-disable-next-line no-console
    console.warn(`[silent-reload] 跳过：FileBundle 无 cfgPath 内容（${cfgPath}）`);
    return;
  }
  // 提取器按节点解析：根层查注册表（精确语义），非根层走通用深度扫描兜底
  const extractor = resolveExtractorForNode(node);

  let referenced: string[];
  try {
    referenced = await extractor(cfgPath, entry);
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn(`[silent-reload] 跳过：提取内部资源失败（${node.fieldPathInParent}）`, err);
    return;
  }

  const missing = referenced.filter((p) => !FileBundle.has(p));
  if (missing.length === 0) {
    // eslint-disable-next-line no-console
    console.log(`[silent-reload] 内部资源已齐（${referenced.length} 项），无需补读`);
    return;
  }

  // eslint-disable-next-line no-console
  console.log(`[silent-reload] 提取 ${referenced.length} 项，缺失 ${missing.length} 项，尝试静默补读：`, missing);

  // 仅用可用目录句柄静默试读（托管模式用托管根、非托管用 read 缓存；无则退出时完整补读兜底）
  const cached = getReadableDirectoryHandle();
  if (!cached) {
    // eslint-disable-next-line no-console
    console.warn('[silent-reload] 跳过：无可用目录句柄（刷新页面后会丢），等退出时完整授权补读');
    return;
  }

  try {
    // 成功项自动 FileBundle.register（contentVersion++ 触发重建）；失败静默忽略
    // v2.34.0 托管模式：托管根 = meta 目录，内部资源只应精确匹配（不 basename 兜底，
    // 避免把 meta 目录外同名文件误加载进来）；非托管维持 basename 兜底兼容目录名差异。
    if (isWorkspaceMode()) {
      await loadFromDirectoryHandle(cached, missing);
    } else {
      await loadFromDirectoryHandleWithBasenameFallback(cached, missing);
    }
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn('[silent-reload] 静默补读异常（退出时完整补读兜底）', err);
  }
}

/**
 * v2.31.0：二级页 config 变更后的节流调度（防抖 500ms）。
 *
 * 编辑过程中每 300ms 防抖写回一次、emit 一次 config-changed；静默补读会遍历授权目录
 * 做 basename 兜底（collectAllFiles），成本较高，故此处再叠加一层节流，把连续编辑合并为
 * 「停顿 500ms 后补读一次」，避免每次按键都触发全目录扫描。
 */
let silentReloadTimer: number | null = null;

function onSubEditorConfigChanged(): void {
  const state = subEditorState.value;
  if (!state) return;
  // 托管模式：编辑即生效写回 FileBundle 后标记该子 json 为脏，供 saveToDisk 统一写回磁盘
  dirtyJsonSet.value.add(state.cfgPath);
  // 节点级脏标志：popTo 一次弹多层时，中间层的脏状态只能由各层自己承载
  // （面板 emit 只反映栈顶层的本次会话改动）。
  state.dirty = true;
  if (silentReloadTimer != null) window.clearTimeout(silentReloadTimer);
  silentReloadTimer = window.setTimeout(() => {
    silentReloadTimer = null;
    void silentReloadConfigAssets(state);
  }, 500);
}

/**
 * 目录型配置内部引用提取器：读取已登记的 config/清单字节，返回其引用的本地资源相对路径。
 */
type DirectoryConfigExtractor = (cfgPath: string, entry: Blob | Uint8Array) => Promise<string[]>;

/**
 * 按节点解析「内部资源提取器」（v2.39.0 多层版）。
 *
 * - 根层（父是 meta）且路径命中注册表 → 用注册表的精确提取器（保留 chunked manifest 的
 *   baseUrl 基准、regionReplace 的 modules 递归等既有语义，2 层场景零回归）。
 * - 其余（非根层，或根层未在注册表）→ **通用深度扫描兜底**：递归遍历该节点 json，字段名命中
 *   `resolveResourceBundleDir` 白名单的字符串叶子按节点 baseDir 解析为相对 key。
 *
 * 兜底是「通用一直嵌套」的关键——任何新链路（如 `regions[].configFile` 里的
 * `models[].modelFilePath`）无需改代码即可补读，只要资源字段名落在既有白名单内。
 */
function resolveExtractorForNode(node: SubEditorNode): DirectoryConfigExtractor {
  const exact = node.parentCfgPath === null ? resolveDirectoryExtractor(node.fieldPathInParent) : null;
  if (exact) return exact;
  return async (_cfgPath, entry) => {
    let parsed: unknown;
    try {
      parsed = JSON.parse(await new Response(entry as BodyInit).text());
    } catch {
      return [];
    }
    return collectNodeResourcePaths(parsed, node.baseDir);
  };
}

/**
 * v2.20.0：目录型引用配置注册表——字段绝对路径 → config 内部引用提取器。
 *
 * 覆盖三类"上传的是清单文件、内部还引用其他本地资源"的字段：
 * - gaussianSplatting.regionReplaceConfigPath：region-replace-config.json（modules 地块）
 * - npcs.configFile：NPC 区域清单 JSON（models 模型/贴图）
 * - collision / terrain / npcs 的 chunkedUrl：分块清单 manifest（collision modules[].url、
 *   terrain modules[].url + r16Url、npcs regions[].configFile）
 *
 * onPropertyChange（上传后引导授权补读）与 promptLoadReferencedConfigAssets（分发提取器）
 * 共用本表，避免硬编码字段清单漂移。
 *
 * ⚠️ 时效提醒：SDK 自 v1.15.0 起把 chunk 声明收编为 `{ chunks: { chunkedUrl } }` 形态，
 * chunked manifest 的**真实绝对路径**是 `npcs.chunks.chunkedUrl`（扁平 `npcs.chunkedUrl`
 * 仅存于早期数据）。本表的扁平 key 只覆盖旧形态，新形态由 resolveDirectoryExtractor 兜底。
 */
const DIRECTORY_CONFIG_FIELD_MAP: Record<string, DirectoryConfigExtractor> = {
  'gaussianSplatting.regionReplaceConfigPath': (p, e) => extractRegionReplaceResourcePaths(p, e),
  'npcs.configFile': (p, e) => extractNpcsConfigResourcePaths(p, e),
  'collision.chunkedUrl': (p, e) => extractChunkedManifestResourcePaths(p, e, 'collision'),
  'terrain.chunkedUrl': (p, e) => extractChunkedManifestResourcePaths(p, e, 'terrain'),
  'npcs.chunkedUrl': (p, e) => extractChunkedManifestResourcePaths(p, e, 'npcs'),
};

/**
 * 解析路径对应的「目录型配置提取器」（v2.39.1）。
 *
 * 为什么需要按路径解析（而非直接查表）：SDK 自 v1.15.0 起把 chunk 声明收编为
 * `{ chunks: { chunkedUrl } }` 形态，chunked manifest 的**真实绝对路径**是
 * `npcs.chunks.chunkedUrl`（而非旧扁平的 `npcs.chunkedUrl`）。原按扁平 key 精确匹配
 * 导致 chunks 模式下：①「编辑 JSON」点击无反应（入口校验直接 return）；
 * ②上传后不引导补读（onPropertyChange 条件不成立）。
 *
 * 解析顺序：
 * 1. 精确匹配（旧扁平形态 + 非 chunked 配置 → 保持既有语义，零回归）
 * 2. 末段字段名 `chunkedUrl` → 按路径首段取维度 → chunked manifest 提取器
 *    （兼容任意 wrapper 层级）
 * 3. 未命中 → null（入口仍放开，补读降级走通用深度扫描兜底）
 */
function resolveDirectoryExtractor(absPath: string): DirectoryConfigExtractor | null {
  const exact = DIRECTORY_CONFIG_FIELD_MAP[absPath];
  if (exact) return exact;

  const normalized = absPath.toLowerCase();
  if (normalized.endsWith('.chunkedurl')) {
    const dimension = normalized.slice(0, normalized.indexOf('.'));
    if (dimension === 'collision' || dimension === 'terrain' || dimension === 'npcs') {
      const kind = dimension;
      return (p, e) => extractChunkedManifestResourcePaths(p, e, kind);
    }
  }
  return null;
}

/**
 * v2.14.0：属性面板上传"目录型引用配置"后的第二层资源补读引导。
 *
 * config 内部引用的地块 / NPC 模型 / 贴图 / 分块文件（如 region-replace 的 modules[].ply_name、
 * npcs 的 models[].modelFilePath、chunked 清单的 modules[].url）不在 FileBundle 中，
 * 导致预览改写时无法转 blob。弹确认框引导用户授权目录，按 config 内部解析出的路径精确补读。
 *
 * @param absPath 触发字段绝对路径（注册表 DIRECTORY_CONFIG_FIELD_MAP 的 key）
 * @param cfgPath 新写入的 config 本地路径（FileBundle key）
 */
async function promptLoadReferencedConfigAssets(node: SubEditorNode): Promise<void> {
  const cfgPath = node.cfgPath;
  // config 本体需已登记（UrlField 上传后即登记）；未登记说明是手输路径，跳过
  const entry = FileBundle.get(cfgPath);
  if (!entry) return;

  // 提取器按节点解析：根层查 meta 绝对路径注册表（保留精确语义），非根层走通用深度扫描
  const extractor = resolveExtractorForNode(node);

  let referenced: string[];
  try {
    referenced = await extractor(cfgPath, entry);
  } catch {
    return;
  }
  // v2.21.0：npcs.chunkedUrl 误收 legacy 单文件清单（含 models/list 而非 regions）时的
  // 兜底提示——此时按 region manifest 解析提取 0 引用、静默无资源（不引导授权不打包）。
  // 正常默认形态已是 legacy（configFile），此处仅覆盖用户手动切到 Chunked 变体后误传。
  if (node.fieldPathInParent === 'npcs.chunkedUrl' && referenced.length === 0) {
    const looksLegacy = await sniffNpcsChunkedMismatch(entry);
    if (looksLegacy) {
      pushToast({
        type: 'warn',
        title: '文件形态不匹配',
        message:
          `「${cfgPath}」是 legacy NPC 清单（含 models/list），不是 region manifest。\n` +
          `请把 npcs 切回 Legacy 变体，在 configFile 字段上传该文件；chunkedUrl 仅用于 regions 多区域外链清单。`,
        duration: 6000,
      });
      return;
    }
  }
  let missing = referenced.filter((p) => !FileBundle.has(p));
  if (missing.length === 0) return; // 内部资源已齐（如整目录授权导入过），无需引导

  // 收集当前仍缺失的内部引用（含深层引用：npcs chunked 的 configFile 登记后暴露 models）
  const collectMissing = async (): Promise<string[]> => {
    const refs = await extractor(cfgPath, entry);
    return refs.filter((p) => !FileBundle.has(p));
  };

  // v2.34.0 托管工作区模式：meta 所在目录已是授权读写根，内部资源只应精确匹配该目录。
  // 直接用托管根精确读取缺失文件；读不到即代表磁盘上确实没有对应文件，不再弹
  // 「选择目录授权」引导框，改为提示用户在子编辑器中上传（同时规避 basename 兜底把
  // meta 目录外的同名文件误加载进来）。
  if (isWorkspaceMode()) {
    const root = getReadableDirectoryHandle();
    if (root) {
      const report = await loadFromDirectoryHandle(root, missing);
      reportLoad(report, '加载配置内部资源');
      missing = await collectMissing();
    }
    if (missing.length > 0) {
      pushToast({
        type: 'warn',
        title: '配置内部资源缺失',
        message:
          `以下 ${missing.length} 个资源文件在 meta 目录下未找到，请在子编辑器中上传：\n` +
          missing
            .slice(0, 3)
            .map((p) => `· ${p}`)
            .join('\n') +
          (missing.length > 3 ? `\n...另有 ${missing.length - 3} 个` : ''),
        duration: 6000,
      });
    }
    return;
  }

  if (!isFileSystemAccessSupported()) {
    pushToast({
      type: 'info',
      title: '配置内部资源未加载',
      message:
        `该配置引用了 ${missing.length} 个本地资源文件（如 ${missing[0]}），` +
        `当前浏览器不支持目录授权，请使用"加载素材目录"按钮选择项目根目录。`,
      duration: 6000,
    });
    return;
  }

  // v2.20.0 有界多层补读：chunked npcs 存在 manifest → regions[].configFile → models 三层引用。
  // 每轮授权加载后重新提取——新登记的 configFile 会在下一轮 extract 中暴露其内部 models 缺失
  // （extractChunkedManifestResourcePaths npcs 分支对已登记 configFile 递归）。目录缺文件时
  // missing 不收敛，轮次封顶 MAX_ROUNDS，末轮仍缺交由 v2.10 导出前拦截提示。
  const MAX_ROUNDS = 4;

  // v2.19.0：会话内已有授权目录句柄时先静默试读——此前只要存在缺失文件就无条件弹
  // "配置内部资源未加载"引导框（缓存只跳过了原生目录选择器，没跳过该确认框）。
  // 缓存目录全部命中 → 直接完成，不打扰用户；缓存不匹配 → 更新缺失列表，引导确认后强制重选。
  const cached = getReadableDirectoryHandle();
  if (cached) {
    const silent = await loadFromDirectoryHandleWithBasenameFallback(cached, missing);
    if (silent.failed.length === 0) {
      reportLoad(silent, '加载配置内部资源');
      // 深层引用（configFile 登记后暴露 models）：若缓存目录本就包含全部文件可继续命中
      const deeper = await collectMissing();
      if (deeper.length === 0) return;
      missing = deeper;
    } else {
      missing = silent.failed.map((f) => f.path);
    }
  }

  const ok = await confirmDialog({
    title: '配置内部资源未加载',
    message:
      `该配置引用了 ${missing.length} 个资源文件，尚未加载（如：\n` +
      missing
        .slice(0, 3)
        .map((p) => `· ${p}`)
        .join('\n') +
      (missing.length > 3 ? `\n...另有 ${missing.length - 3} 个` : '') +
      `\n\n【文件在本地】请授权一个能逐级包含这些路径的目录（如 meta.json 所在目录），仅会读取配置引用的文件。` +
      `\n【文件在远程】若这些资源托管在服务器上，请把清单（manifest）的 baseUrl 改为绝对 URL（http(s)://…）` +
      `——编辑器会将远程引用视为外部资源，不再要求本地存在（但导出包也不会包含它们）。`,
    okText: '选择目录授权',
    cancelText: '稍后再说',
    variant: 'info',
  });
  if (!ok) return;

  try {
    // v2.17.0：优先复用会话内已授权的目录句柄（assets-loader v1.6.0 缓存），
    // 避免同一会话内每次上传 config 都重新弹目录选择器。
    // v2.19.0：cached 静默试读失败时（useCached: false）强制原生重选，不复用失败缓存。
    let dirHandle: Awaited<ReturnType<typeof pickDirectoryHandle>> | null = null;
    for (let round = 0; round < MAX_ROUNDS && missing.length > 0; round++) {
      dirHandle = await pickDirectoryHandle('read', undefined, { useCached: !cached && round === 0 });
      if (!dirHandle) return; // 用户取消
      // v2.15.0：basename 兜底——属性面板上传后 config 路径被 bundleDir 重命名
      // （如 region-replace/），磁盘目录可能是 region_replace/，精确路径匹配不上时
      // 按文件名匹配登记，解决目录名差异导致的内部资源加载失败。
      let report = await loadFromDirectoryHandleWithBasenameFallback(dirHandle, missing);
      if (report.failed.length > 0) {
        // 目录可能不属于该项目：给一次"重新选择目录"的机会（强制不走缓存）
        const retry = await confirmDialog({
          title: '部分资源未找到',
          message:
            `仍有 ${report.failed.length} 个文件未加载到（如 ${report.failed[0].path}）。\n\n` +
            `可能原因：\n` +
            `· 所选目录不是项目根目录——配置内的相对路径以 meta.json 所在目录为基准\n` +
            `· 这些文件实际托管在远程服务器——若如此，请把清单（manifest）的 baseUrl 改为绝对 URL` +
            `（http(s)://…），编辑器会将远程引用视为外部资源、不再要求本地存在\n\n` +
            `是否重新选择目录？`,
          okText: '重新选择目录',
          cancelText: '算了',
          variant: 'warn',
        });
        if (!retry) {
          reportLoad(report, '加载配置内部资源');
          return;
        }
        dirHandle = await pickDirectoryHandle('read');
        if (!dirHandle) return;
        report = await loadFromDirectoryHandleWithBasenameFallback(dirHandle, missing);
      }
      reportLoad(report, '加载配置内部资源');
      // 递归暴露更深层引用（npcs chunked 的 configFile 内部 models），有界收敛
      missing = await collectMissing();
    }
  } catch (err) {
    pushToast({
      type: 'error',
      title: '加载失败',
      message: (err as Error).message || String(err),
    });
  }
}

/**
 * Gizmo 拖拽回写：PreviewPanel 中 TransformControls 拖动时，
 * 通过 useGizmoBridge 通知到此处，路由到 onPropertyChange 写回 meta。
 *
 * absPath 是 transform 字段的绝对路径（如 "gaussianSplatting.transform"），
 * channel 是 position/rotation/scale 三轴之一。
 */
const { changeHandler, activeGizmoEntries, sdkRef, sceneReadyCounter, pickResult } = useGizmoBridge();
changeHandler.value = (absPath: string, channel: 'position' | 'rotation' | 'scale' | 'size', value: number[]) => {
  // 子编辑器（侧边栏二级页）打开时，gizmo entry.path 是相对 draft 根的**短路径**
  // （如 list[0].transform），直接当 meta 绝对路径写回会落到错误位置 → 转发给子编辑器
  // 按草稿路径回写，由 draft deep watch 走原有「编辑即生效」链路。
  if (isSubEditorOpen()) {
    subEditorRef.value!.applyGizmoChange(absPath, channel, value);
    return;
  }
  onPropertyChange(`${absPath}.${channel}`, value);
};

/**
 * 打点拾取回填：PreviewPanel 命中碰撞体后经 setPickResult 回传，
 * 此处按「点谁回填谁」把命中坐标写回对应 transform 的 position。
 * absPath 是 transform 字段的绝对路径（如 "gaussianSplatting.transform"）。
 */
watch(pickResult, (res) => {
  if (!res || !res.path) return;
  // 子编辑器打开时：res.path 是草稿内短路径，按 meta 绝对路径回填会写错位置、
  // 也会污染主编辑器的打点历史栈 → 直接转发给子编辑器回填 draft。
  if (isSubEditorOpen()) {
    // 子编辑器 draft 存的是**配置坐标**（SDK 消费时 − worldOrigin 转场景坐标），
    // 而 res.pos 是场景坐标 —— 必须用 res.configPos，否则打点后数值整体偏移一个
    // worldOrigin（表现为「从 0 开始」、与原值差别很大）。meta 路径不受影响（仍用 pos）。
    subEditorRef.value!.applyPickPosition(res.path, res.configPos ?? res.pos);
    return;
  }
  // 记录打点前旧 position 入历史栈（供「回退」按钮撤销），再回填新值。
  // vectorToTuple 兼容 [x,y,z] 数组与 {x,y,z} 对象两种旧格式，避免对象格式
  // 取 [0] 得到 undefined 而被错误记录为 [0,0,0]（回退会把模型拉到原点）。
  const beforeTuple = vectorToTuple(getByPath(meta, `${res.path}.position`), [0, 0, 0]);
  // 命中坐标与当前 position 相同时跳过（不入栈、不回填），避免：
  // ① 入栈一层相同值导致回退"看起来没反应"；
  // ② 触发无意义的 onPropertyChange（脏标记 + SDK 重建）。
  if (beforeTuple[0] === res.pos[0] && beforeTuple[1] === res.pos[1] && beforeTuple[2] === res.pos[2]) {
    return;
  }
  recordPickPosition(res.path, beforeTuple);
  onPropertyChange(`${res.path}.position`, res.pos);
});

const waitForSdkRefresh = async (beforeSdk: any, beforeCounter: number, timeoutMs = 5000): Promise<void> => {
  const start = Date.now();
  let sdkChangedTime: number | null = null;
  while (Date.now() - start < timeoutMs) {
    await new Promise<void>((resolve) => window.setTimeout(resolve, 50));
    if (sdkRef.value && sdkRef.value !== beforeSdk) {
      if (sdkChangedTime === null) sdkChangedTime = Date.now();
      // SDK 重建完成且场景就绪 → 可以安全激活 gizmo
      if (sceneReadyCounter.value !== beforeCounter) return;
      // SDK 已重建但场景 2s 内未触发 onSceneReady → 兜底返回（可能场景无 zone 对象）
      if (Date.now() - sdkChangedTime > 2000) return;
    }
  }
};

const activateNewArrayItemGizmoAfterRender = async (
  arrAbsPath: string,
  itemPath: string,
  item: unknown,
  beforeSdk: any,
  beforeCounter: number,
): Promise<void> => {
  if (arrAbsPath === 'interactionZones') {
    deactivateGizmo();
    await nextTick();
    await waitForSdkRefresh(beforeSdk, beforeCounter);
    // interactionZones 统一走 collectInteractionZoneGizmoEntries（v3 shape 只收集 shape.transform，
    // 避免 geometry/model 兼容镜像重复 gizmo）
    activateGizmoMulti(collectInteractionZoneGizmoEntries());
    return;
  }

  const found: { path: string; transform: any }[] = [];
  findTransformsInData(item, itemPath, found);
  if (found.length === 0) return;

  const newEntries = found.map((f) => makeGizmoEntry(f.path, f.transform));
  activateGizmoMulti([...activeGizmoEntries.value, ...newEntries]);
};

/** 数组追加 */
const onArrayPush = async (arrAbsPath: string, item: unknown): Promise<void> => {
  if (!arrAbsPath) return;
  const beforeSdk = sdkRef.value;
  const beforeCounter = sceneReadyCounter.value;
  let arr = getByPath(meta, arrAbsPath);
  if (!Array.isArray(arr)) {
    // 如果已有数据是 Record（非空对象），弹出确认提示，告知会覆盖
    if (arr != null && typeof arr === 'object' && !Array.isArray(arr)) {
      const keys = Object.keys(arr).slice(0, 3);
      const preview = keys.map((k) => `· ${k}`).join('\n');
      const more = Object.keys(arr).length > 3 ? `\n...另有 ${Object.keys(arr).length - 3} 个字段` : '';
      const proceed = await confirmDialog({
        title: '新增数组项：将覆盖现有 Record 数据',
        message:
          `当前 ${arrAbsPath} 为 Record 类型（${Object.keys(arr).length} 个字段）：\n${preview}${more}\n\n` +
          `新增数组项会将以上数据替换为空数组，内容将不可恢复。`,
        okText: '确认覆盖',
        cancelText: '取消',
        variant: 'warn',
      });
      if (!proceed) return;
    }
    setByPath(meta, arrAbsPath, []);
    arr = getByPath(meta, arrAbsPath);
  }
  (arr as unknown[]).push(item);

  // 新增项含 transform → 自动激活 gizmo。
  // interactionZones 数组项需要先等预览 SDK 重建出 zone_0/zone_1 等运行时对象，
  // 否则 PreviewPanel 会先创建 gizmo，导致 sceneTarget=null，只回写数值不更新视觉。
  const newIndex = (arr as unknown[]).length - 1;
  const itemPath = `${arrAbsPath}[${newIndex}]`;
  void activateNewArrayItemGizmoAfterRender(arrAbsPath, itemPath, item, beforeSdk, beforeCounter);
};

/** 数组移除（按索引） */
const onArrayRemove = (arrAbsPath: string, index: number): void => {
  if (!arrAbsPath) return;
  const arr = getByPath(meta, arrAbsPath);
  if (!Array.isArray(arr)) return;
  if (index < 0 || index >= arr.length) return;
  arr.splice(index, 1);

  // 移除的项可能激活了 gizmo → 清理失效条目并重新索引
  const removedPathPrefix = `${arrAbsPath}[${index}]`;
  // 精确匹配：path === prefix 或 path 以 prefix + '.' 或 prefix + '[' 开头
  // （避免 `list[1]` 误匹配 `list[10]`）
  const isRemovedPath = (path: string) =>
    path === removedPathPrefix || path.startsWith(removedPathPrefix + '.') || path.startsWith(removedPathPrefix + '[');
  const survivingEntries = activeGizmoEntries.value.filter((e) => !isRemovedPath(e.path));

  // 重新索引：被删项之后的条目 path 中 [i] 需要减 1
  const reindexed = survivingEntries.map((e) => {
    if (!e.path.startsWith(arrAbsPath + '[')) return e;
    const match = e.path.match(/\[(\d+)\]/);
    if (!match) return e;
    const idx = parseInt(match[1], 10);
    if (idx <= index) return e; // 删项之前的不受影响
    return { ...e, path: e.path.replace(`[${idx}]`, `[${idx - 1}]`) };
  });

  if (
    reindexed.length !== activeGizmoEntries.value.length ||
    reindexed.some((e, i) => e.path !== activeGizmoEntries.value[i].path)
  ) {
    activateGizmoMulti(reindexed);
  }
};

// ==================== 文件菜单：新建 / 导入 / 导出 ====================

/**
 * 用 setMeta 替代 Object.assign，确保：
 * - 旧 keys 全部清空（避免上一份数据残留）
 * - 写入后立刻跑 normalizeMeta（修非法形态）
 * - 重置选中状态（避免选中已不存在的 widget）
 */
function setMeta(next: Record<string, any>): void {
  for (const k of Object.keys(meta)) delete meta[k];
  Object.assign(meta, next);
  normalizeMeta(meta);
  selectedWidgetId.value = null;
  // 场景切换：清空打点历史栈，避免旧场景坐标污染新场景的回退
  clearAllPickHistory();
  // 加载新数据后旧脏集合作废，一并清空（否则残留的子 json 脏标记会让 isDirty 恒真）
  dirtyJsonSet.value.clear();
  // 重置 dirty 基准：刚加载的数据视为"干净状态"
  pristineSnapshot.value = JSON.stringify(meta);
}

/**
 * 新建项目：写入与"默认控件 6 个"对齐的最小骨架。
 *
 * **覆盖范围**：与 widget-schemas.ts 中 `required: true` 的 6 个 widget 一一对应：
 *
 * - 顶层标量：`name / rendererScale / debugger / meterScale`
 * - 顶层对象：`gaussianSplatting (SplatConfig 必需子字段)`
 * - 嵌套虚拟节点：`initial.player (position / rotation 必填)`
 *
 * **不写**的字段：
 * - `collision` / `interactive`：ProjectConfig 类型上必需但归为可添加，避免新建
 *   就塞空 URL 控件；用户首次"添加 collision"或"添加 interactive"时再写骨架（onAddWidget）
 * - 其它可选字段（`camera` / `terrain` / `lighting` / 等）：按需添加
 *
 * 默认值原则：
 * - 数值取"中性"默认（缩放=1、阶=0）
 * - URL/路径留空字符串
 * - transform 用 SDK 文档约定默认（rotation 弧度、scale=[1,1,1]）
 */
function buildBlankMeta(): Record<string, any> {
  return buildProjectConfigSkeleton() as Record<string, any>;
}

const importInputRef = ref<HTMLInputElement | null>(null);
const assetsDirInputRef = ref<HTMLInputElement | null>(null);

const onTopBarAction = (
  action: 'new' | 'import' | 'export' | 'load-example' | 'load-assets-dir' | 'save' | 'reload',
) => {
  if (action === 'new') void doNew();
  else if (action === 'import') void doImport();
  else if (action === 'export') void doExport();
  else if (action === 'load-example') void doLoadExample();
  else if (action === 'load-assets-dir') doLoadAssetsDir();
  else if (action === 'save') void saveToDisk();
  else if (action === 'reload') void reloadFromDisk();
};

/** 新建：未保存防呆 + 写入空骨架 */
async function doNew(): Promise<void> {
  if (!(await confirmDiscardIfDirty('新建项目', '新建项目将丢弃当前未保存的修改，是否继续？'))) return;
  // 新建会清空数据，与之关联的本地文件登记也应一并清空（meta 里没有任何字段引用它们）
  // 新建没有本地托管根 → 退出托管工作区模式
  FileBundle.clear();
  FileBundle.setAssetsBaseUrl(null);
  exitWorkspaceMode();
  workspaceMode.value = false;
  setMeta(buildBlankMeta());
}

/** 加载示例：把内置 mock（ChineseGarden）灌进去，方便快速看到所有控件 */
async function doLoadExample(): Promise<void> {
  if (!(await confirmDiscardIfDirty('加载示例', '加载示例将丢弃当前未保存的修改，是否继续？'))) return;
  // 示例数据全是远程 URL，不会用到本地文件登记，先清掉
  FileBundle.clear();
  FileBundle.setAssetsBaseUrl(null);
  // 示例数据无本地托管根 → 退出托管工作区模式
  exitWorkspaceMode();
  workspaceMode.value = false;
  // 深拷贝避免污染 mockMetaJson 的 import 引用
  setMeta(JSON.parse(JSON.stringify(mockMetaJson)));
}

/**
 * Raw 模式"应用"按钮回调：把用户编辑后的 JSON 对象灌进 meta。
 *
 * RawModePanel 已经做过 JSON.parse 和 isObject 校验，这里仅负责整体替换。
 * 复用 setMeta 让 normalizeMeta 自动跑一次（修非法形态），并清空选中态。
 *
 * FileBundle 处理：raw 应用可能改了字段值（指向不同文件 / 改成远程 URL），
 * 此时 FileBundle 中的旧条目可能成为孤儿；做一次 GC 释放内存（不再被任何字段引用的清掉）。
 */
async function onRawApply(parsed: Record<string, any>): Promise<void> {
  setMeta(parsed);
  // GC：以新 meta 为基准，清掉 FileBundle 中不再被引用的本地文件
  const stillReferenced = new Set(await collectLocalPathsInMeta(meta));
  for (const [path] of FileBundle.entries()) {
    if (!stillReferenced.has(path)) FileBundle.unregister(path);
  }
  // 用户在 raw 模式应用后通常想看场景层级树效果，自动切回场景编辑 tab
  activeTab.value = 'scene';
}

/** 导入：触发隐藏 input click，文件选完后由 onImportFileChosen 处理 */
/**
 * 导入入口：先弹"来源选择"对话框（本地文件 / 远程 URL），再分发到对应流程。
 *
 * 两种来源的差异点：
 * - **本地**：触发隐藏 `<input type="file">` click，文件选完后由 onImportFileChosen 处理；
 *   .json 单文件流程会再问一次"是否授权目录"以加载相对路径素材。
 * - **远程**：用 fetch 拉 URL，解析为 JSON；如果是相对路径素材，自动以 URL 所在目录
 *   作为 baseURL 调 fetchByPath 拉到 FileBundle（与本地导入对齐）。
 *
 * 用户取消选择来源 / 关闭对话框 → 退出，不做任何改动。
 */
async function doImport(): Promise<void> {
  if (!(await confirmDiscardIfDirty('导入文件', '导入文件将覆盖当前未保存的修改，是否继续？'))) return;

  const choice = await importSourceDialog();
  if (!choice) return;

  if (choice === 'local') {
    // 重置 value 让连续选同一个文件也能触发 change
    if (importInputRef.value) importInputRef.value.value = '';
    importInputRef.value?.click();
    return;
  }

  // 远程 URL 导入
  await importFromRemoteUrl(choice.url);
}

/**
 * 从远程 URL 导入 .json 配置 + 自动拉取相对路径素材。
 *
 * 流程：
 * 1. fetch URL 拿到 JSON 文本（CORS 失败 / 4xx / Content-Type=html → 报错退出）
 * 2. 解析为对象，setMeta 替换当前 meta
 * 3. 计算 baseURL = URL 去掉文件名后的部分（如 `https://cdn.example.com/proj/splat.json` → `https://cdn.example.com/proj/`）
 * 4. 收集 meta 中相对路径素材，调 fetchByPath(paths, baseUrl) 自动并发下载到 FileBundle
 * 5. 报告加载结果（成功/失败明细）
 *
 * **不做的事**：不弹"目录授权"——远程导入语义就是"从 URL 拉一切"，没必要让用户再选目录。
 */
async function importFromRemoteUrl(url: string): Promise<void> {
  const busy = beginBusy({
    title: '正在加载远程配置',
    detail: url,
    percent: null,
  });
  try {
    let resp: Response;
    try {
      resp = await fetch(url);
    } catch (err) {
      // 跨域 / 网络错误 → fetch 直接 throw（typeof TypeError），错误信息一般是 "Failed to fetch"
      // eslint-disable-next-line no-console
      console.error('[MetaEditor] 远程导入 fetch 失败：', err);
      pushToast({
        type: 'error',
        title: '加载失败',
        message:
          `无法访问该 URL：${(err as Error).message || 'Failed to fetch'}\n\n` +
          `常见原因：\n` +
          `· 远程站点未允许跨域 (CORS)，浏览器阻断了请求\n` +
          `· 网络不通 / DNS 解析失败\n` +
          `· URL 协议不被支持（仅 http/https）\n\n` +
          `若是 CORS 问题，建议把文件下载到本地后用"本地文件"导入。`,
        duration: 9000,
      });
      return;
    }

    if (!resp.ok) {
      pushToast({
        type: 'error',
        title: '加载失败',
        message: `服务器返回 HTTP ${resp.status} ${resp.statusText || ''}`.trim(),
      });
      return;
    }

    // SPA fallback 防御：若返回 HTML 视为"配置文件不存在"
    const ct = resp.headers.get('content-type') || '';
    if (/^text\/html\b/i.test(ct)) {
      pushToast({
        type: 'error',
        title: '加载失败',
        message: '响应不是 JSON 内容（被 SPA 路由兜底为 HTML），URL 指向的配置文件可能不存在',
      });
      return;
    }

    const text = await resp.text();
    let parsed: any;
    try {
      parsed = JSON.parse(text);
    } catch (err) {
      pushToast({
        type: 'error',
        title: '解析失败',
        message: `URL 指向的内容不是合法 JSON：${(err as Error).message}`,
      });
      return;
    }
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      pushToast({ type: 'error', message: '导入失败：JSON 根必须是对象' });
      return;
    }

    // 推导 baseURL：URL 去掉文件名后保留目录（含末尾 /）
    // 示例 'https://cdn.example.com/proj/splat.json' → 'https://cdn.example.com/proj/'
    const baseUrl = new URL('.', url).toString();

    // 接管 meta（清空 FileBundle 让远程素材独占）
    // 先 setAssetsBaseUrl 并预取素材，最后 setMeta 触发一次重建——此时 baseUrl 已就位
    // 且远程素材已填充 FileBundle，避免"先 setMeta 空 FileBundle 加载失败 + 素材预取后
    // 指纹变化再重建"的双重加载。
    FileBundle.clear();
    FileBundle.setAssetsBaseUrl(baseUrl);
    // 远程导入没有本地可写目录根 → 退出托管工作区模式（保持内存沙盒 + 导出）
    exitWorkspaceMode();
    workspaceMode.value = false;

    const localPaths = await collectLocalPathsInMeta(parsed);
    if (localPaths.length === 0) {
      setMeta(parsed);
      pushToast({
        type: 'success',
        title: '导入成功',
        message: '已加载远程配置（无相对路径素材）',
        duration: 3500,
      });
      return;
    }

    busy.update({
      title: '加载远程素材',
      detail: `0 / ${localPaths.length}`,
      percent: 0,
    });
    const report = await fetchByPath(localPaths, baseUrl, (p) => {
      busy.update({
        detail: `${p.done} / ${p.total} · ${p.path.split('/').pop() || p.path}`,
        percent: (p.done / p.total) * 100,
      });
    });
    reportLoad(report, '加载远程素材');
    setMeta(parsed);
  } catch (err) {
    pushToast({
      type: 'error',
      title: '导入失败',
      message: (err as Error).message || String(err),
    });
  } finally {
    busy.end();
  }
}

const onImportFileChosen = async (e: Event): Promise<void> => {
  const input = e.target as HTMLInputElement;
  const file = input.files?.[0];
  if (!file) return;

  const isZip =
    /\.zip$/i.test(file.name) || file.type === 'application/zip' || file.type === 'application/x-zip-compressed';

  try {
    if (isZip) {
      await importFromZip(file);
    } else {
      await importFromJson(file);
    }
  } catch (err) {
    alert(`导入失败：${(err as Error).message}`);
  }
};

/** .json 单文件导入：原行为 + 自动尝试加载素材
 *
 * 加载素材的策略（按优先级）：
 * 1. **File System Access API**（Chromium 系桌面）：
 *    - 弹 confirm 询问用户是否授权一个目录（建议指向 .json 所在目录），
 *    - 用户授权后，按 meta 中引用的相对路径**精确读取**所需文件（不需要把整目录全加载）。
 *    - 用户取消授权 → 跳过素材加载，仅完成 meta 导入（用户后续可手工上传）。
 * 2. **不支持 FS Access API**（Firefox / Safari 等）：
 *    - 弹 confirm 询问用户是否选择一个目录，确认后用 `<input webkitdirectory>` 让其挑目录，
 *    - 整目录加载，按 meta 引用的路径过滤报告缺失项。
 *    - 用户取消 → 仅完成 meta 导入。
 *
 * 不再做 `fetchByPath` 兜底：相对路径在浏览器里没有"原始 .json 所在目录"的概念，
 * 用 dev server 根猜测命中率几乎为零，反而会刷出一堆 404 噪音。
 */
async function importFromJson(file: File): Promise<void> {
  const busy = beginBusy({
    title: '正在导入',
    detail: `读取 ${file.name}...`,
    percent: null,
  });
  try {
    const text = await file.text();
    const parsed = JSON.parse(text);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      pushToast({ type: 'error', message: '导入失败：JSON 根必须是对象' });
      return;
    }
    // 纯 JSON 导入 → 清空 FileBundle（之前的本地文件登记跟新数据无关）
    // 本地导入没有"远程根目录"概念，重置 baseUrl=null（PreviewPanel 回落到 document.baseURI）
    FileBundle.clear();
    FileBundle.setAssetsBaseUrl(null);

    // 先基于 parsed 收集本地路径（不 setMeta——PreviewPanel 尚未重建，无空档期）
    const localPaths = await collectLocalPathsInMeta(parsed);

    // 暂时收起 busy，避免遮罩盖住浏览器自带的目录授权弹窗
    busy.update({ title: '等待授权目录', detail: '请在弹窗中授权 / 选择目录', percent: null });

    // 本地导入统一尝试进入「托管工作区」模式：授权 readwrite 目录（meta 所在目录）。
    // 先授权并加载素材，加载完成后再 setMeta。
    // 原因：若先 setMeta，PreviewPanel 立即重建，而此时 FileBundle 为空 → 本地资源加载报错；
    // 授权完成后 FileBundle 填充 → 指纹变化 → 再次重建（重复加载）。延后 setMeta 保证
    // 整条导入流程只触发一次重建，且重建时素材已就绪。
    const hosted = await loadAssetsForImportedMeta(file.name, localPaths, busy, parsed);
    workspaceMode.value = hosted;
    setMeta(parsed);

    if (localPaths.length === 0) {
      // 无素材引用：托管成功与否都提示导入成功（托管时补充说明）。
      pushToast({
        type: 'success',
        message: hosted ? `导入成功：${file.name}（已托管工作区）` : `导入成功：${file.name}`,
        duration: 2500,
      });
    }
  } catch (err) {
    pushToast({
      type: 'error',
      title: '导入失败',
      message: (err as Error).message || String(err),
    });
  } finally {
    busy.end();
  }
}

/**
 * 导入 .json 后：让用户选择一个目录授权，然后按 meta 引用的相对路径加载素材。
 *
 * 参数 busy 是已经创建好的进度遮罩实例，本函数负责更新它的文案 / 进度。
 *
 * 行为分支：
 * - 浏览器支持 FS Access API → 先 confirm，确认后调 `pickDirectoryHandle` + `loadFromDirectoryHandle`
 * - 否则 → confirm 后用隐藏的 `<input webkitdirectory>` 让用户挑目录（loadFromFiles）
 * - 用户在任意环节取消 → 仅完成 meta 导入，提示"可后续手工补充"
 */
/**
 * 生成"授权目录"提示：列出配置引用的相对路径，并说明应选择哪个目录。
 *
 * 核心语义：meta 内的相对路径（如 `collision.url = "assets/x.glb"`）是**相对
 * meta.json 所在目录**书写的；`loadFromDirectoryHandle` 以授权目录为"解析根"，
 * 从根开始逐级按该相对路径查找文件。因此：
 * - 正确做法 = 授权 **meta.json 所在目录（项目根）**：素材即使分散在 assets/、
 *   npcs/、models/ 等多个子目录，授权它们的公共祖先（meta.json 所在目录）即可
 *   一次全部覆盖——无需对每个子目录单独授权
 * - 不要授权 meta.json 所在目录的**上级**：平级引用（无 `../`）会整体"垫高"一级
 *   导致路径错位（例如授权父目录后找 `父目录/assets/x.glb`，而文件实际在
 *   `父目录/项目名/assets/x.glb`）
 * - 仅当配置内部含 `../` 上溯且需要越出项目根时，才需要授权更高层目录
 * - 授权 meta.json 所在目录的**子目录**会导致其它目录的素材读不到
 */
function buildAssetDirHint(localPaths: string[]): string {
  const sample = localPaths.slice(0, 5);
  const lines = sample.map((p) => `· ${p}`);
  const more = localPaths.length > sample.length ? `\n  ...另有 ${localPaths.length - sample.length} 个` : '';
  return (
    `配置引用的相对路径（以 meta.json 所在目录为基准）：\n${lines.join('\n')}${more}\n\n` +
    `请授权【meta.json 所在目录】（即包含这些路径的项目根目录）：\n` +
    `· 素材可能分布在多个子目录（assets/、npcs/、models/ 等），授权它们的公共上级 ——\n` +
    `  meta.json 所在目录 —— 即可一次全部读取，无需对每个目录分别授权\n` +
    `· 不要授权 meta.json 所在目录的上级或更下层子目录，否则会提示文件未找到\n\n` +
    `选错目录可重新选择；未读取到的素材在导出 zip 时会提示缺失。`
  );
}

async function loadAssetsForImportedMeta(
  importedFileName: string,
  localPaths: string[],
  busy: ReturnType<typeof beginBusy>,
  metaValue: any,
): Promise<boolean> {
  const fileCount = localPaths.length;
  try {
    if (isFileSystemAccessSupported()) {
      // 授权目录（readwrite）：本地导入统一进入「托管工作区」模式，句柄可读可写。
      // fileCount===0 时仅托管（无素材可加载），文案强调托管语义；有素材则沿用加载文案。
      const ok = await confirmDialog({
        title: fileCount > 0 ? '加载本地素材' : '托管工作区',
        message:
          fileCount > 0
            ? `检测到 ${importedFileName} 引用了 ${fileCount} 个本地素材。\n` +
              `由于浏览器无法直接读取你电脑上的文件，需要授权一个目录。\n\n` +
              buildAssetDirHint(localPaths) +
              '\n' +
              `授权后编辑器将「托管」该目录：修改配置可直接保存回磁盘，上传的素材也会落盘到该目录。`
            : `检测到 ${importedFileName} 没有引用本地素材。\n` +
              `如需「托管」该项目工作区（编辑配置后直接保存回磁盘、上传素材自动落盘），` +
              `请授权该文件所在的目录。\n\n` +
              `取消则退回内存编辑模式（改动通过「导出文件」下载）。`,
        okText: '选择目录授权',
        cancelText: fileCount > 0 ? '稍后手动上传' : '暂不托管',
        variant: 'info',
      });
      if (!ok) {
        exitWorkspaceMode();
        if (fileCount > 0) {
          pushToast({
            type: 'info',
            title: '已跳过素材加载',
            message: '可在右侧属性面板手工上传所需素材',
            duration: 4000,
          });
        }
        return false;
      }

      let dirHandle: Awaited<ReturnType<typeof pickDirectoryHandle>> = null;
      try {
        // v2.19.0：导入 json 的素材授权也优先复用会话内已授权目录句柄（与属性面板补读 v2.17 对齐），
        // 避免同一项目连续导入 / 重试时每次重复弹原生目录选择器。
        // 托管模式升级 readwrite：后续「保存写回 / 上传落盘」需要写权限。
        dirHandle = await pickDirectoryHandle('readwrite', undefined, { useCached: true });
      } catch (err) {
        // 不支持 / SecurityError 等：降级到 webkitdirectory（无写能力，无法托管）
        // eslint-disable-next-line no-console
        console.warn('[MetaEditor] pickDirectoryHandle(readwrite) 失败，降级 webkitdirectory：', err);
        exitWorkspaceMode();
        await loadAssetsViaWebkitDirectory(localPaths, busy, true);
        return false;
      }

      if (!dirHandle) {
        // 用户主动取消授权
        exitWorkspaceMode();
        if (fileCount > 0) {
          pushToast({
            type: 'info',
            title: '已跳过素材加载',
            message: '可在右侧属性面板手工上传所需素材',
            duration: 4000,
          });
        }
        return false;
      }

      // 进入托管模式：缓存可写句柄 + meta 文件名，供保存写回 / 从磁盘重载 / 上传落盘使用
      enterWorkspaceMode(dirHandle, importedFileName);

      if (fileCount === 0) {
        pushToast({
          type: 'info',
          title: '已托管工作区',
          message: `编辑后可 Ctrl+S 保存回磁盘：${importedFileName}`,
          duration: 4000,
        });
        return true;
      }

      busy.update({
        title: '加载本地素材',
        detail: `0 / ${fileCount}`,
        percent: 0,
      });
      const updateProgress = (p: { done: number; total: number; path: string }) => {
        busy.update({
          detail: `${p.done} / ${p.total} · ${p.path.split('/').pop() || p.path}`,
          percent: (p.done / p.total) * 100,
        });
      };
      let report = await loadFromDirectoryHandle(dirHandle, localPaths, updateProgress);
      // v2.19.0：复用的缓存目录可能属于其他项目——加载仍有失败时给一次"重新选择目录"机会（强制不走缓存）
      if (report.failed.length > 0) {
        const retry = await confirmDialog({
          title: '部分素材未找到',
          message:
            `仍有 ${report.failed.length} 个素材未加载到（如 ${report.failed[0].path}）。\n\n` +
            `引用的相对路径以 meta.json 所在目录为基准，请授权【meta.json 所在目录】` +
            `（不是它的上级或子目录）。是否重新选择目录？`,
          okText: '重新选择目录',
          cancelText: '算了',
          variant: 'warn',
        });
        if (retry) {
          const fresh = await pickDirectoryHandle('readwrite');
          if (fresh) {
            dirHandle = fresh;
            enterWorkspaceMode(dirHandle, importedFileName);
            report = await loadFromDirectoryHandle(dirHandle, localPaths, updateProgress);
          }
        }
      }
      reportLoad(report, '加载素材');
      // v2.11.0：第二层引用补读——region-replace-config.json 此时已登记，
      // 重新收集 config 内部的地块资源（首次授权时 config 未登记、第 4 步解析不到），补读缺失文件
      await loadRegionReplaceSecondLevel(dirHandle, localPaths, metaValue);
      // v2.7.0：regionReplace 多地块提示（modules.length>1 时地块文件未一并打包）
      void warnRegionReplaceMultiPlot(metaValue);
      pushToast({
        type: 'info',
        title: '已托管工作区',
        message: `编辑后可 Ctrl+S 保存回磁盘：${importedFileName}`,
        duration: 4000,
      });
      return true;
    }

    // 浏览器不支持 FS Access API：无法托管，走 webkitdirectory 兜底（无素材时直接返回）
    exitWorkspaceMode();
    if (fileCount === 0) {
      return false;
    }
    const ok = await confirmDialog({
      title: '加载本地素材',
      message:
        `检测到 ${importedFileName} 引用了 ${fileCount} 个本地素材。\n` +
        `当前浏览器不支持目录授权 API（仅 Chrome / Edge 支持），需要你手动选择一个包含这些素材的目录。\n\n` +
        buildAssetDirHint(localPaths) +
        '\n' +
        `选择目录后，浏览器会读取目录下所有文件（仅读到内存，不会上传到任何服务器）。`,
      okText: '选择目录',
      cancelText: '稍后手动上传',
      variant: 'info',
    });
    if (!ok) {
      pushToast({
        type: 'info',
        title: '已跳过素材加载',
        message: '可在右侧属性面板手工上传所需素材',
        duration: 4000,
      });
      return false;
    }
    await loadAssetsViaWebkitDirectory(localPaths, busy, false);
    // v2.11.0：第二层引用补读（webkitdirectory 已整目录登记；此处仅校验缺失并提示）
    await loadRegionReplaceSecondLevel(null, localPaths, metaValue);
    // v2.7.0：regionReplace 多地块提示（modules.length>1 时地块文件未一并打包）
    void warnRegionReplaceMultiPlot(metaValue);
    return false;
  } catch (err) {
    // 素材加载失败不应阻断导入：toast 提示后返回，由调用方继续 setMeta
    exitWorkspaceMode();
    pushToast({
      type: 'error',
      title: '素材加载失败',
      message: (err as Error).message || String(err),
    });
    return false;
  }
}

/**
 * v2.11.0：region-replace 第二层引用补读。
 *
 * 首次授权时 region-replace-config.json 尚未登记，collectLocalPathsInMeta 只能收集第一层；
 * config 读进来后再收集一次（此时第 4 步能解析内部 modules 资源），把缺失的地块文件补读。
 *
 * - FS Access 分支（dirHandle 非空）：从已授权句柄精确补读缺失路径
 * - webkitdirectory 分支（dirHandle 为 null）：整目录已登记，仅报告仍缺失的路径
 *
 * @param dirHandle FS Access 目录句柄（webkitdirectory 回退传 null）
 * @param firstLevel 第一轮已请求的路径（避免把已请求过的当作缺失重复提示）
 * @param metaValue 导入的 meta 数据（未 setMeta 前的 parsed，避免依赖全局 reactive meta）
 */
async function loadRegionReplaceSecondLevel(
  dirHandle: Awaited<ReturnType<typeof pickDirectoryHandle>> | null,
  firstLevel: string[],
  metaValue: any,
): Promise<void> {
  const deepPaths = await collectLocalPathsInMeta(metaValue);
  const missing = deepPaths.filter((p) => !FileBundle.has(p) && !firstLevel.includes(p));
  if (missing.length === 0) return;

  let report: LoadReport;
  if (dirHandle) {
    report = await loadFromDirectoryHandle(dirHandle, missing);
  } else {
    report = {
      total: missing.length,
      succeeded: [],
      failed: missing.map((p) => ({ path: p, reason: '所选目录中未找到对应文件' })),
    };
  }
  if (report.succeeded.length > 0) {
    pushToast({
      type: 'success',
      title: '多地块素材补读',
      message: `已补读 ${report.succeeded.length} 个地块文件`,
      duration: 3000,
    });
  }
  const stillMissing = report.failed.filter((f) => !firstLevel.includes(f.path));
  if (stillMissing.length > 0) {
    pushToast({
      type: 'warn',
      title: '部分多地块素材缺失',
      message:
        `${stillMissing.length} 个地块文件未加载（详见 Console）：\n` +
        stillMissing
          .slice(0, 3)
          .map((f) => `· ${f.path}`)
          .join('\n') +
        (stillMissing.length > 3 ? `\n...另有 ${stillMissing.length - 3} 个` : '') +
        `\n\n若这些文件在远程服务器：把清单（manifest）的 baseUrl 改为绝对 URL（http(s)://…），` +
        `编辑器将视为远程引用、不再要求本地存在；导出时会自动从远程下载并本地化。`,
      duration: 6000,
    });
    // eslint-disable-next-line no-console
    console.warn('[MetaEditor] 多地块素材缺失：', stillMissing.map((f) => `${f.path} (${f.reason})`).join('\n'));
  }
}

/**
 * webkitdirectory 兜底：等待用户在隐藏 input 上选目录，再批量登记。
 *
 * Promise 在 input change 触发后 resolve；超过 60s 未操作或弹窗被关闭无法可靠探测，
 * 但 input 不消费时也无副作用——下次再触发会覆盖。
 *
 * @param fromAccessApiFallback 是否是从 FS Access API 失败降级而来（影响提示文案）
 */
async function loadAssetsViaWebkitDirectory(
  localPaths: string[],
  busy: ReturnType<typeof beginBusy>,
  fromAccessApiFallback: boolean,
): Promise<void> {
  const inputEl = assetsDirInputRef.value;
  if (!inputEl) {
    pushToast({ type: 'error', message: '内部错误：目录选择 input 未就绪' });
    return;
  }
  inputEl.value = '';

  // 用一个一次性的 change 监听把异步流程串起来
  const filesPromise = new Promise<FileList | null>((resolve) => {
    const handler = () => {
      inputEl.removeEventListener('change', handler);
      resolve(inputEl.files && inputEl.files.length > 0 ? inputEl.files : null);
    };
    inputEl.addEventListener('change', handler);
    inputEl.click();
  });

  busy.update({
    title: '等待选择素材目录',
    detail: fromAccessApiFallback ? '已降级到目录选择' : '请在弹窗中选择目录',
    percent: null,
  });

  const files = await filesPromise;
  if (!files) {
    pushToast({
      type: 'info',
      title: '已跳过素材加载',
      message: '可在右侧属性面板手工上传所需素材',
      duration: 4000,
    });
    return;
  }

  busy.update({
    title: '加载本地素材',
    detail: `处理 ${files.length} 个文件...`,
    percent: null,
  });
  const report = loadFromFiles(files, localPaths);
  reportLoad(report, '加载素材');
}

/** 加载素材目录：用户选一个目录，把里面的文件按相对路径登记到 FileBundle */
function doLoadAssetsDir(): void {
  if (isEmptyMeta.value) {
    pushToast({
      type: 'warn',
      message: '请先新建或导入项目，再加载素材目录',
    });
    return;
  }
  if (assetsDirInputRef.value) assetsDirInputRef.value.value = '';
  assetsDirInputRef.value?.click();
}

const onAssetsDirChosen = async (e: Event): Promise<void> => {
  const input = e.target as HTMLInputElement;
  if (!input.files || input.files.length === 0) return;
  const expected = await collectLocalPathsInMeta(meta);
  const report = loadFromFiles(input.files, expected);
  reportLoad(report, '加载素材目录');
};

/**
 * 统一上报加载结果：
 * - 全部成功 → 绿色成功 toast
 * - 部分失败 → 黄色警告 toast，列出前若干条
 * - 全部失败 → 红色错误 toast
 *
 * 失败明细同时打印到 console，方便复制定位。
 */
function reportLoad(report: LoadReport, action: string): void {
  if (report.failed.length === 0 && report.succeeded.length > 0) {
    pushToast({
      type: 'success',
      title: `${action}成功`,
      message: `已加载 ${report.succeeded.length} 个素材文件`,
      duration: 3000,
    });
    return;
  }
  if (report.failed.length > 0) {
    // 控制台详细日志
    // eslint-disable-next-line no-console
    console.warn(`[MetaEditor] ${action} 部分失败：`, report.failed.map((f) => `${f.path} (${f.reason})`).join('\n'));
    const sample = report.failed
      .slice(0, 3)
      .map((f) => f.path)
      .join('\n');
    const more = report.failed.length > 3 ? `\n...另有 ${report.failed.length - 3} 个` : '';
    const allFailed = report.succeeded.length === 0;
    pushToast({
      type: allFailed ? 'error' : 'warn',
      title: allFailed ? `${action}失败` : `${action}部分成功`,
      message:
        (allFailed
          ? `${report.failed.length} 个素材无法加载（详见 Console）：\n`
          : `成功 ${report.succeeded.length} 个，${report.failed.length} 个未找到：\n`) +
        sample +
        more,
      duration: 5500,
    });
  }
}

/**
 * .zip 项目包导入：
 * 1) 找到 zip 内的 `meta.json` 作为主配置
 * 2) 其它文件全部回填 FileBundle，路径 = zip 内相对路径
 * 3) FileBundle 中的路径形态应与 meta.json 内字段值一致（约定：相对路径）
 */
async function importFromZip(file: File): Promise<void> {
  const busy = beginBusy({
    title: '正在导入 zip',
    detail: `解析 ${file.name}...`,
    percent: 0,
  });
  try {
    // JSZip 的 loadAsync 也支持 onUpdate 回调，但只覆盖"读取/解压"阶段；
    // 我们后续 forEach 取每个文件 bytes 才是真正的解码工作，所以分两段进度统计。
    const zip = await JSZip.loadAsync(file);
    const metaEntry = zip.file('meta.json');
    if (!metaEntry) {
      pushToast({
        type: 'error',
        title: '导入失败',
        message: 'zip 包内未找到 meta.json',
      });
      return;
    }
    const metaText = await metaEntry.async('string');
    const parsed = JSON.parse(metaText);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      pushToast({
        type: 'error',
        title: '导入失败',
        message: 'meta.json 根必须是对象',
      });
      return;
    }

    // 收集待解压的非 meta.json 条目（先 enumerate 出来，方便算总数 + 推进度）
    const pending: Array<{ relPath: string; entry: import('jszip').JSZipObject }> = [];
    zip.forEach((relPath, zipEntry) => {
      if (zipEntry.dir) return;
      if (relPath === 'meta.json') return;
      pending.push({ relPath, entry: zipEntry });
    });

    // 重置 FileBundle，再串行回填（串行比 Promise.all 慢一点但能精确推进度）
    // zip 导入没有"远程根目录"概念，重置 baseUrl=null；也没有本地托管根 → 退出托管模式
    FileBundle.clear();
    FileBundle.setAssetsBaseUrl(null);
    exitWorkspaceMode();
    workspaceMode.value = false;
    busy.update({ detail: `0 / ${pending.length}`, percent: 0 });
    for (let i = 0; i < pending.length; i++) {
      const { relPath, entry } = pending[i];
      const bytes = await entry.async('uint8array');
      FileBundle.register(relPath, bytes);
      busy.update({
        detail: `${i + 1} / ${pending.length} · ${relPath.split('/').pop() || relPath}`,
        percent: ((i + 1) / Math.max(pending.length, 1)) * 100,
      });
    }

    setMeta(parsed);
    pushToast({
      type: 'success',
      title: '导入成功',
      message: `已加载 ${pending.length} 个素材文件`,
      duration: 3000,
    });
  } catch (err) {
    pushToast({
      type: 'error',
      title: '导入 zip 失败',
      message: (err as Error).message || String(err),
    });
  } finally {
    busy.end();
  }
}

/**
 * 导出：
 * - 当存在被引用的本地文件 → 打成 zip（meta.json + 各子目录文件）
 * - 否则 → 单文件 .json 下载（保持轻量场景的体验）
 *
 * 文件路径约定：meta 中字段值（如 collision.url='collision/x.glb'）即为 zip 内的相对路径，
 * FileBundle 的 key 与之一一对应，导出时仅打包 meta 中"实际引用到"的本地文件，
 * 不再被引用的孤儿文件会被 GC（不进 zip）。
 *
 * **UI 锁定**：zip 模式下打包是异步的，期间用 BusyOverlay 锁住 UI，避免用户继续编辑导致打包内容前后不一致。
 */
async function doExport(): Promise<void> {
  if (isEmptyMeta.value) {
    pushToast({
      type: 'warn',
      message: '当前没有可导出的数据，请先新建或导入项目',
    });
    return;
  }

  // 必填校验：在生成 snapshot 前跑一次，告诉用户有哪些字段没填。
  // 失败时弹 confirm 让用户选择 "继续导出" / "取消修复"——校验是提示性的，
  // 不强制阻塞（用户可能就是想导出半成品备份）。
  const report = validateRequiredFields(meta, rules.value);
  if (!report.ok) {
    const lines: string[] = [];
    if (report.violations.length > 0) {
      lines.push('· ' + report.violations.join('\n· '));
    }
    if (report.missing.length > 0) {
      const sample = report.missing.slice(0, 8);
      lines.push(...sample.map((m) => `· ${m.widgetId}: ${m.label}（${m.absPath}）`));
      if (report.missing.length > sample.length) {
        lines.push(`...另有 ${report.missing.length - sample.length} 项必填字段未填`);
      }
    }
    const proceed = await confirmDialog({
      title: '导出前检查：存在未配置的必填项',
      message:
        `以下字段是 SDK 渲染场景所必需的，但当前 meta 中缺失：\n\n${lines.join('\n')}\n\n` +
        `继续导出会得到一份"半成品"配置，SDK 加载时会报错。建议先回属性面板补齐再导出。`,
      okText: '仍然导出',
      cancelText: '回去补齐',
      variant: 'warn',
    });
    if (!proceed) return;
  }

  const snapshot = JSON.parse(JSON.stringify(meta));
  const fileName = `${(snapshot.name || 'meta').toString().trim() || 'meta'}`;

  // v2.22.0 + v2.26.0：远程 baseUrl 清单先本地化——region-replace config 与 chunked
  // manifest（collision/terrain/npcs）的 baseUrl 为远程 CDN 时，从 CDN 下载模块到 config
  // 目录镜像布局并改写 baseUrl 为相对路径（覆盖 FileBundle 中的 config/manifest），使下方
  // collectLocalPathsInMeta 解析出干净镜像 key（zip 内 config+模块布局自洽、round-trip 稳定）。
  // 下载全部成功才改写；任一失败保留远程引用原样导出（collect 守卫对绝对 baseUrl 返回空，
  // 不再生成 https:// 畸形 key）。两类本地化各自带一次 configPendingLoad 挂起重建。
  await ensureLocalizedRemoteRegionReplace(snapshot);
  await ensureLocalizedRemoteChunkedManifests(snapshot);

  // 收集 meta 实际引用到的本地路径（避免把已删除字段对应的孤儿文件也打进去）
  const referenced = await collectLocalPathsInMeta(snapshot);
  const referencedExisting = referenced.filter((p) => FileBundle.has(p));
  const missing = referenced.filter((p) => !FileBundle.has(p));

  // v2.10.0：导出前拦截——存在未加载的本地素材时提示（很可能是授权目录错误）。
  // 授权目录是相对路径的解析根：所选目录需能逐级包含 meta 引用的相对路径。
  if (missing.length > 0) {
    const sample = missing.slice(0, 5);
    const proceed = await confirmDialog({
      title: '导出：部分本地素材未加载',
      message:
        `以下 ${missing.length} 个本地素材引用在文件登记中不存在：\n\n` +
        sample.map((p) => `· ${p}`).join('\n') +
        (missing.length > sample.length ? `\n  ...另有 ${missing.length - sample.length} 个` : '') +
        `\n\n如果此前通过"授权目录"加载过素材，可能是授权目录不正确——所选目录需能逐级包含` +
        `meta 中引用的相对路径（例如引用 \`region-replace/config.json\` 时，应选择 \`region-replace\` 的上级目录）。\n\n` +
        `可以回属性面板手工上传缺失素材，或仍然导出（zip 将缺失这些文件）。`,
      okText: '仍然导出',
      cancelText: '回去补齐',
      variant: 'warn',
    });
    if (!proceed) return;
  }

  if (referencedExisting.length === 0) {
    // 纯远程 / 无本地文件登记：单 .json 下载（同步快操作，不需要进度条）
    downloadBlob(JSON.stringify(snapshot, null, 2), `${fileName}.json`, 'application/json;charset=utf-8');
    if (missing.length > 0) {
      pushToast({
        type: 'warn',
        title: '已导出 JSON（不含素材）',
        message: `检测到 ${missing.length} 个本地素材引用未加载，导出仅含 meta.json`,
        duration: 6000,
      });
    } else {
      pushToast({
        type: 'success',
        message: `已导出 ${fileName}.json`,
        duration: 2500,
      });
    }
  } else {
    // 含本地文件：打 zip（耗时操作，锁 UI + 显示进度）
    await exportAsZip(snapshot, referencedExisting, fileName);
    const tip =
      missing.length > 0
        ? `已打包 ${referencedExisting.length} 个素材，仍有 ${missing.length} 个未加载（详见 Console）`
        : `已打包 ${referencedExisting.length} 个素材`;
    if (missing.length > 0) {
      // eslint-disable-next-line no-console
      console.warn('[MetaEditor] 导出 zip 中缺失的素材路径：', missing);
    }
    pushToast({
      type: missing.length > 0 ? 'warn' : 'success',
      title: `已导出 ${fileName}.zip`,
      message: tip,
      duration: 3500,
    });
  }

  // 导出 == 落地保存：重置 dirty 基准 + 清空脏内部 json 集合（子 json 已打包进 zip）
  dirtyJsonSet.value.clear();
  pristineSnapshot.value = JSON.stringify(meta);
}

/**
 * 托管工作区模式：手动保存（Ctrl+S / 文件菜单「保存」）。
 *
 * 把当前 meta 主配置 + 被编辑过的内部 json 清单写回磁盘对应文件：
 * - meta 主配置 → `writeFileToDirectory(root, metaName, JSON.stringify(meta))`
 * - 脏内部 json（dirtyJsonSet，子编辑器编辑过的 region-replace / npcs / chunked 清单）
 *   → 逐个 `writeFileToDirectory(root, cfgPath, entry)`
 *
 * 内存仍是编辑真相源（写盘单向落地），写盘不触发 PreviewPanel 重建（FileBundle 内容
 * 未变，不增 contentVersion）。保存后重置 pristineSnapshot（对齐「导出 == 落地保存」）。
 */
async function saveToDisk(): Promise<void> {
  if (!workspaceMode.value) {
    pushToast({
      type: 'warn',
      message: '当前未处于托管工作区模式，请用「导出文件」下载',
    });
    return;
  }
  const root = getWorkspaceRoot();
  const metaName = getWorkspaceMetaName();
  if (!root || !metaName) {
    pushToast({ type: 'warn', message: '托管元信息缺失，请重新导入项目' });
    return;
  }

  const jsonCount = dirtyJsonSet.value.size;
  const busy = beginBusy({ title: '保存到磁盘', detail: metaName, percent: null });
  try {
    await ensureReadWritePermission(root);
    // 1) 写回 meta 主配置
    await writeFileToDirectory(root, metaName, JSON.stringify(meta, null, 2));
    // 2) 写回被编辑过的内部 json（仅脏集合，避免全量写盘）
    for (const cfgPath of dirtyJsonSet.value) {
      const entry = FileBundle.get(cfgPath);
      if (!entry) continue;
      await writeFileToDirectory(root, cfgPath, entry);
    }
    dirtyJsonSet.value.clear();
    // 保存 == 落地：重置 dirty 基准
    pristineSnapshot.value = JSON.stringify(meta);
    pushToast({
      type: 'success',
      title: '已保存到磁盘',
      message: jsonCount > 0 ? `${metaName}（含 ${jsonCount} 个内部 json）` : metaName,
      duration: 3000,
    });
  } catch (err) {
    pushToast({
      type: 'error',
      title: '保存失败',
      message: (err as Error).message || String(err),
    });
  } finally {
    busy.end();
  }
}

/**
 * 托管工作区模式：从磁盘重载（文件菜单「从磁盘重载」）。
 *
 * 把磁盘上的 meta 主配置重新读回编辑器，并重读其引用的本地素材（覆盖内存），用于
 * 外部修改后手动同步。有未保存修改先 confirmDiscardIfDirty 防呆。
 */
async function reloadFromDisk(): Promise<void> {
  if (!(await confirmDiscardIfDirty('从磁盘重载', '从磁盘重载将丢弃当前未保存的修改，是否继续？'))) return;
  const root = getWorkspaceRoot();
  const metaName = getWorkspaceMetaName();
  if (!root || !metaName) {
    pushToast({ type: 'warn', message: '当前未处于托管工作区模式' });
    return;
  }

  const busy = beginBusy({ title: '从磁盘重载', detail: `读取 ${metaName}...`, percent: null });
  try {
    // 关闭子编辑器（整栈清空）：JsonSubEditorPanel 的 draft 在 setup 一次性初始化
    // （不响应 FileBundle 变化），若重载时子编辑器仍开着，draft 会停留在旧的 json 内容、
    // 组件 key（cfgPath）不变也不重挂载。关闭后用户重新打开，会从已刷新的 FileBundle 读到磁盘新内容。
    subEditorStack.value = [];

    // 读回 meta 主配置
    const fileHandle = await root.getFileHandle(metaName);
    const file = await fileHandle.getFile();
    const text = await file.text();
    const parsed = JSON.parse(text);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      pushToast({ type: 'error', message: '磁盘上的 meta 文件不是合法 JSON 对象' });
      return;
    }

    // 清空并重读素材（本地导入没有远程根目录概念，重置 baseUrl）
    FileBundle.clear();
    FileBundle.setAssetsBaseUrl(null);
    const localPaths = await collectLocalPathsInMeta(parsed);
    if (localPaths.length > 0) {
      busy.update({ title: '重读素材', detail: `0 / ${localPaths.length}`, percent: 0 });
      const report = await loadFromDirectoryHandle(root, localPaths, (p) => {
        busy.update({
          detail: `${p.done} / ${p.total} · ${p.path.split('/').pop() || p.path}`,
          percent: (p.done / p.total) * 100,
        });
      });
      reportLoad(report, '重读素材');
    }
    // 第二层资源重读：第一轮已把 config/manifest 本体（regionReplaceConfigPath/configFile/
    // chunkedUrl 指向的文件）登记进 FileBundle，此时再 collectLocalPathsInMeta 一轮即可解析出
    // 其内部资源（ply_name/collision_name / npcs modelFilePath/imagePath / chunked 模块 url）。
    // 否则外部修改子 json 里的资源路径后，重载只读回 config 本体、内部资源文件不重读，预览缺资源。
    busy.update({ title: '重读第二层资源', detail: '解析 config 内部引用...', percent: null });
    await loadRegionReplaceSecondLevel(root, localPaths, parsed);
    dirtyJsonSet.value.clear();
    setMeta(parsed);
    pushToast({ type: 'success', message: `已从磁盘重载：${metaName}`, duration: 3000 });
  } catch (err) {
    pushToast({
      type: 'error',
      title: '重载失败',
      message: (err as Error).message || String(err),
    });
  } finally {
    busy.end();
  }
}

/**
 * 用 JSZip 把 meta.json + 所有被引用的本地文件打包下载。
 *
 * 进度阶段：
 * 1) 写入 meta.json + 各文件条目（瞬时，进度从 0 → 5）
 * 2) `zip.generateAsync` 生成 blob（耗时，由 onUpdate 回调推 5 → 95）
 * 3) Blob 生成完毕到触发下载（95 → 100）
 *
 * 期间用 BusyOverlay 锁 UI，try/finally 确保异常时也能释放。
 *
 * **进度平滑**：JSZip 对小文件 / 已压缩资源（splat/glb 等）的 onUpdate 触发非常稀疏，
 * 容易出现"卡在 37% 然后直接 100%"的视觉错觉。这里用一个 setInterval 平滑器：
 * - onUpdate 拿到真实进度 → 作为"目标值"
 * - 平滑器每 50ms 把显示进度向目标值靠拢（每步最多 +1.5）
 * - 这样视觉上始终是连续过渡，不影响真实完成时机（完成后强制拉满）
 */
async function exportAsZip(snapshot: Record<string, any>, paths: string[], fileName: string): Promise<void> {
  const busy = beginBusy({
    title: '正在导出 zip',
    detail: '准备文件...',
    percent: 0,
  });

  // 进度平滑器：targetPercent 是 onUpdate 给的真值，displayPercent 是 UI 显示值
  let targetPercent = 5;
  let displayPercent = 0;
  let currentFileLabel = '准备文件...';
  const smoother = window.setInterval(() => {
    if (displayPercent < targetPercent) {
      // 距离越远走得越快，但单次最多 +1.5%，保持视觉平滑
      const gap = targetPercent - displayPercent;
      const step = Math.min(1.5, Math.max(0.3, gap * 0.15));
      displayPercent = Math.min(targetPercent, displayPercent + step);
      busy.update({ detail: currentFileLabel, percent: displayPercent });
    }
  }, 50);

  try {
    const zip = new JSZip();
    zip.file('meta.json', JSON.stringify(snapshot, null, 2));

    for (const path of paths) {
      const entry = FileBundle.get(path);
      if (!entry) continue;
      // zip 内路径用规范化形式（不带前导 ./ 或 /），避免不同打包工具的兼容问题。
      // meta.json 中字段值保持用户原样写法（含 ./），下次解压时 FileBundle.normalizePath 让两边对齐。
      const zipPath = FileBundle.normalizePath(path);
      zip.file(zipPath, entry as Blob | Uint8Array);
    }

    targetPercent = 5;
    currentFileLabel = '压缩中...';

    const blob = await zip.generateAsync(
      {
        type: 'blob',
        compression: 'DEFLATE',
        compressionOptions: { level: 6 },
      },
      (metadata) => {
        // metadata.percent 是 0-100；映射到 5-95 区间，给前置和收尾各留 5%
        targetPercent = 5 + (metadata.percent / 100) * 90;
        currentFileLabel = metadata.currentFile
          ? `压缩中：${metadata.currentFile.split('/').pop() || metadata.currentFile}`
          : '压缩中...';
      },
    );

    // 压缩已完成 → 把目标拉到 95；后面触发下载再拉满 100
    targetPercent = 95;
    currentFileLabel = '触发下载...';

    // 下载
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${fileName}.zip`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);

    // 强制拉满（停止平滑器后立即推到 100，避免最后还卡几个百分点）
    targetPercent = 100;
    displayPercent = 100;
    busy.update({ detail: '完成', percent: 100 });
  } finally {
    window.clearInterval(smoother);
    busy.end();
  }
}

/** 触发浏览器下载（纯文本/单文件场景） */
function downloadBlob(content: string, fileName: string, mime: string): void {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/**
 * v2.7.0：regionReplace 多地块本地导入提示。
 *
 * regionReplaceConfigPath 指向的 JSON 内部 `modules[]` 每个元素又引用一组地块文件
 * （url[] / mortonConfig），这些**第二层引用**不会被 collectLocalPathsInMeta 收集
 * （它只收集字段自身值，不递归解析 JSON 内容）。因此：
 * - 本地导入多地块 region-replace 配置 → 只有 config JSON 被打包，地块文件缺失 →
 *   场景加载不出来（PreviewPanel 用 blob URL 指到 config，SDK 按相对路径找地块 → 404）
 * - 导出 zip → 同样只含 config JSON，不含地块文件
 *
 * 本函数在素材加载完成后检测：若 FileBundle 里有 regionReplaceConfigPath 对应的 JSON
 * 且解析后 `modules.length > 1`（多地块），弹 confirm 提示风险，不阻断流程。
 *
 * @param value 当前 meta（含 gaussianSplatting.regionReplaceConfigPath 本地路径）
 */
async function warnRegionReplaceMultiPlot(value: any): Promise<void> {
  const cfgPath = value?.gaussianSplatting?.regionReplaceConfigPath;
  if (typeof cfgPath !== 'string' || !cfgPath || !FileBundle.isLocalPath(cfgPath)) {
    return;
  }
  const entry = FileBundle.get(cfgPath);
  if (!entry) return;

  // entry 可能是 Blob / Uint8Array / ArrayBuffer
  let text: string;
  try {
    if (typeof TextDecoder === 'function') {
      text =
        entry instanceof Blob
          ? await new Response(entry).text()
          : new TextDecoder('utf-8').decode(entry as Uint8Array | ArrayBuffer);
    } else {
      text = entry instanceof Blob ? await entry.text() : String(entry);
    }
  } catch {
    return;
  }

  let parsed: { modules?: unknown[] } | null = null;
  try {
    parsed = JSON.parse(text) as { modules?: unknown[] };
  } catch {
    return;
  }

  const moduleCount = Array.isArray(parsed?.modules) ? parsed.modules.length : 0;
  if (moduleCount <= 1) return;

  const moduleName = FileBundle.safeFileName(cfgPath);
  await confirmDialog({
    title: '多地块 region-replace 提示',
    message:
      `检测到 ${moduleName} 是多地块配置（${moduleCount} 个模块）。\n\n` +
      `本地导入只打包了配置文件本身，各地块引用的场景文件（url[] / mortonConfig）未一并收集：\n` +
      `· 编辑器内预览可能无法加载全部地块\n` +
      `· 导出 zip 时不包含地块文件，需另行部署到服务器\n\n` +
      `建议：把地块文件放入同一目录，托管到服务器后用"远程 URL 导入"。`,
    okText: '知道了',
    cancelText: '关闭',
    variant: 'info',
  });
}

/**
 * 收集 meta 中"应当作为本地素材打包"的字符串值。
 *
 * **严格基于 rules 的字段声明**：只扫描那些在 widget-schemas 中显式标记了 `bundleDir` 的
 * FieldUrl 字段。其它字符串字段（无论看起来多像路径）一律不参与打包，避免把：
 *
 * - npc 名字（`'默认相机'`、`'去看看'`）
 * - 模型 url（如果用户填了相对路径但该字段未声明 bundleDir）
 * - 按钮文案、提示语
 *
 * 当成"本地素材"误打包。
 *
 * 收集来源（四层）：
 * 1. rules 中标记 bundleDir 的字段（group 直下可静态反查）
 * 2. 深度遍历 meta 全部字段（覆盖数组项 / 联合变体 / 动态 Record 内的资源 URL）
 * 3. region-replace-config.json 内部引用的模块资源（第二层引用，v2.11.0）
 *
 * @returns 唯一化后的本地路径列表（去重）
 */
async function collectLocalPathsInMeta(value: any): Promise<string[]> {
  // 1) 从 rules 反查所有 bundle 字段的"绝对路径"
  const bundleAbsPaths: string[] = [];
  collectBundleFieldPaths(rules.value.widgets, '', bundleAbsPaths);

  // 2) 按这些绝对路径取值
  const out: string[] = [];
  const seen = new Set<string>();
  for (const absPath of bundleAbsPaths) {
    const v = getByPath(value, absPath);
    if (typeof v === 'string' && FileBundle.isLocalPath(v)) {
      // 用 normalize 后的 path 做唯一化键，避免 './x' 和 'x' 重复
      const key = FileBundle.normalizePath(v);
      if (!seen.has(key)) {
        seen.add(key);
        out.push(v);
      }
    }
  }

  // 3) 深度兜底：遍历 meta 全部字段，收集所有「资源 URL 字段名」的本地路径。
  //
  //    为什么需要深度遍历：walkFields（第 1 步）只能静态反查 group 直下字段，无法覆盖：
  //    - 顶层 union widget（collision.url / terrain.url——widget rootPath='' 导致反查路径算错）
  //    - array itemSchema（audio.bgm[].url、lighting.keyframes[].hdriUrl、npc.models[].modelFilePath）
  //    - union variant / auto-object（interaction.shape.mesh.url、interactionZones 动态 Record key）
  //
  //    字段名判定复用 build-editor-rules 的 resolveResourceBundleDir（v1.6.0 导出，单一真相源）：
  //    具名白名单（imagePath/modelFilePath/audioUrl/hdriUrl/dataUrl/r16Url 等）+ 裸 url → 收集；
  //    baseUrl/chunkedUrl/setPath/zoneNavigateUrl 等内部引用天然排除。
  const stack: unknown[] = [value];
  const visited = new Set<object>();
  while (stack.length > 0) {
    const node = stack.pop();
    if (!node || typeof node !== 'object') continue;
    if (visited.has(node as object)) continue;
    visited.add(node as object);
    if (Array.isArray(node)) {
      for (const item of node) stack.push(item);
      continue;
    }
    for (const [field, v] of Object.entries(node as Record<string, unknown>)) {
      if (v !== null && typeof v === 'object') {
        stack.push(v);
        continue;
      }
      if (typeof v !== 'string' || !FileBundle.isLocalPath(v)) continue;
      if (resolveResourceBundleDir(field.toLowerCase()) === null) continue;
      const key = FileBundle.normalizePath(v);
      if (!seen.has(key)) {
        seen.add(key);
        out.push(v);
      }
    }
  }

  // 4) 第二层引用：region-replace-config.json 内部的模块资源（多地块）。
  //    config 内 modules[].ply_name / collision_name / mortonConfig 相对 config.baseUrl 引用，
  //    不在 meta 字段里——但授权加载 / 导出 zip 必须一并处理，否则地块文件缺失。
  //    仅当 config 已登记到 FileBundle（授权加载/手工上传后）时才能解析其内容。
  const rrPath = value?.gaussianSplatting?.regionReplaceConfigPath;
  if (typeof rrPath === 'string' && rrPath && FileBundle.isLocalPath(rrPath)) {
    const rrEntry = FileBundle.get(rrPath);
    if (rrEntry) {
      const rrPaths = await extractRegionReplaceResourcePaths(rrPath, rrEntry);
      for (const p of rrPaths) {
        const key = FileBundle.normalizePath(p);
        if (!seen.has(key)) {
          seen.add(key);
          out.push(p);
        }
      }
    }
  }

  // 5) 第二层引用：npcs.configFile 内部的 NPC 模型/贴图资源。
  //    config 内 models[].modelFilePath / imagePath 相对 config 所在目录引用，
  //    不在 meta 字段里（编辑器 npcs 面板只展示 configFile 本身），授权加载 / 导出必须一并处理。
  const npcsPath = value?.npcs?.configFile;
  if (typeof npcsPath === 'string' && npcsPath && FileBundle.isLocalPath(npcsPath)) {
    const npcsEntry = FileBundle.get(npcsPath);
    if (npcsEntry) {
      const npcsPaths = await extractNpcsConfigResourcePaths(npcsPath, npcsEntry);
      for (const p of npcsPaths) {
        const key = FileBundle.normalizePath(p);
        if (!seen.has(key)) {
          seen.add(key);
          out.push(p);
        }
      }
    }
  }

  // 6) 第二层引用（v2.20.0，v2.39.2 兼容 chunks 收编形态）：collision / terrain / npcs 的分块清单
  //    内部资源。manifest 内 modules[].url（碰撞 GLB / R16 瓦片）、terrain r16Url、
  //    npcs regions[].configFile 相对 manifest.baseUrl 引用——不在 meta 字段里，
  //    授权加载 / 导出 zip 必须一并处理。仅当 manifest 已登记到 FileBundle 时才能解析其内容。
  //
  //    ⚠️ 路径形态：SDK v1.15.0 起 chunk 声明收编为 `{ chunks: { chunkedUrl } }`，
  //    真实路径是 `npcs.chunks.chunkedUrl`（旧扁平 `npcs.chunkedUrl` 仅存于早期数据）。
  //    原实现只读扁平路径 → chunks 模式下整个第 6 层被跳过 → manifest 内部资源全部漏打包。
  const CHUNKED_DIMENSIONS = ['collision', 'terrain', 'npcs'] as const;
  for (const dimension of CHUNKED_DIMENSIONS) {
    const dimensionNode = value?.[dimension] as { chunks?: { chunkedUrl?: unknown }; chunkedUrl?: unknown } | undefined;
    if (!dimensionNode || typeof dimensionNode !== 'object') continue;
    const chunkedPath = dimensionNode.chunks?.chunkedUrl ?? dimensionNode.chunkedUrl;
    if (typeof chunkedPath !== 'string' || !chunkedPath || !FileBundle.isLocalPath(chunkedPath)) continue;
    const chunkedEntry = FileBundle.get(chunkedPath);
    if (!chunkedEntry) continue;

    let chunkedPaths = await extractChunkedManifestResourcePaths(chunkedPath, chunkedEntry, dimension);
    // npcs 兜底：编辑器里 legacy 单文件清单（{models, list}）是主要使用形态，用户可能把它放在
    // chunks.chunkedUrl 字段（变体默认顺序差异所致）。此时 regions[] 提取为 0 引用，但内部
    // models[].modelFilePath / imagePath 相对 config 目录引用，仍需补读与打包（对齐 v1.13.0 的形态兼容）。
    if (dimension === 'npcs' && chunkedPaths.length === 0) {
      chunkedPaths = await extractNpcsConfigResourcePaths(chunkedPath, chunkedEntry);
    }

    for (const p of chunkedPaths) {
      const key = FileBundle.normalizePath(p);
      if (!seen.has(key)) {
        seen.add(key);
        out.push(p);
      }
    }
  }
  return out;
}

/**
 * 从 npcs.configFile（NPC 外部清单 JSON）提取模型/贴图资源相对路径（第二层引用）。
 *
 * 资源来源：深度遍历 config 内容，字段名命中 resolveResourceBundleDir 白名单
 * （modelFilePath→models、imagePath→images、datatextureUrl 等）且值为相对路径 →
 * 以 config 所在目录为基准解析（models[].modelFilePath 形如 `./npc_mesh/xxx.glb`）。
 *
 * 只收集"路径语义"字符串：name/describe/id 等文本字段经白名单天然排除。
 *
 * @param cfgPath FileBundle key（如 `'npcs/chinese-garden-npcs.json'`），用于推导 config 所在目录
 * @param entry config 文件字节（Blob / Uint8Array）
 */
async function extractNpcsConfigResourcePaths(cfgPath: string, entry: Blob | Uint8Array): Promise<string[]> {
  let text: string;
  try {
    text =
      entry instanceof Blob ? await new Response(entry).text() : new TextDecoder('utf-8').decode(entry as Uint8Array);
  } catch {
    return [];
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return [];
  }
  if (!parsed || typeof parsed !== 'object') return [];

  const dirBase = FileBundle.dirname(cfgPath);
  const out: string[] = [];
  const stack: unknown[] = [parsed];
  const visited = new Set<object>();
  while (stack.length > 0) {
    const node = stack.pop();
    if (!node || typeof node !== 'object') continue;
    if (visited.has(node as object)) continue;
    visited.add(node as object);
    if (Array.isArray(node)) {
      for (const item of node) stack.push(item);
      continue;
    }
    for (const [field, v] of Object.entries(node as Record<string, unknown>)) {
      if (v !== null && typeof v === 'object') {
        stack.push(v);
        continue;
      }
      if (typeof v !== 'string' || !v) continue;
      // 命中白名单（modelFilePath/imagePath 等）且是相对路径 → 以 config 目录为基准解析
      if (resolveResourceBundleDir(field.toLowerCase()) === null) continue;
      const resolved = FileBundle.isLocalPath(v) ? FileBundle.joinRelativePath(dirBase, v) : v;
      if (FileBundle.isLocalPath(resolved)) out.push(resolved);
    }
  }
  return out;
}

/**
 * v2.20.0：从 chunked 分块清单 manifest（collision / terrain / npcs region）提取内部资源相对路径。
 *
 * 覆盖三种 manifest（结构对齐 SDK gs.schema.ts / npc-region-schema.ts）：
 * - collision：chunkedCollisionManifestSchema —— `modules[].url`（碰撞 GLB）
 * - terrain：chunkedTerrainManifestSchema —— `modules[].url`（R16 瓦片）+ 顶层 `r16Url`
 *   （single 模式整张 R16）
 * - npcs：npcRegionManifestSchema —— `regions[].configFile`（区域清单 JSON，其内部
 *   models[].modelFilePath 引用由 extractNpcsConfigResourcePaths 在 configFile 登记后递归处理）
 *
 * 解析规则对齐 SDK loader（`url.startsWith('http') ? url : baseUrl + url`）：绝对 URL
 * （http/data/blob）视为非本地不收集。编辑器以「授权根（页面根 = meta.json 目录）」为基准：
 * baseUrl 缺省空串 = 授权根，`joinRelativePath(baseUrl, seg)` 拼模块 url（纯前缀，不拼
 * manifest 目录，对齐 SDK buildChunkModule 不 resolveUrl）。
 *
 * @param cfgPath manifest 的 FileBundle key（如 `'assets/collision-chunks.json'`）
 * @param entry manifest 文件字节（Blob / Uint8Array）
 * @param kind 清单类型（决定内部引用结构）
 */
async function extractChunkedManifestResourcePaths(
  cfgPath: string,
  entry: Blob | Uint8Array,
  kind: 'collision' | 'terrain' | 'npcs',
): Promise<string[]> {
  let text: string;
  try {
    text =
      entry instanceof Blob ? await new Response(entry).text() : new TextDecoder('utf-8').decode(entry as Uint8Array);
  } catch {
    return [];
  }
  let parsed: {
    baseUrl?: unknown;
    modules?: unknown;
    r16Url?: unknown;
    regions?: unknown;
  } | null = null;
  try {
    parsed = JSON.parse(text);
  } catch {
    return [];
  }
  if (!parsed || typeof parsed !== 'object' || (!Array.isArray(parsed.modules) && !Array.isArray(parsed.regions))) {
    return [];
  }

  // v2.25.0 守卫（对齐 v2.22.0 regionReplace 同款）：manifest.baseUrl 为绝对 URL（远程
  // CDN）时，模块属"远程引用"——SDK 运行时直接按 CDN 地址 fetch，编辑器不应把它当本地
  // 目录拼（此前 joinRelativePath(dirname, 'https://…') 会生成 `…/https://…` 畸形 key，
  // round-trip 后 FileBundle key 与 zip 条目错位 → 误弹"资源未加载"授权框）。若导出前
  // 已完成本地化改写（manifest.baseUrl 被改为相对镜像路径并覆盖登记），此处 baseUrl 非
  // 绝对 → 走正常相对推导。chunked 三类（collision/terrain/npcs region）统一语义。
  const chunkedRawBaseUrl = typeof parsed.baseUrl === 'string' ? parsed.baseUrl : '';
  if (FileBundle.isAbsoluteUrl(chunkedRawBaseUrl)) return [];

  const out: string[] = [];
  // v2.36.0 对齐 SDK chunked 纯前缀拼接语义：manifest.baseUrl 相对「授权根（页面根）」
  // 而非 manifest 目录（SDK buildChunkModule 用 `baseUrl + seg` 原样拼接、不 resolveUrl），
  // 故此处不拼 dirname(cfgPath)。baseUrl 缺省空串 = 授权根。
  const base = chunkedRawBaseUrl || '';
  const push = (seg: string): void => {
    if (!seg) return;
    // 绝对 URL（SDK 直连远程）不收集、不打包
    if (/^(https?:\/\/|data:|blob:)/i.test(seg)) return;
    const resolved = FileBundle.joinRelativePath(base, seg);
    if (FileBundle.isLocalPath(resolved)) out.push(resolved);
  };

  if (kind === 'collision' || kind === 'terrain') {
    // modules[].url：collision → 碰撞 GLB；terrain → R16 瓦片
    for (const mod of Array.isArray(parsed.modules) ? parsed.modules : []) {
      if (!mod || typeof mod !== 'object') continue;
      const url = (mod as Record<string, unknown>).url;
      if (typeof url === 'string' && url) push(url);
    }
    // terrain single 模式：整张 R16（r16Url 相对 baseUrl 解析，与 SDK terrain-dimension 一致）
    if (kind === 'terrain' && typeof parsed.r16Url === 'string' && parsed.r16Url) {
      push(parsed.r16Url);
    }
  } else if (kind === 'npcs') {
    // regions[].configFile：区域清单 JSON。configFile 未登记 → 收集路径待授权补读；
    // 已登记（早前授权/导入过）→ 递归其内部 models 引用（extractNpcsConfigResourcePaths
    // 相对 configFile 所在目录解析），保证 collect 导出与多层补读覆盖到第三层。
    for (const region of Array.isArray(parsed.regions) ? parsed.regions : []) {
      if (!region || typeof region !== 'object') continue;
      const configFileRaw = (region as Record<string, unknown>).configFile;
      if (typeof configFileRaw !== 'string' || !configFileRaw) continue;
      if (/^(https?:\/\/|data:|blob:)/i.test(configFileRaw)) continue; // 远程 region 不收集
      const configFilePath = FileBundle.joinRelativePath(base, configFileRaw);
      if (!FileBundle.isLocalPath(configFilePath)) continue;
      out.push(configFilePath);
      const cfgEntry = FileBundle.get(configFilePath);
      if (cfgEntry) {
        try {
          const deeper = await extractNpcsConfigResourcePaths(configFilePath, cfgEntry);
          out.push(...deeper);
        } catch {
          // 单个区域解析失败不阻断其他区域
        }
      }
    }
  }
  return out;
}

/**
 * v2.21.0：嗅探 npcs.chunkedUrl 收到的文件是否为 legacy NPC 清单（而非 region manifest）。
 *
 * 判断依据：legacy 清单顶层含 `models[]` / `list[]`（单文件 NPC 配置），而 region manifest
 * 顶层是 `regions[]`（外链多区域）。chunked 提取器只认 regions——legacy 清单被误传进
 * chunkedUrl 时提取 0 引用且无任何引导，用户会静默导出缺资源。此函数供
 * promptLoadReferencedConfigAssets 在上传后给出「切回 Legacy 变体填 configFile」提示。
 *
 * @param entry npcs.chunkedUrl 登记的文件字节
 * @returns true = 内容是 legacy 清单（应切 legacy 变体）；false = region manifest 或不可解析
 */
async function sniffNpcsChunkedMismatch(entry: Blob | Uint8Array): Promise<boolean> {
  let text: string;
  try {
    text =
      entry instanceof Blob ? await new Response(entry).text() : new TextDecoder('utf-8').decode(entry as Uint8Array);
  } catch {
    return false;
  }
  let parsed: { regions?: unknown; models?: unknown; list?: unknown } | null = null;
  try {
    parsed = JSON.parse(text);
  } catch {
    return false;
  }
  if (!parsed || typeof parsed !== 'object') return false;
  // 有 regions → 是 region manifest，形态正确
  if (Array.isArray(parsed.regions)) return false;
  // 有 legacy 特征字段（models/list）且无 regions → 是 legacy 清单
  return Array.isArray(parsed.models) || Array.isArray(parsed.list);
}

/**
 * 从 region-replace-config.json 提取模块资源相对路径（第二层引用）。
 *
 * 资源来源（对齐 SDK RegionReplaceStrategy.loadRegionReplaceConfig 的组装逻辑）：
 * 1. `modules[].ply_name`（数组/字符串，缺省回退 `module.name`）—— 地块文件
 * 2. `modules[].collision_name[]` —— 碰撞 GLB（相对 baseUrl 拼接）
 * 3. `modules[].mortonConfig`（显式字段，或 `config.morton=true` 时运行时生成
 *    `baseUrl + name + '.morton'`）
 *
 * 路径推导复用 FileBundle.resolveFileSegToRelPath（与 SDK resolveFileSegToUrl 规则对齐：
 * 消化 ./ ../、按 fileType 补扩展名），返回「相对授权根」的路径。
 *
 * @param cfgPath FileBundle key（如 `'region-replace/config.json'`），用于推导 config 所在目录
 * @param entry config 文件字节（Blob / Uint8Array）
 */
async function extractRegionReplaceResourcePaths(cfgPath: string, entry: Blob | Uint8Array): Promise<string[]> {
  let text: string;
  try {
    text =
      entry instanceof Blob ? await new Response(entry).text() : new TextDecoder('utf-8').decode(entry as Uint8Array);
  } catch {
    return [];
  }
  let parsed: {
    baseUrl?: unknown;
    fileType?: unknown;
    morton?: unknown;
    modules?: unknown;
  } | null = null;
  try {
    parsed = JSON.parse(text);
  } catch {
    return [];
  }
  if (!parsed || typeof parsed !== 'object' || !Array.isArray(parsed.modules)) return [];

  // v2.22.0 守卫：baseUrl 为绝对 URL（远程 CDN）时，模块属"远程引用"——SDK 运行时直接
  // 按 CDN 地址 fetch，编辑器不应把它当本地目录拼（此前 joinRelativePath(dirBase, 'https://…')
  // 会生成 `region-replace/https://…` 畸形 key，round-trip 后 FileBundle key 与 zip 条目
  // 错位 → 弹"资源未加载"授权框）。若导出前已完成本地化改写（config.baseUrl 被改为相对
  // 镜像路径并覆盖登记），此处 baseUrl 非绝对 → 走正常相对推导。
  const rawBaseUrl = typeof parsed.baseUrl === 'string' ? parsed.baseUrl : '';
  if (FileBundle.isAbsoluteUrl(rawBaseUrl)) return [];

  const out: string[] = [];
  const push = (p: string | null): void => {
    if (p && FileBundle.isLocalPath(p)) out.push(p);
  };

  const dirBase = FileBundle.dirname(cfgPath);
  const base = FileBundle.joinRelativePath(dirBase, rawBaseUrl || './');
  const fileType = typeof parsed.fileType === 'string' ? parsed.fileType : '';
  const mortonEnabled = parsed.morton === true;

  for (const mod of parsed.modules) {
    if (!mod || typeof mod !== 'object') continue;
    const m = mod as Record<string, unknown>;
    const name = typeof m.name === 'string' ? m.name : '';
    // ply_name：数组 / 字符串 / 缺省回退 name
    let plyNames: string[] = [];
    if (Array.isArray(m.ply_name)) {
      plyNames = m.ply_name.filter((n): n is string => typeof n === 'string' && n.length > 0);
    } else if (typeof m.ply_name === 'string' && m.ply_name) {
      plyNames = [m.ply_name];
    } else if (name) {
      plyNames = [name];
    }
    for (const seg of plyNames) push(FileBundle.resolveFileSegToRelPath(seg, base, fileType));
    // collision_name
    if (Array.isArray(m.collision_name)) {
      for (const seg of m.collision_name) {
        if (typeof seg === 'string' && seg) push(FileBundle.resolveFileSegToRelPath(seg, base, fileType));
      }
    }
    // mortonConfig：显式字段优先；否则 morton=true 时按运行时规则生成
    if (typeof m.mortonConfig === 'string' && m.mortonConfig) {
      push(FileBundle.resolveFileSegToRelPath(m.mortonConfig, base, fileType));
    } else if (mortonEnabled && name) {
      push(FileBundle.joinRelativePath(base, `${name}.morton`));
    }
  }
  return out;
}

/** 一次远程下载任务：远程 URL → FileBundle 镜像 key */
interface RemoteDownloadJob {
  remoteUrl: string;
  localKey: string;
}

/**
 * 通用「导出前远程模块下载」执行器（v2.26.0，regionReplace / chunked 共用）。
 *
 * - 挂起 preview 重建：每个 register 都改变 FileBundle fingerprint → PreviewPanel force watch
 *   每次全量 rebuild（N 文件 = N 次刷新）。configPendingLoad 期间 scheduleRebuild 跳过一切
 *   重建（含 force）；下载完成置 false 由 watch(configPendingLoad) 统一强制重建一次。
 * - FileBundle 已有镜像 key → 复用跳过（授权目录 / 早前下载场景）
 * - 任一文件下载失败 → 停止、toast、返回 false（调用方保留远程引用原样导出）
 */
async function downloadRemoteJobs(
  jobs: RemoteDownloadJob[],
  ui: { title: string; failTitle: string; failMessage: string },
): Promise<boolean> {
  if (jobs.length === 0) return true;
  configPendingLoad.value = true;
  const busy = beginBusy({ title: ui.title, detail: '准备下载...', percent: 0 });
  try {
    let ok = true;
    for (let i = 0; i < jobs.length; i++) {
      const job = jobs[i];
      if (FileBundle.has(job.localKey)) {
        busy.update({ detail: `复用 ${job.localKey.split('/').pop()}`, percent: ((i + 1) / jobs.length) * 100 });
        continue;
      }
      try {
        busy.update({
          detail: `下载 ${job.localKey.split('/').pop() || job.remoteUrl}`,
          percent: (i / jobs.length) * 100,
        });
        const resp = await fetch(job.remoteUrl);
        if (!resp.ok) {
          ok = false;
          break;
        }
        const bytes = new Uint8Array(await resp.arrayBuffer());
        FileBundle.register(job.localKey, bytes);
      } catch {
        ok = false;
        break;
      }
    }
    if (!ok) {
      pushToast({
        type: 'warn',
        title: ui.failTitle,
        message: ui.failMessage,
        duration: 6000,
      });
      return false;
    }
    return true;
  } finally {
    busy.end();
    configPendingLoad.value = false;
  }
}

/**
 * v2.22.0：region-replace 远程 baseUrl 导出本地化。
 *
 * 场景：config 的 baseUrl 是**绝对 CDN URL**（如 `https://mogs-…cos…/mogs/…/`），用户本地
 * 没有模块文件、运行时靠 SDK 直接 fetch CDN。此前导出 zip 时 collect 把 `https://` 当相对
 * 目录拼出 `region-replace/https://…` 畸形 key → round-trip 后 FileBundle key 与 zip 条目错位
 * → 再导入/再导出弹「资源未加载」授权框。
 *
 * 本函数在导出前把这种「远程引用 config」改写成**本地镜像引用**：
 * 1. 逐个模块 seg（ply_name / collision_name / mortonConfig）用对齐 SDK 的规则解析成最终
 *    CDN URL（resolveRemoteFileSegToUrl），再换算成「config 目录下的镜像相对 key」
 *    （resolveRemoteFileSegToRelPath——绝对 baseUrl 去掉 scheme+host 后的 path 段挂到
 *    config 所在目录，`.splat/.glb` 等文件打进 zip 后 SDK 部署在该目录即可离线命中）；
 * 2. FileBundle 已有该镜像 key 的文件 → 复用（授权目录/zip 导入场景）；否则 fetch 下载；
 * 3. 全部成功 → 改写 config.baseUrl 为镜像相对路径，并把改写后的 config 字节**覆盖登记**
 *    回 FileBundle——此后 collectLocalPathsInMeta 解析 config 时 baseUrl 是相对值，推导出
 *    的就是上述干净镜像 key（与 zip 内布局自洽，round-trip 稳定）；
 * 4. 任一文件下载失败 → 不改写 config（保留远程 baseUrl），zip 仍原样导出远程引用——
 *    SDK 运行时走 CDN 加载；若 CDN 也不可达则场景本就加载不出来（用户可接受语义）。
 *
 * @param value 当前 meta（含 gaussianSplatting.regionReplaceConfigPath 本地路径）
 * @returns 是否已成功本地化（false 表示保留远程引用原样导出）
 */
async function ensureLocalizedRemoteRegionReplace(value: any): Promise<boolean> {
  const rrPath = value?.gaussianSplatting?.regionReplaceConfigPath;
  if (typeof rrPath !== 'string' || !rrPath || !FileBundle.isLocalPath(rrPath)) return true;
  const entry = FileBundle.get(rrPath);
  if (!entry) return true;

  let text: string;
  try {
    text =
      entry instanceof Blob ? await new Response(entry).text() : new TextDecoder('utf-8').decode(entry as Uint8Array);
  } catch {
    return true;
  }
  let parsed: {
    baseUrl?: unknown;
    fileType?: unknown;
    morton?: unknown;
    modules?: unknown;
  } | null = null;
  try {
    parsed = JSON.parse(text);
  } catch {
    return true;
  }
  if (!parsed || typeof parsed !== 'object' || !Array.isArray(parsed.modules)) return true;
  const rawBaseUrl = typeof parsed.baseUrl === 'string' ? parsed.baseUrl : '';
  if (!FileBundle.isAbsoluteUrl(rawBaseUrl)) return true; // 非远程引用无需本地化

  // 收集所有待下载资源段 → { remoteUrl, localKey }
  const fileType = typeof parsed.fileType === 'string' ? parsed.fileType : '';
  const mortonEnabled = parsed.morton === true;
  const jobs: { remoteUrl: string; localKey: string }[] = [];
  const seen = new Set<string>();
  const collectSeg = (seg: string): void => {
    const localKey = FileBundle.resolveRemoteFileSegToRelPath(seg, rrPath, rawBaseUrl, fileType);
    const remoteUrl = FileBundle.resolveRemoteFileSegToUrl(seg, rawBaseUrl, fileType);
    if (!localKey || !remoteUrl) return;
    if (seen.has(localKey)) return;
    seen.add(localKey);
    jobs.push({ remoteUrl, localKey });
  };
  for (const mod of parsed.modules as Record<string, unknown>[]) {
    if (!mod || typeof mod !== 'object') continue;
    const name = typeof mod.name === 'string' ? mod.name : '';
    let plyNames: string[] = [];
    if (Array.isArray(mod.ply_name)) {
      plyNames = (mod.ply_name as unknown[]).filter((n): n is string => typeof n === 'string' && n.length > 0);
    } else if (typeof mod.ply_name === 'string' && mod.ply_name) {
      plyNames = [mod.ply_name];
    } else if (name) {
      plyNames = [name];
    }
    for (const seg of plyNames) collectSeg(seg);
    if (Array.isArray(mod.collision_name)) {
      for (const seg of mod.collision_name as unknown[]) {
        if (typeof seg === 'string' && seg) collectSeg(seg);
      }
    }
    if (typeof mod.mortonConfig === 'string' && mod.mortonConfig) {
      collectSeg(mod.mortonConfig);
    } else if (mortonEnabled && name) {
      const localKey = FileBundle.resolveRemoteFileSegToRelPath(`${name}.morton`, rrPath, rawBaseUrl, fileType);
      const remoteUrl = FileBundle.resolveRemoteFileSegToUrl(`${name}.morton`, rawBaseUrl, fileType);
      if (localKey && remoteUrl && !seen.has(localKey)) {
        seen.add(localKey);
        jobs.push({ remoteUrl, localKey });
      }
    }
  }
  if (jobs.length === 0) return true;

  // 下载远程模块（v2.24.0 挂起防抖逻辑下沉通用 downloadRemoteJobs，v2.26.0 起 regionReplace
  // 与 chunked 共用）：每个文件 register 都改变 fingerprint → 若不挂起，PreviewPanel force
  // watch（v1.23.0 纳入 fingerprint）每次全量 rebuild（N 文件 = N 次刷新，且每次是资源未齐
  // 中间态）。helper 内统一 configPendingLoad 挂起 + BusyOverlay 进度 + 失败 toast（保留远程引用）。
  if (
    !(await downloadRemoteJobs(jobs, {
      title: '下载远程地块资源',
      failTitle: '远程地块下载失败',
      failMessage: '部分远程模块未能下载，导出将保留远程 CDN 引用（zip 不含地块文件）。',
    }))
  ) {
    return false;
  }

  // 全部成功 → 改写 baseUrl 为镜像相对路径并覆盖登记 config（register 只接受 File/Uint8Array）
  parsed.baseUrl = FileBundle.absoluteUrlToRelPath(rawBaseUrl);
  const rewrittenBytes = new TextEncoder().encode(JSON.stringify(parsed, null, 2));
  FileBundle.register(rrPath, rewrittenBytes);
  return true;
}

/**
 * v2.26.0：chunked 远程 baseUrl 导出本地化（编辑器统一，配套 file-bundle v1.8.0）。
 *
 * 与 ensureLocalizedRemoteRegionReplace 同语义，覆盖 collision / terrain / npcs 三类
 * chunked manifest（collision.chunkedUrl / terrain.chunkedUrl / npcs.chunkedUrl）：
 * - collision：modules[].url（碰撞 GLB）
 * - terrain：modules[].url（R16 瓦片）+ 顶层 r16Url（single 模式整张）
 * - npcs：regions[].configFile（区域二级清单 JSON）→ 下载后**递归**其内部
 *   modelFilePath / imagePath 等相对引用（相对 configFile 所在镜像目录解析）
 *
 * 模块段 URL 对齐 SDK chunk dimension 的**纯前缀拼接**（resolveRemoteChunkedSegToUrl），
 * 镜像 key 用 resolveRemoteChunkedSegToRelPath（与 collect 端 extractChunkedManifestResourcePaths
 * 同 joinRelativePath 推导，round-trip 自洽）。全部成功 → 改写 manifest.baseUrl 为镜像
 * 相对路径并覆盖登记；任一失败 → 保留远程引用原样导出（collect 守卫对绝对 baseUrl 返回空）。
 *
 * @param value 当前 meta（含 collision/terrain/npcs 三处 chunkedUrl 本地路径）
 */
async function ensureLocalizedRemoteChunkedManifests(value: any): Promise<void> {
  const refs: { path: unknown; kind: 'collision' | 'terrain' | 'npcs' }[] = [];
  // ⚠️ 兼容 chunks 收编形态（v2.39.7）：SDK v1.15.0 起 chunk 声明迁入 `维度.chunks.chunkedUrl`，
  // 真实路径是 `npcs.chunks.chunkedUrl`（旧扁平 `npcs.chunkedUrl` 仅存于早期数据）。
  // 原实现只读扁平路径 → chunks 模式下 refs 恒空 → 远程清单**完全不下载**、不本地化 →
  // 导出包缺 manifest 内部资源（表现为「打包导出时也不会下载下来」）。
  for (const kind of ['collision', 'terrain', 'npcs'] as const) {
    const node = value?.[kind] as { chunks?: { chunkedUrl?: unknown }; chunkedUrl?: unknown } | undefined;
    if (!node || typeof node !== 'object') continue;
    const chunkedPath = node.chunks?.chunkedUrl ?? node.chunkedUrl;
    if (typeof chunkedPath === 'string' && chunkedPath) {
      refs.push({ path: chunkedPath, kind });
    }
  }

  for (const { path: rawPath, kind } of refs) {
    if (typeof rawPath !== 'string' || !FileBundle.isLocalPath(rawPath)) continue;
    const manifestPath = rawPath;
    const manifestEntry = FileBundle.get(manifestPath);
    if (!manifestEntry) continue;

    let text: string;
    try {
      text =
        manifestEntry instanceof Blob
          ? await new Response(manifestEntry).text()
          : new TextDecoder('utf-8').decode(manifestEntry as Uint8Array);
    } catch {
      continue;
    }
    let parsed: { baseUrl?: unknown; modules?: unknown; regions?: unknown; r16Url?: unknown } | null = null;
    try {
      parsed = JSON.parse(text);
    } catch {
      continue;
    }
    if (!parsed || typeof parsed !== 'object') continue;
    const rawBaseUrl = typeof parsed.baseUrl === 'string' ? parsed.baseUrl : '';
    if (!FileBundle.isAbsoluteUrl(rawBaseUrl)) continue; // 非远程引用无需本地化

    // 收集本轮待下载任务（modules[].url / r16Url / regions[].configFile）
    const jobs: RemoteDownloadJob[] = [];
    const seen = new Set<string>();
    const collectSeg = (seg: string): void => {
      if (!seg) return;
      const localKey = FileBundle.resolveRemoteChunkedSegToRelPath(seg, manifestPath, rawBaseUrl);
      const remoteUrl = FileBundle.resolveRemoteChunkedSegToUrl(seg, rawBaseUrl);
      if (!localKey || !remoteUrl) return;
      if (seen.has(localKey)) return;
      seen.add(localKey);
      jobs.push({ remoteUrl, localKey });
    };

    if (kind === 'collision' || kind === 'terrain') {
      for (const mod of Array.isArray(parsed.modules) ? parsed.modules : []) {
        if (!mod || typeof mod !== 'object') continue;
        const url = (mod as Record<string, unknown>).url;
        if (typeof url === 'string' && url) collectSeg(url);
      }
      // terrain single 模式：整张 R16（r16Url 相对 baseUrl 解析，与 SDK terrain-dimension 一致）
      if (kind === 'terrain' && typeof parsed.r16Url === 'string' && parsed.r16Url) {
        collectSeg(parsed.r16Url);
      }
    } else if (kind === 'npcs') {
      // regions[].configFile：区域二级清单 JSON。configFile 相对 baseUrl 下载到镜像 key；
      // 登记后由下方 collectNpcsConfigInnerRefs 递归其内部 modelFilePath/imagePath 相对引用
      // （相对 configFile 所在镜像目录解析，与 SDK 以 configFile URL 目录为基准一致）。
      for (const region of Array.isArray(parsed.regions) ? parsed.regions : []) {
        if (!region || typeof region !== 'object') continue;
        const configFile = (region as Record<string, unknown>).configFile;
        if (typeof configFile === 'string' && configFile) collectSeg(configFile);
      }
    }
    if (jobs.length === 0) continue;

    if (
      !(await downloadRemoteJobs(jobs, {
        title: `下载远程 ${kind === 'npcs' ? 'NPC 区域' : kind === 'terrain' ? '地形' : '碰撞'}资源`,
        failTitle: '远程资源下载失败',
        failMessage: `部分远程 ${kind} 模块未能下载，导出将保留远程 CDN 引用（zip 不含模块文件）。`,
      }))
    ) {
      continue; // 保留远程引用，处理下一个 manifest
    }

    // npcs：configFile 下载登记后，递归收集其内部 modelFilePath/imagePath 等相对引用并下载
    if (kind === 'npcs') {
      const innerJobs: RemoteDownloadJob[] = [];
      const innerSeen = new Set<string>();
      for (const region of Array.isArray(parsed.regions) ? parsed.regions : []) {
        if (!region || typeof region !== 'object') continue;
        const configFile = (region as Record<string, unknown>).configFile;
        if (typeof configFile !== 'string' || !configFile) continue;
        const configFileKey = FileBundle.resolveRemoteChunkedSegToRelPath(configFile, manifestPath, rawBaseUrl);
        if (!configFileKey) continue;
        await collectNpcsConfigInnerRefs(configFileKey, rawBaseUrl + configFile, innerJobs, innerSeen);
      }
      if (innerJobs.length > 0) {
        await downloadRemoteJobs(innerJobs, {
          title: '下载远程 NPC 模型资源',
          failTitle: '远程 NPC 资源下载失败',
          failMessage: '部分远程 NPC 模型/贴图未能下载，导出将保留远程 CDN 引用。',
        });
      }
    }

    // 全部成功 → 改写 baseUrl 为镜像相对路径并覆盖登记 manifest
    parsed.baseUrl = FileBundle.absoluteUrlToRelPath(rawBaseUrl);
    const rewrittenBytes = new TextEncoder().encode(JSON.stringify(parsed, null, 2));
    FileBundle.register(manifestPath, rewrittenBytes);
  }
}

/**
 * v2.26.0：递归收集 npcs 区域 configFile 内部的模型/贴图等相对引用并登记下载任务。
 *
 * configFile（如 `plaza.json`）内部 models[].modelFilePath / imagePath / dialogues[].audio
 * 相对 **configFile 所在 URL 目录**引用（SDK resolveNPCFileConfigPaths 以 configFile URL
 * extractBaseUrl 为基准）。本地化时 configFile 已下载到镜像 key——内部相对引用以该镜像
 * 目录为基准（joinRelativePath(dirname(configFileKey), rel)）登记，远程 URL 以 configFile
 * 远程 URL 目录为基准（new URL(rel, configFileRemoteUrl)）下载。
 *
 * @param configFileKey configFile 的 FileBundle 镜像 key
 * @param configFileRemoteUrl configFile 的完整远程 URL（baseUrl + configFile）
 * @param out 收集到的下载任务
 * @param seen 已收集 key 集合
 */
async function collectNpcsConfigInnerRefs(
  configFileKey: string,
  configFileRemoteUrl: string,
  out: RemoteDownloadJob[],
  seen: Set<string>,
): Promise<void> {
  const entry = FileBundle.get(configFileKey);
  if (!entry) return;
  let text: string;
  try {
    text =
      entry instanceof Blob ? await new Response(entry).text() : new TextDecoder('utf-8').decode(entry as Uint8Array);
  } catch {
    return;
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return;
  }
  if (!parsed || typeof parsed !== 'object') return;

  const configFileDir = FileBundle.dirname(configFileKey);
  // configFile 远程目录：去掉文件名部分（SDK extractBaseUrl 语义）
  const remoteDir = (() => {
    const idx = configFileRemoteUrl.lastIndexOf('/');
    return idx >= 0 ? configFileRemoteUrl.slice(0, idx + 1) : configFileRemoteUrl;
  })();

  const stack: unknown[] = [parsed];
  const visited = new Set<object>();
  while (stack.length > 0) {
    const node = stack.pop();
    if (!node || typeof node !== 'object') continue;
    if (visited.has(node as object)) continue;
    visited.add(node as object);
    if (Array.isArray(node)) {
      for (const item of node) stack.push(item);
      continue;
    }
    for (const [field, v] of Object.entries(node as Record<string, unknown>)) {
      if (v !== null && typeof v === 'object') {
        stack.push(v);
        continue;
      }
      if (typeof v !== 'string' || !v) continue;
      if (resolveResourceBundleDir(field.toLowerCase()) === null) continue;
      if (!FileBundle.isLocalPath(v)) continue; // 远程绝对 URL 不下载（保留远程引用）
      const localKey = FileBundle.joinRelativePath(configFileDir, v);
      let remoteUrl: string | null = null;
      try {
        remoteUrl = new URL(v, remoteDir).href;
      } catch {
        remoteUrl = null;
      }
      if (!remoteUrl || seen.has(localKey)) continue;
      seen.add(localKey);
      out.push({ remoteUrl, localKey });
    }
  }
}

/**
 * 递归遍历 widget schema，收集所有标记了 bundleDir 的 FieldUrl 字段的绝对路径。
 *
 * 绝对路径 = `widget.rootPath` + `field.path` 拼接（中间用 `.`）。
 * 注意：只递归 `group.children`；array 的 itemSchema / union 的 variants / auto-object
 * 的 recordValueSchema **无法**静态反查（动态 key / 变体路径），由
 * collectLocalPathsInMeta 第 3 步的深度遍历兜底覆盖。
 */
function collectBundleFieldPaths(widgets: WidgetSchema[], _basePath: string, out: string[]): void {
  for (const w of widgets) {
    if (!w.fields) continue;
    walkFields(w.fields, w.rootPath || '', out);
  }
}

function walkFields(fields: any[], basePath: string, out: string[]): void {
  for (const f of fields) {
    if (!f || typeof f !== 'object') continue;
    const fPath = f.path || '';
    const abs = joinPath(basePath, fPath);

    if (f.type === 'url' && f.bundleDir) {
      out.push(abs);
    } else if (f.type === 'group' && Array.isArray(f.children)) {
      walkFields(f.children, abs, out);
    }
    // 注：interactionZones 的 shape.mesh.url（Record/数组内）由 collectLocalPathsInMeta
    // 的第 3 步直接扫描 meta 数据收集，不走 walkFields（Record key 动态、schema 无法反查实例路径）。
  }
}

function joinPath(a: string, b: string): string {
  if (!a) return b;
  if (!b) return a;
  return `${a}.${b}`;
}

/**
 * "是否丢弃未保存内容"防呆。
 *
 * 触发条件：仅当 isDirty（meta 相对 pristine 快照有变更）时弹自定义 Confirm 对话框。
 * - 空白态 / 加载后未编辑：直接放行不打扰
 * - 真实有改动：弹 ConfirmDialog（异步等待用户决策）
 *
 * 使用 confirmDialog（自定义对话框）而不是 window.confirm 的原因：
 * - 视觉与编辑器暗色主题一致，居中显示，焦点自动落在"确定"按钮
 * - Esc / Enter 键支持
 * - 浏览器原生 confirm 在某些设备上"阻止后续脚本"行为不一致
 */
async function confirmDiscardIfDirty(title: string, message: string): Promise<boolean> {
  if (!isDirty.value) return true;
  return confirmDialog({
    title,
    message,
    okText: '继续',
    cancelText: '取消',
    variant: 'danger',
  });
}

/**
 * 浏览器关闭/刷新页面时的防丢提示。
 *
 * 使用 beforeunload 标准事件：现代浏览器要求同时设置 preventDefault() 和 returnValue
 * 才会显示原生确认弹窗（文案由浏览器决定，不能自定义；我们只决定是否提醒）。
 *
 * 注意：returnValue 在标准上已 deprecated，但所有主流浏览器（Chrome/Firefox/Safari/Edge）
 * 仍要求这个属性才会显示提示——是事实标准。这里 ts-ignore 抑制弃用警告。
 */
const onBeforeUnload = (e: BeforeUnloadEvent) => {
  if (isDirty.value) {
    e.preventDefault();
    // returnValue 已 deprecated 但浏览器仍要求设置才显示弹窗，是事实标准
    // eslint-disable-next-line @typescript-eslint/no-deprecated, deprecation/deprecation
    e.returnValue = '';
  }
};
