<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount } from 'vue';
import { Box, ChevronDown, FilePlus, Upload, Download, FolderKanban, Sparkles, Save, RefreshCw } from 'lucide-vue-next';

const props = defineProps<{
  projectName: string;
  /** 是否有未保存修改（决定项目名旁是否显示橙点） */
  dirty?: boolean;
  /** 是否处于托管工作区模式（决定文件菜单显示「保存/从磁盘重载」及 Ctrl+S 语义） */
  workspaceMode?: boolean;
}>();

/** 文件菜单 / 快捷键统一通过 action 事件向上抛 */
type FileAction = 'new' | 'import' | 'export' | 'load-example' | 'load-assets-dir' | 'save' | 'reload';
const emit = defineEmits<{
  (e: 'action', action: FileAction): void;
}>();

const openMenu = ref<'file' | 'edit' | null>(null);

const toggleMenu = (name: 'file' | 'edit') => {
  openMenu.value = openMenu.value === name ? null : name;
};

const onAction = (action: FileAction) => {
  emit('action', action);
  openMenu.value = null;
};

const closeMenuOnOutside = (e: MouseEvent) => {
  const target = e.target as HTMLElement;
  if (!target.closest('.menu-item')) {
    openMenu.value = null;
  }
};

/**
 * 全局快捷键监听。
 * - Ctrl/Cmd + N → 新建
 * - Ctrl/Cmd + O → 导入
 * - Ctrl/Cmd + S → 托管模式保存写回磁盘 / 非托管导出文件
 *
 * 注意：浏览器对 Ctrl+N / Ctrl+O 默认会接管（新窗口 / 打开文件），
 * 必须 preventDefault 才能拦住。这是 demo 内显式约定的行为。
 */
const onKeyDown = (e: KeyboardEvent) => {
  if (!(e.ctrlKey || e.metaKey)) return;
  const k = e.key.toLowerCase();
  if (k === 'n') {
    e.preventDefault();
    emit('action', 'new');
  } else if (k === 'o') {
    e.preventDefault();
    emit('action', 'import');
  } else if (k === 's') {
    e.preventDefault();
    emit('action', props.workspaceMode ? 'save' : 'export');
  }
};

onMounted(() => {
  document.addEventListener('click', closeMenuOnOutside);
  window.addEventListener('keydown', onKeyDown);
});

onBeforeUnmount(() => {
  document.removeEventListener('click', closeMenuOnOutside);
  window.removeEventListener('keydown', onKeyDown);
});
</script>

